// ---> NEW: AEGIS PREEMPTIVE CPU CONTEXT <---
typedef struct {
    /* SAVE_GPRS order from idt.s, followed by the five-qword long-mode IRET frame. */
    uint64_t r15, r14, r13, r12, r11, r10, r9, r8;
    uint64_t rbp, rdi, rsi, rdx, rcx, rbx, rax;
    uint64_t rip, cs, rflags;
    /* In 64-bit mode IRETQ consumes RSP and SS for same-CPL and privilege returns. */
    uint64_t rsp, ss;
} cpu_context_t;

_Static_assert(offsetof(cpu_context_t, rip) == 15U * sizeof(uint64_t),
               "timer GPR save order must match cpu_context_t");
_Static_assert(offsetof(cpu_context_t, rsp) == 18U * sizeof(uint64_t),
               "long-mode IRET RSP/SS tail must follow RIP/CS/RFLAGS");

typedef struct {
    uint32_t id;
    int state;               // 0: FREE, 1: RUNNING, 2: PAUSED
    uint32_t time_slice;     
    cpu_context_t* context;  
} preemptive_thread_t;

preemptive_thread_t thread_pool[MAX_TASKS];

