/* AHCI PRDT entries are 16 bytes: DBA, DBAU, reserved, and DBC/IOC. */
typedef struct {
    uint32_t dba;
    uint32_t dbau;
    uint32_t reserved;
    uint32_t dbc_ioc;
} __attribute__((packed)) ahci_prdt_entry_t;

typedef struct {
    uint8_t  cfis[64];
    uint8_t  acmd[16];
    uint8_t  rsv[48];
    ahci_prdt_entry_t prdt_entry[1];
} __attribute__((packed)) ahci_cmd_tbl_t;

_Static_assert(sizeof(ahci_prdt_entry_t) == 16U,
               "AHCI PRDT entry must be exactly 16 bytes");
_Static_assert(offsetof(ahci_cmd_tbl_t, prdt_entry) == 128U,
               "AHCI PRDT must begin at command-table offset 128");

