/* LUNA public ABI structures.  These are intentionally independent of
 * POSIX types so native applications do not have to adopt the POSIX model. */
typedef struct {
    const char* path;
    uint32_t flags;
} luna_open_args_t;

typedef struct {
    uint32_t handle;
    void* buffer;
    uint32_t length;
} luna_io_args_t;

typedef struct {
    const char* path;
    void* entries;
    uint32_t capacity;
} luna_list_args_t;

typedef struct {
    const char* path;
    void* out_stat;
} luna_stat_args_t;

typedef struct {
    uint32_t kind;
    uint32_t mode;
    uint64_t size;
    uint64_t capabilities;
    uint32_t generation;
    char name[48];
} luna_stat_t;

typedef struct {
    uint32_t inode;
    uint8_t kind;
    uint8_t flags;
    uint16_t name_len;
    uint64_t size;
    char name[48];
} luna_dirent_t;

