// Byte order helpers
uint16_t htons(uint16_t val) { return (val << 8) | (val >> 8); }
uint16_t ntohs(uint16_t val) { return htons(val); }
uint32_t htonl(uint32_t val) {
    return ((val & 0xFF000000) >> 24) |
           ((val & 0x00FF0000) >> 8)  |
           ((val & 0x0000FF00) << 8)  |
           ((val & 0x000000FF) << 24);
}
uint32_t ntohl(uint32_t val) { return htonl(val); }

// IP Checksum Calculation
uint16_t net_checksum(void* addr, int count) {
    uint32_t sum = 0;
    uint16_t* ptr = (uint16_t*)addr;
    while (count > 1) {
        sum += *ptr++;
        count -= 2;
    }
    if (count > 0) sum += *(uint8_t*)ptr;
    while (sum >> 16) sum = (sum & 0xFFFF) + (sum >> 16);
    return (uint16_t)(~sum);
}

