static volatile uint32_t arkm_init_ready_mask = 0U;
static volatile uint32_t arkm_init_failed_mask = 0U;

static void arkm_init_mark(uint32_t mask) {
    __sync_fetch_and_or(&arkm_init_ready_mask, mask);
}
static void arkm_init_fail(uint32_t mask) {
    __sync_fetch_and_or(&arkm_init_failed_mask, mask);
}
static int arkm_init_has(uint32_t mask) {
    return (__atomic_load_n(&arkm_init_ready_mask, __ATOMIC_ACQUIRE) & mask) == mask;
}

