/* Physical framebuffer format is discovered at boot.  The software back buffer
 * remains ARGB-like 0x00RRGGBB; output conversion happens only at the blitter. */
typedef struct {
    uint8_t bits_per_pixel;
    uint8_t bytes_per_pixel;
    uint8_t framebuffer_type;
    uint8_t red_position;
    uint8_t red_size;
    uint8_t green_position;
    uint8_t green_size;
    uint8_t blue_position;
    uint8_t blue_size;
    uint8_t valid;
} arkm_framebuffer_format_t;

/* Default remains the existing legacy 32-bit RGB layout.  UEFI handoff resets
 * valid and sets these fields only after the incoming tag has been validated. */
static arkm_framebuffer_format_t arkm_fb_format = {
    32U, 4U, 1U, 16U, 8U, 8U, 8U, 0U, 8U, 1U
};

/* Set by the EFI Multiboot2 handoff before ARKM replaces firmware page tables. */
uint64_t arkm_mb2_framebuffer_phys = 0;
uint32_t arkm_mb2_framebuffer_valid = 0;
/* Distinguishes UEFI without GOP from BIOS/VBE for safe display fallback. */
static uint8_t arkm_efi_boot_path = 0U;

/* Validated ACPI RSDP copy retained across the EFI page-table handoff. */
static struct RSDPDescriptor arkm_mb2_rsdp_copy;
static uint32_t arkm_mb2_rsdp_valid = 0;

uint32_t back_buffer[1280 * 720]; 
uint32_t screen_width = 1280; 
uint32_t screen_height = 720; 
uint32_t screen_pitch = 1280 * 4;

uint32_t window_memory_pool[MAX_WINDOWS][1280 * 720];

/* Channel masks are described in bits by Multiboot2.  Support byte-addressable
 * direct-RGB pixels from 8 through 64 bits, plus common 15-bit RGB555.  This
 * covers 8/15/16/24/32/40/48/56/64-bpp layouts without pretending arbitrary
 * non-byte-aligned bitstreams are byte-addressable. Indexed/EGA tags are
 * deliberately rejected until a palette/text renderer exists. */
static int arkm_fb_bpp_storage_valid(uint8_t bpp) {
    return bpp == 8U || bpp == 15U || bpp == 16U ||
           (bpp >= 24U && bpp <= 64U && (bpp & 7U) == 0U);
}

static int arkm_fb_rgb_layout_valid(uint8_t bpp, uint8_t type,
                                    uint8_t red_pos, uint8_t red_size,
                                    uint8_t green_pos, uint8_t green_size,
                                    uint8_t blue_pos, uint8_t blue_size) {
    if (type != 1U || !arkm_fb_bpp_storage_valid(bpp)) return 0;
    if (red_size == 0U || red_size > 32U ||
        green_size == 0U || green_size > 32U ||
        blue_size == 0U || blue_size > 32U) return 0;
    if ((uint32_t)red_pos + red_size > bpp ||
        (uint32_t)green_pos + green_size > bpp ||
        (uint32_t)blue_pos + blue_size > bpp) return 0;

    uint64_t red_mask = ((1ULL << red_size) - 1ULL) << red_pos;
    uint64_t green_mask = ((1ULL << green_size) - 1ULL) << green_pos;
    uint64_t blue_mask = ((1ULL << blue_size) - 1ULL) << blue_pos;
    if ((red_mask & green_mask) != 0ULL ||
        (red_mask & blue_mask) != 0ULL ||
        (green_mask & blue_mask) != 0ULL) return 0;
    return 1;
}

static uint64_t arkm_fb_pack_channel(uint8_t component,
                                     uint8_t size, uint8_t position) {
    if (size == 0U || size > 32U || (uint32_t)position + size > 64U)
        return 0ULL;
    uint64_t maximum = (1ULL << size) - 1ULL;
    uint64_t scaled = ((uint64_t)component * maximum + 127ULL) / 255ULL;
    return scaled << position;
}

/* Write a logical 0x00RRGGBB pixel to the physical framebuffer using the
 * detected channel layout and byte pitch.  The target is MMIO, so stores are
 * volatile and never go through the 32-bit back-buffer pointer type. */
static void arkm_fb_write_pixel(uint32_t x, uint32_t y, uint32_t rgb) {
    if (!framebuffer || !arkm_fb_format.valid ||
        x >= screen_width || y >= screen_height ||
        arkm_fb_format.bytes_per_pixel == 0U ||
        arkm_fb_format.bytes_per_pixel > 8U || screen_pitch == 0U) return;

    uint64_t bytes_per_pixel = arkm_fb_format.bytes_per_pixel;
    uint64_t pixel_x_offset = (uint64_t)x * bytes_per_pixel;
    if (pixel_x_offset > screen_pitch ||
        bytes_per_pixel > (uint64_t)screen_pitch - pixel_x_offset) return;

    uint64_t byte_offset = (uint64_t)y * (uint64_t)screen_pitch + pixel_x_offset;
    uint64_t total_bytes = (uint64_t)screen_pitch * (uint64_t)screen_height;
    if (byte_offset > total_bytes || bytes_per_pixel > total_bytes - byte_offset)
        return;

    uint8_t red = (uint8_t)(rgb >> 16);
    uint8_t green = (uint8_t)(rgb >> 8);
    uint8_t blue = (uint8_t)rgb;
    uint64_t packed =
        arkm_fb_pack_channel(red, arkm_fb_format.red_size,
                             arkm_fb_format.red_position) |
        arkm_fb_pack_channel(green, arkm_fb_format.green_size,
                             arkm_fb_format.green_position) |
        arkm_fb_pack_channel(blue, arkm_fb_format.blue_size,
                             arkm_fb_format.blue_position);

    volatile uint8_t *dst = (volatile uint8_t *)(uintptr_t)framebuffer + byte_offset;
    for (uint32_t i = 0U; i < arkm_fb_format.bytes_per_pixel; ++i)
        dst[i] = (uint8_t)(packed >> (i * 8U));
}

/* Composite pixels are always 32-bit and use the fixed logical stride.  This
 * routine converts them to the negotiated hardware format row by row. */
static void arkm_fb_blit_backbuffer_rect(uint32_t x0, uint32_t y0,
                                         uint32_t x1, uint32_t y1,
                                         uint32_t source_stride) {
    if (!framebuffer || !arkm_fb_format.valid || source_stride == 0U) return;
    if (x0 > screen_width) x0 = screen_width;
    if (x1 > screen_width) x1 = screen_width;
    if (y0 > screen_height) y0 = screen_height;
    if (y1 > screen_height) y1 = screen_height;
    if (x0 >= x1 || y0 >= y1 || x1 > source_stride ||
        x1 > WINDOW_BUFFER_STRIDE || y1 > WINDOW_BUFFER_HEIGHT) return;

    /* Preserve the efficient original path for the common 32-bit 0x00RRGGBB
     * physical format, while still respecting the detected byte pitch. */
    if (arkm_fb_format.bits_per_pixel == 32U &&
        arkm_fb_format.bytes_per_pixel == 4U &&
        arkm_fb_format.red_position == 16U && arkm_fb_format.red_size == 8U &&
        arkm_fb_format.green_position == 8U && arkm_fb_format.green_size == 8U &&
        arkm_fb_format.blue_position == 0U && arkm_fb_format.blue_size == 8U &&
        (screen_pitch & 3U) == 0U &&
        (((uintptr_t)framebuffer & 3ULL) == 0ULL)) {
        for (uint32_t y = y0; y < y1; ++y) {
            const uint32_t *src = &back_buffer[(size_t)y * source_stride + x0];
            volatile uint32_t *dst = (volatile uint32_t *)
                ((volatile uint8_t *)(uintptr_t)framebuffer +
                 (uint64_t)y * screen_pitch + (uint64_t)x0 * 4ULL);
            for (uint32_t x = x0; x < x1; ++x) *dst++ = *src++;
        }
        return;
    }

    for (uint32_t y = y0; y < y1; ++y) {
        const uint32_t *src = &back_buffer[(size_t)y * source_stride + x0];
        for (uint32_t x = x0; x < x1; ++x)
            arkm_fb_write_pixel(x, y, *src++);
    }
}

