static spinlock_t screen_damage_lock = 0;
static volatile uint32_t screen_damage_valid = 0U;
static volatile int32_t screen_damage_x0 = 0;
static volatile int32_t screen_damage_y0 = 0;
static volatile int32_t screen_damage_x1 = 0;
static volatile int32_t screen_damage_y1 = 0;

static void compositor_mark_full_dirty(void) {
    uint64_t flags;
    arkm_lock_irqsave(&screen_damage_lock, &flags);
    screen_full_dirty = 1U;
    screen_dirty = 1U;
    arkm_unlock_irqrestore(&screen_damage_lock, flags);
}

static void compositor_mark_damage(int x, int y, int w, int h) {
    if (w <= 0 || h <= 0) return;
    int64_t x1_64 = (int64_t)x + (int64_t)w;
    int64_t y1_64 = (int64_t)y + (int64_t)h;
    if (x < 0) x = 0;
    if (y < 0) y = 0;
    if (x1_64 > (int64_t)screen_width) x1_64 = screen_width;
    if (y1_64 > (int64_t)screen_height) y1_64 = screen_height;
    if (x >= (int)x1_64 || y >= (int)y1_64) return;
    int x1 = (int)x1_64;
    int y1 = (int)y1_64;

    uint64_t flags;
    arkm_lock_irqsave(&screen_damage_lock, &flags);
    if (!screen_damage_valid) {
        screen_damage_x0 = x;
        screen_damage_y0 = y;
        screen_damage_x1 = x1;
        screen_damage_y1 = y1;
        screen_damage_valid = 1U;
    } else {
        if (x < screen_damage_x0) screen_damage_x0 = x;
        if (y < screen_damage_y0) screen_damage_y0 = y;
        if (x1 > screen_damage_x1) screen_damage_x1 = x1;
        if (y1 > screen_damage_y1) screen_damage_y1 = y1;
    }
    screen_dirty = 1U;
    arkm_unlock_irqrestore(&screen_damage_lock, flags);
}
