// ==========================================
// 5. IMPLEMENTATIONS
// ==========================================

void arkm_lock_irqsave(spinlock_t* lock, uint64_t* rflags) {
    __asm__ volatile("pushfq; popq %0; cli" : "=r"(*rflags));
    while (__sync_lock_test_and_set(lock, 1)) { __asm__ volatile("pause"); }
}

void arkm_unlock_irqrestore(spinlock_t* lock, uint64_t rflags) {
    __sync_lock_release(lock);
    __asm__ volatile("pushq %0; popfq" : : "r"(rflags) : "memory");
}

// ==========================================
// POSIX MUTEX & SEMAPHORE PRIMITIVES
// ==========================================
typedef struct {
    spinlock_t lock;
    uint32_t owner_tid;
    uint32_t recursion;
} mutex_t;

typedef struct {
    spinlock_t lock;
    uint32_t count;
    uint32_t max_count;
    uint32_t waiters;
} semaphore_t;

void mutex_init(mutex_t* m) {
    m->lock = 0;
    m->owner_tid = 0xFFFFFFFF;
    m->recursion = 0;
}

void mutex_lock(mutex_t* m) {
    uint32_t tid = current_task_idx;
    if (m->owner_tid == tid) {
        m->recursion++;
        return;
    }
    uint64_t flags;
    arkm_lock_irqsave(&m->lock, &flags);
    while (m->owner_tid != 0xFFFFFFFF) {
        arkm_unlock_irqrestore(&m->lock, flags);
        __asm__ volatile("pause");
        arkm_lock_irqsave(&m->lock, &flags);
    }
    m->owner_tid = tid;
    m->recursion = 1;
    arkm_unlock_irqrestore(&m->lock, flags);
}

void mutex_unlock(mutex_t* m) {
    if (m->owner_tid != current_task_idx) return;
    if (--m->recursion > 0) return;
    uint64_t flags;
    arkm_lock_irqsave(&m->lock, &flags);
    m->owner_tid = 0xFFFFFFFF;
    arkm_unlock_irqrestore(&m->lock, flags);
}

void sem_init(semaphore_t* sem, uint32_t initial, uint32_t max) {
    sem->lock = 0;
    sem->count = initial;
    sem->max_count = max;
    sem->waiters = 0;
}

void sem_wait(semaphore_t* sem) {
    uint64_t flags;
    while (1) {
        arkm_lock_irqsave(&sem->lock, &flags);
        if (sem->count > 0) {
            sem->count--;
            arkm_unlock_irqrestore(&sem->lock, flags);
            return;
        }
        sem->waiters++;
        arkm_unlock_irqrestore(&sem->lock, flags);
        __asm__ volatile("pause");
    }
}

void sem_post(semaphore_t* sem) {
    uint64_t flags;
    arkm_lock_irqsave(&sem->lock, &flags);
    if (sem->count < sem->max_count) {
        sem->count++;
    }
    if (sem->waiters > 0) sem->waiters--;
    arkm_unlock_irqrestore(&sem->lock, flags);
}

static uint32_t console_shell_bottom(uint32_t console_h) {
    uint32_t console_w = (num_windows > (int)WINDOW_SPECIAL_CONSOLE &&
                          windows[WINDOW_SPECIAL_CONSOLE].w > 0) ?
                         (uint32_t)windows[WINDOW_SPECIAL_CONSOLE].w : 0U;
    uint8_t drawer_fits = (uint8_t)(hardware_discovery_visible &&
                                   console_w >= 500U && console_h >= 280U);
    uint32_t drawer_top = HW_DRAWER_TOP;
    if (console_h < HW_DRAWER_BOTTOM && console_h > 128U)
        drawer_top = console_h - 128U;
    uint32_t bottom = drawer_fits ?
                      (drawer_top > 20U ? drawer_top - 20U : CONSOLE_TEXT_TOP) :
                      (console_h > 20U ? console_h - 20U : console_h);
    if (bottom < CONSOLE_TEXT_TOP + CONSOLE_LINE_HEIGHT) bottom = CONSOLE_TEXT_TOP + CONSOLE_LINE_HEIGHT;
    if (bottom > console_h) bottom = console_h;
    return bottom;
}

static void console_history_push_top(void) {
    if (num_windows <= (int)WINDOW_SPECIAL_CONSOLE || !windows[WINDOW_SPECIAL_CONSOLE].buffer) return;
    uint32_t slot = console_history_head;
    uint32_t* dst = &console_history_pixels[slot][0][0];
    uint32_t* src = &windows[WINDOW_SPECIAL_CONSOLE].buffer[CONSOLE_TEXT_TOP * WINDOW_BUFFER_STRIDE];
    memcpy(dst, src, (size_t)CONSOLE_LINE_HEIGHT * WINDOW_BUFFER_STRIDE * sizeof(uint32_t));
    console_history_head = (slot + 1U) % CONSOLE_HISTORY_LINES;
    if (console_history_count < CONSOLE_HISTORY_LINES) {
        console_history_count++;
    }
    /* If the user is reading older output, keep that content anchored while
     * new output advances the live bottom.  At bottom (0), keep autoscrolling. */
    if (virtual_scroll_pos > 0U && virtual_scroll_pos < CONSOLE_HISTORY_LINES) virtual_scroll_pos++;
    if (virtual_scroll_pos > console_history_count) virtual_scroll_pos = console_history_count;
}

static void console_scroll_by(int rows) {
    int64_t next = (int64_t)virtual_scroll_pos + (int64_t)rows;
    if (next < 0) next = 0;
    if ((uint64_t)next > console_history_count) next = console_history_count;
    if ((uint32_t)next != virtual_scroll_pos) {
        virtual_scroll_pos = (uint32_t)next;
        compositor_mark_full_dirty();
        if (total_cpu_cores > 2U) apic_send_wakeup(local_apic_ids[2]);
    }
}

static void console_scroll_to_bottom(void) {
    if (virtual_scroll_pos != 0U) {
        virtual_scroll_pos = 0U;
        compositor_mark_full_dirty();
        if (total_cpu_cores > 2U) apic_send_wakeup(local_apic_ids[2]);
    }
}

static void console_scroll_to_top(void) {
    uint32_t top = console_history_count;
    if (virtual_scroll_pos != top) {
        virtual_scroll_pos = top;
        compositor_mark_full_dirty();
        if (total_cpu_cores > 2U) apic_send_wakeup(local_apic_ids[2]);
    }
}

static int console_scrollbar_grab_offset(int mouse_y) {
    if (num_windows <= (int)WINDOW_SPECIAL_CONSOLE || console_history_count == 0U) return 0;
    window_t* win = &windows[WINDOW_SPECIAL_CONSOLE];
    uint32_t bottom = console_shell_bottom((uint32_t)win->h);
    int track_top = win->y + (int)CONSOLE_TEXT_TOP;
    int track_h = (int)bottom - (int)CONSOLE_TEXT_TOP;
    if (track_h < 24) return 0;
    uint32_t live_lines = (uint32_t)(track_h / (int)CONSOLE_LINE_HEIGHT);
    if (live_lines == 0U) live_lines = 1U;
    uint32_t total_lines = console_history_count + live_lines;
    int thumb_h = (int)(((uint32_t)track_h * live_lines) / (total_lines ? total_lines : 1U));
    if (thumb_h < 22) thumb_h = 22;
    if (thumb_h > track_h) thumb_h = track_h;
    int travel = track_h - thumb_h;
    uint32_t view = virtual_scroll_pos;
    if (view > console_history_count) view = console_history_count;
    int thumb_top = track_top + ((console_history_count && travel > 0)
        ? (int)(((uint64_t)(console_history_count - view) * (uint32_t)travel) / console_history_count)
        : travel);
    int within_thumb = mouse_y - thumb_top;
    return (within_thumb >= 0 && within_thumb < thumb_h) ? within_thumb : thumb_h / 2;
}

static void console_scrollbar_drag_to(int mouse_y, int grab_offset_y) {
    if (num_windows <= (int)WINDOW_SPECIAL_CONSOLE || console_history_count == 0U) return;
    window_t* win = &windows[WINDOW_SPECIAL_CONSOLE];
    uint32_t bottom = console_shell_bottom((uint32_t)win->h);
    int track_top = win->y + (int)CONSOLE_TEXT_TOP;
    int track_h = (int)bottom - (int)CONSOLE_TEXT_TOP;
    if (track_h < 24) return;
    uint32_t live_lines = (uint32_t)(track_h / (int)CONSOLE_LINE_HEIGHT);
    if (live_lines == 0U) live_lines = 1U;
    uint32_t total_lines = console_history_count + live_lines;
    int thumb_h = (int)(((uint32_t)track_h * live_lines) / (total_lines ? total_lines : 1U));
    if (thumb_h < 22) thumb_h = 22;
    if (thumb_h > track_h) thumb_h = track_h;
    int travel = track_h - thumb_h;
    if (travel <= 0) { console_scroll_to_bottom(); return; }
    int rel = mouse_y - track_top - grab_offset_y;
    if (rel < 0) rel = 0;
    if (rel > travel) rel = travel;
    uint32_t from_top = (uint32_t)(((uint64_t)rel * console_history_count) / (uint32_t)travel);
    uint32_t new_offset = console_history_count - from_top;
    if (new_offset != virtual_scroll_pos) {
        virtual_scroll_pos = new_offset;
        compositor_mark_full_dirty();
        if (total_cpu_cores > 2U) apic_send_wakeup(local_apic_ids[2]);
    }
}

void draw_scrollbar(uint32_t console_w, uint32_t console_h) {
    if (console_w < CONSOLE_SCROLLBAR_W + 2U || console_h < CONSOLE_TEXT_TOP + 24U || num_windows <= 0 || !windows[0].buffer) return;
    uint32_t bottom = console_shell_bottom(console_h);
    uint32_t track_top = CONSOLE_TEXT_TOP;
    uint32_t track_h = bottom > track_top ? bottom - track_top : 1U;
    uint32_t live_lines = track_h / CONSOLE_LINE_HEIGHT;
    if (!live_lines) live_lines = 1U;
    uint32_t total_lines = console_history_count + live_lines;
    uint32_t thumb_h = (track_h * live_lines) / (total_lines ? total_lines : 1U);
    if (thumb_h < 22U) thumb_h = 22U;
    if (thumb_h > track_h) thumb_h = track_h;
    uint32_t travel = track_h - thumb_h;
    uint32_t view = virtual_scroll_pos > console_history_count ? console_history_count : virtual_scroll_pos;
    uint32_t thumb_y = track_top + ((console_history_count && travel) ? ((console_history_count - view) * travel / console_history_count) : travel);
    uint32_t x0 = console_w - CONSOLE_SCROLLBAR_W;
    for (uint32_t y = track_top; y < bottom; y++) {
        uint32_t* row = &windows[0].buffer[y * WINDOW_BUFFER_STRIDE];
        for (uint32_t x = x0; x < console_w; x++) row[x] = 0x202830U;
    }
    for (uint32_t y = thumb_y; y < thumb_y + thumb_h && y < bottom; y++) {
        uint32_t* row = &windows[0].buffer[y * WINDOW_BUFFER_STRIDE];
        for (uint32_t x = x0 + 2U; x < console_w - 2U; x++) row[x] = 0x90A8B8U;
    }
    compositor_mark_full_dirty();
}

void shell_newline() {
    cursor_y += CONSOLE_LINE_HEIGHT;
    uint32_t console_w = (uint32_t)windows[0].w;
    uint32_t console_h = (uint32_t)windows[0].h;
    uint32_t shell_bottom = console_shell_bottom(console_h);

    if (cursor_y >= shell_bottom) {
        cursor_y = shell_bottom - CONSOLE_LINE_HEIGHT;
        console_history_push_top();

        int prev_win = active_window_id;
        window_set_active(WINDOW_SPECIAL_CONSOLE);

        /* Preserve one outgoing row in the history ring, then shift the live
         * text region by one row.  Use a single memcpy per raster row. */
        const uint32_t first_y = CONSOLE_TEXT_TOP;
        const uint32_t last_y = shell_bottom - CONSOLE_LINE_HEIGHT;
        for (uint32_t y = first_y; y < last_y; y += CONSOLE_LINE_HEIGHT) {
            memcpy(&windows[0].buffer[y * WINDOW_BUFFER_STRIDE],
                   &windows[0].buffer[(y + CONSOLE_LINE_HEIGHT) * WINDOW_BUFFER_STRIDE],
                   (size_t)CONSOLE_LINE_HEIGHT * WINDOW_BUFFER_STRIDE * sizeof(uint32_t));
        }
        for (uint32_t y = last_y; y < shell_bottom; y++) {
            uint32_t* row = &windows[0].buffer[y * WINDOW_BUFFER_STRIDE];
            for (uint32_t x = 0; x < console_w; x++) row[x] = 0x14191EU;
        }
        draw_scrollbar(console_w, console_h);
        if (hardware_discovery_visible) draw_hardware_discovery_drawer();
        window_set_active(prev_win);
    }
}


uint64_t sys_ipc_send(uint64_t msg_ptr) {
    ipc_message_t user_msg;
    if (!aegis_copy_from_user(&user_msg, msg_ptr, sizeof(user_msg))) return 0;
    uint64_t flags;
    arkm_lock_irqsave(&ipc_lock, &flags);
    for (int i = 0; i < MAX_IPC_MESSAGES; i++) {
        if (ipc_bus[i].valid == 0) {
            memcpy(&ipc_bus[i], &user_msg, sizeof(ipc_message_t));
            ipc_bus[i].sender_id = current_task_idx; 
            ipc_bus[i].valid = 1;
            log_telemetry(7, ipc_bus[i].receiver_id); 
            arkm_unlock_irqrestore(&ipc_lock, flags);
            return 1; 
        }
    }
    arkm_unlock_irqrestore(&ipc_lock, flags);
    return 0; 
}

uint64_t sys_ipc_recv(uint64_t buffer_ptr) {
    if (!validate_user_writable_pointer(buffer_ptr, sizeof(ipc_message_t))) return 0;
    uint64_t flags;
    arkm_lock_irqsave(&ipc_lock, &flags);
    for (int i = 0; i < MAX_IPC_MESSAGES; i++) {
        if (ipc_bus[i].valid == 1 && ipc_bus[i].receiver_id == current_task_idx) {
            int copied = aegis_copy_to_user(buffer_ptr, &ipc_bus[i], sizeof(ipc_message_t));
            if (copied) ipc_bus[i].valid = 0;
            arkm_unlock_irqrestore(&ipc_lock, flags);
            return copied ? 1U : 0U;
        }
    }
    arkm_unlock_irqrestore(&ipc_lock, flags);
    return 0; 
}

int mouse_wait(uint8_t a_type) {
    uint32_t timeout = 1000000U;
    if (a_type == 0U) {
        while (timeout--) {
            if (inb(0x64) & 0x01U) return 1;
            __asm__ volatile("pause");
        }
        return 0;
    }
    while (timeout--) {
        if ((inb(0x64) & 0x02U) == 0U) return 1;
        __asm__ volatile("pause");
    }
    return 0;
}

void mouse_write(uint8_t a_write) {
    if (!mouse_wait(1U)) return;
    outb(0x64, 0xD4U);
    if (!mouse_wait(1U)) return;
    outb(0x60, a_write);
}

uint8_t mouse_read(void) {
    if (!mouse_wait(0U)) return 0xFFU;
    return inb(0x60);
}

uint8_t mouse_has_wheel = 0;
extern uint8_t mouse_cycle; /* Defined with the PS/2 packet state below. */

static int arkm_i8042_read_config(uint8_t *config) {
    if (!config || !mouse_wait(1U)) return 0;
    outb(0x64, 0x20U);
    if (!mouse_wait(0U)) return 0;
    *config = inb(0x60);
    return 1;
}

static int arkm_i8042_write_config(uint8_t config) {
    if (!mouse_wait(1U)) return 0;
    outb(0x64, 0x60U);
    if (!mouse_wait(1U)) return 0;
    outb(0x60, config);
    return 1;
}

static int arkm_i8042_mouse_command(uint8_t command, uint8_t *response) {
    if (!mouse_wait(1U)) return 0;
    outb(0x64, 0xD4U);
    if (!mouse_wait(1U)) return 0;
    outb(0x60, command);
    if (!mouse_wait(0U)) return 0;
    if (inb(0x60) != 0xFAU) return 0; /* Every device command must ACK. */
    if (response) {
        if (!mouse_wait(0U)) return 0;
        *response = inb(0x60);
    }
    return 1;
}

void init_mouse(void) {
    uint8_t config = 0U;
    mouse_has_wheel = 0U;
    mouse_cycle = 0U;

    /* Initialize the legacy controller as a real fallback path. Both IRQ bits
     * are required; bit 6 translates keyboard set-2 codes to set-1 expected by
     * keyboard_handler(). USB remains optional and does not own host input. */
    if (mouse_wait(1U)) outb(0x64, 0xADU); /* disable keyboard port while reconfiguring */
    if (mouse_wait(1U)) outb(0x64, 0xA7U); /* disable auxiliary port */
    for (uint32_t i = 0U; i < 64U && (inb(0x64) & 0x01U); ++i)
        (void)inb(0x60);

    if (!arkm_i8042_read_config(&config)) {
        qemu_serial_write("[INPUT] i8042 config read failed; attempting IRQ-enabled defaults\n");
        config = 0x00U;
    }
    config = (uint8_t)((config & (uint8_t)~0x30U) | 0x43U); /* IRQ1, IRQ12, translation */
    if (!arkm_i8042_write_config(config))
        qemu_serial_write("[INPUT] i8042 config write timed out\n");
    if (mouse_wait(1U)) outb(0x64, 0xAEU); /* enable keyboard port */
    if (mouse_wait(1U)) outb(0x64, 0xA8U); /* enable auxiliary port */

    /* Explicitly enable keyboard scanning; a missing ACK is non-fatal because
     * some firmware leaves scanning enabled already. */
    if (mouse_wait(1U)) {
        outb(0x60, 0xF4U);
        if (mouse_wait(0U)) (void)inb(0x60);
    }

    int mouse_ok = arkm_i8042_mouse_command(0xF6U, NULL);
    if (mouse_ok) {
        /* IntelliMouse negotiation: each command ACK is consumed before the
         * next command; F2 returns ACK followed by the device ID. */
        mouse_ok = arkm_i8042_mouse_command(0xF3U, NULL) &&
                   arkm_i8042_mouse_command(200U, NULL) &&
                   arkm_i8042_mouse_command(0xF3U, NULL) &&
                   arkm_i8042_mouse_command(100U, NULL) &&
                   arkm_i8042_mouse_command(0xF3U, NULL) &&
                   arkm_i8042_mouse_command(80U, NULL);
    }
    uint8_t device_id = 0U;
    if (mouse_ok && arkm_i8042_mouse_command(0xF2U, &device_id))
        mouse_has_wheel = (device_id == 3U || device_id == 4U);
    else
        mouse_has_wheel = 0U;

    if (!arkm_i8042_mouse_command(0xF4U, NULL))
        qemu_serial_write("[INPUT] PS/2 mouse streaming ACK missing\n");
    qemu_serial_write("[INPUT] i8042 IRQ1/IRQ12 enabled; PS/2 input fallback initialized\n");
}

uint8_t mouse_cycle = 0;
uint8_t mouse_byte[4];

static int window_is_app(int id) {
    return id >= 2 && id < num_windows && windows[id].visible;
}

/* Return the topmost visible window under the pointer, respecting z-order. */
static int window_at_screen_point(int x, int y) {
    int hit = -1;
    int highest_z = -2147483647;
    for (int i = 0; i < num_windows; i++) {
        const window_t* win = &windows[i];
        if (!win->visible || x < win->x || x >= win->x + win->w ||
            y < win->y || y >= win->y + win->h)
            continue;
        if (win->z >= highest_z) {
            highest_z = win->z;
            hit = i;
        }
    }
    return hit;
}

static void window_clamp_position(window_t* win) {
    if (!win) return;
    if (win->x < 0) win->x = 0;
    if (win->y < 0) win->y = 0;
    if (win->x + win->w > (int)screen_width)
        win->x = (int)screen_width - win->w;
    if (win->y + win->h > (int)screen_height)
        win->y = (int)screen_height - win->h;
    if (win->x < 0) win->x = 0;
    if (win->y < 0) win->y = 0;
}

static void window_scroll_clamp(window_t* win) {
    if (!win) return;
    int max_x = win->content_w - win->w;
    int max_y = win->content_h - win->h;
    if (max_x < 0) max_x = 0;
    if (max_y < 0) max_y = 0;
    if (win->scroll_x < 0) win->scroll_x = 0;
    if (win->scroll_y < 0) win->scroll_y = 0;
    if (win->scroll_x > max_x) win->scroll_x = max_x;
    if (win->scroll_y > max_y) win->scroll_y = max_y;
}

void window_scroll_by(int id, int dx, int dy) {
    if (!window_is_app(id)) return;
    window_t* win = &windows[id];
    win->scroll_x += dx;
    win->scroll_y += dy;
    window_scroll_clamp(win);
    compositor_mark_full_dirty();
}

/* direction: -1 = up, +1 = down. */
static int kernel_scroll_active_vertical(int direction) {
    if (direction == 0) return 0;
    if (active_window_id == WINDOW_SPECIAL_CONSOLE) {
        /* Console history is measured from the live bottom: positive goes up. */
        console_scroll_by(direction < 0 ? 3 : -3);
        return 1;
    }
    if (window_is_app(active_window_id)) {
        window_scroll_by(active_window_id, 0, direction < 0 ? -24 : 24);
        return 1;
    }
    return 0;
}

void window_scroll_to_bottom(int id) {
    if (!window_is_app(id)) return;
    window_t* win = &windows[id];
    win->scroll_x = 0;
    win->scroll_y = win->content_h - win->h;
    window_scroll_clamp(win);
    compositor_mark_full_dirty();
}

int window_resize(int id, int new_w, int new_h) {
    if (!window_is_app(id)) return 0;
    window_t* win = &windows[id];
    if (!(win->flags & WINDOW_FLAG_RESIZABLE)) return 0;
    if (new_w < win->min_w) new_w = win->min_w;
    if (new_h < win->min_h) new_h = win->min_h;
    if (new_w > (int)screen_width) new_w = (int)screen_width;
    if (new_h > (int)screen_height) new_h = (int)screen_height;

    int old_w = win->w;
    int old_h = win->h;
    win->w = new_w;
    win->h = new_h;
    if (win->content_w < new_w) win->content_w = new_w;
    if (win->content_h < new_h) win->content_h = new_h;
    window_scroll_clamp(win);

    /* Clear newly exposed viewport area only; the fixed backing store keeps
     * existing application pixels stable across arbitrary resize operations. */
    if (new_w > old_w) {
        uint32_t clear_w = (uint32_t)(new_w - old_w);
        for (int y = 0; y < new_h; y++) {
            uint32_t* row = &win->buffer[(uint32_t)y * WINDOW_BUFFER_STRIDE + (uint32_t)old_w];
            for (uint32_t x = 0; x < clear_w; x++) row[x] = 0x14191E;
        }
    }
    if (new_h > old_h) {
        for (int y = old_h; y < new_h; y++) {
            uint32_t* row = &win->buffer[(uint32_t)y * WINDOW_BUFFER_STRIDE];
            for (int x = 0; x < new_w; x++) row[x] = 0x14191E;
        }
    }
    compositor_mark_full_dirty();
    return 1;
}

void window_move(int id, int new_x, int new_y) {
    if (!window_is_app(id)) return;
    window_t* win = &windows[id];
    if (!(win->flags & WINDOW_FLAG_MOVABLE)) return;
    win->x = new_x;
    win->y = new_y;
    window_clamp_position(win);
    compositor_mark_full_dirty();
}

void window_toggle_maximize(int id) {
    if (!window_is_app(id)) return;
    window_t* win = &windows[id];
    if (!(win->flags & WINDOW_FLAG_RESIZABLE)) return;

    if (!(win->flags & WINDOW_FLAG_MAXIMIZED)) {
        win->saved_x = win->x;
        win->saved_y = win->y;
        win->saved_w = win->w;
        win->saved_h = win->h;
        win->x = 0;
        win->y = 0;
        win->w = (int)screen_width;
        win->h = (int)screen_height;
        if (win->content_w < win->w) win->content_w = win->w;
        if (win->content_h < win->h) win->content_h = win->h;
        win->flags |= WINDOW_FLAG_MAXIMIZED;
    } else {
        win->x = win->saved_x;
        win->y = win->saved_y;
        win->w = win->saved_w;
        win->h = win->saved_h;
        win->flags &= (uint8_t)~WINDOW_FLAG_MAXIMIZED;
        window_clamp_position(win);
    }
    window_scroll_clamp(win);
    compositor_mark_full_dirty();
}

void toggle_kernel_fullscreen(void) {
    if (num_windows < 2) return;
    if (!kernel_ui_fullscreen) {
        fullscreen_saved_console_x = windows[0].x;
        fullscreen_saved_console_y = windows[0].y;
        fullscreen_saved_console_w = windows[0].w;
        fullscreen_saved_console_h = windows[0].h;
        fullscreen_saved_dashboard_x = windows[1].x;
        fullscreen_saved_dashboard_y = windows[1].y;
        fullscreen_saved_dashboard_w = windows[1].w;
        fullscreen_saved_dashboard_h = windows[1].h;
        fullscreen_saved_dashboard_visible = windows[1].visible;

        windows[0].x = 0;
        windows[0].y = 0;
        windows[0].w = (int)screen_width;
        windows[0].h = (int)screen_height;
        windows[0].content_w = (int)screen_width;
        windows[0].content_h = (int)screen_height;
        windows[0].scroll_x = 0;
        windows[0].scroll_y = 0;
        windows[1].visible = 0;
        active_window_id = 0;
        kernel_ui_fullscreen = 1;
    } else {
        windows[0].x = fullscreen_saved_console_x;
        windows[0].y = fullscreen_saved_console_y;
        windows[0].w = fullscreen_saved_console_w;
        windows[0].h = fullscreen_saved_console_h;
        windows[0].content_w = windows[0].w;
        windows[0].content_h = windows[0].h;
        windows[1].x = fullscreen_saved_dashboard_x;
        windows[1].y = fullscreen_saved_dashboard_y;
        windows[1].w = fullscreen_saved_dashboard_w;
        windows[1].h = fullscreen_saved_dashboard_h;
        windows[1].visible = fullscreen_saved_dashboard_visible;
        active_window_id = 0;
        kernel_ui_fullscreen = 0;
        draw_dashboard();
    }
    /* The process now owns an independent execution_context and kernel stack.
     * Retire the loader-only staging context so additional services can load. */
    arkm_boot_app_context.valid = 0;
    __atomic_store_n(&arkm_ring3_schedule_pending, 1U, __ATOMIC_RELEASE);
    compositor_mark_full_dirty();
    if (total_cpu_cores > 2U) apic_send_wakeup(local_apic_ids[2]);
}

static void send_key_event_to_active_service(uint16_t keycode, uint16_t modifiers, char ascii) {
    if (!window_is_app(active_window_id)) return;
    int target_srv = -1;
    for (int i = 0; i < registered_services_count; i++) {
        if (micro_registry[i].win_id == active_window_id && micro_registry[i].active_status == 1) {
            target_srv = micro_registry[i].service_id;
            break;
        }
    }
    if (target_srv < 0) return;
    struct { uint16_t keycode; uint16_t modifiers; uint8_t ascii; uint8_t reserved[3]; } ev = { keycode, modifiers, (uint8_t)ascii, {0,0,0} };
    uint64_t flags;
    arkm_lock_irqsave(&ipc_lock, &flags);
    for (int i = 0; i < MAX_IPC_MESSAGES; i++) {
        if (!ipc_bus[i].valid) {
            ipc_bus[i].sender_id = 0xFFFFFFFFU;
            ipc_bus[i].receiver_id = (uint32_t)target_srv;
            ipc_bus[i].type = 2;
            memcpy(ipc_bus[i].payload, &ev, sizeof(ev));
            ipc_bus[i].valid = 1;
            break;
        }
    }
    arkm_unlock_irqrestore(&ipc_lock, flags);
}

static int window_scrollbar_grab_offset(int id, int mouse_y) {
    if (!window_is_app(id)) return 0;
    window_t* win = &windows[id];
    int max_y = win->content_h - win->h;
    int track_h = win->h - 4;
    if (max_y <= 0 || track_h <= 0 || win->content_h <= 0) return 0;
    int thumb_h = (track_h * win->h) / win->content_h;
    if (thumb_h < 22) thumb_h = 22;
    if (thumb_h > track_h) thumb_h = track_h;
    int travel = track_h - thumb_h;
    int thumb_top = win->y + 2 + ((travel > 0) ? (win->scroll_y * travel / max_y) : 0);
    int within_thumb = mouse_y - thumb_top;
    return (within_thumb >= 0 && within_thumb < thumb_h) ? within_thumb : thumb_h / 2;
}

static void window_scrollbar_drag_to(int id, int mouse_y, int grab_offset_y) {
    if (!window_is_app(id)) return;
    window_t* win = &windows[id];
    int max_y = win->content_h - win->h;
    if (max_y <= 0) return;
    int track_h = win->h - 4;
    int thumb_h = (track_h * win->h) / win->content_h;
    if (thumb_h < 22) thumb_h = 22;
    if (thumb_h > track_h) thumb_h = track_h;
    int travel = track_h - thumb_h;
    if (travel <= 0) { win->scroll_y = 0; return; }
    int rel = mouse_y - win->y - 2 - grab_offset_y;
    if (rel < 0) rel = 0;
    if (rel > travel) rel = travel;
    win->scroll_y = (int)(((int64_t)rel * max_y) / travel);
    window_scroll_clamp(win);
    compositor_mark_full_dirty();
}

static void mouse_process_packet(int dx, int dy, uint8_t buttons, int wheel) {
    __atomic_fetch_add(&arkm_x_mouse_input_events, 1U, __ATOMIC_RELAXED);
    int old_x = sys_mouse.x;
    int old_y = sys_mouse.y;
    int old_left = sys_mouse.left_click;
    int old_right = sys_mouse.right_click;

    sys_mouse.x += dx;
    sys_mouse.y -= dy;
    if (sys_mouse.x < 0) sys_mouse.x = 0;
    if (sys_mouse.x >= (int)screen_width) sys_mouse.x = (int)screen_width - 1;
    if (sys_mouse.y < 0) sys_mouse.y = 0;
    if (sys_mouse.y >= (int)screen_height) sys_mouse.y = (int)screen_height - 1;

    sys_mouse.left_click = (buttons & 0x01U) != 0U;
    sys_mouse.right_click = (buttons & 0x02U) != 0U;
    sys_mouse.wheel_delta = wheel;

    int pointer_changed = (old_x != sys_mouse.x) || (old_y != sys_mouse.y);
    int button_changed = (old_left != sys_mouse.left_click) || (old_right != sys_mouse.right_click);
    int changed = pointer_changed || button_changed || wheel != 0;

    if (wheel != 0) {
        int wheel_target = window_at_screen_point(sys_mouse.x, sys_mouse.y);
        if (wheel_target == WINDOW_SPECIAL_CONSOLE) {
            console_scroll_by(wheel * 3);
        } else if (window_is_app(wheel_target) &&
                   (windows[wheel_target].flags & WINDOW_FLAG_SCROLLABLE)) {
            window_scroll_by(wheel_target, 0, -wheel * 24);
        }
    }

    if (sys_mouse.left_click) {
        if (!sys_mouse.prev_left_click) {
            int clicked_win = -1;
            int highest_z = -1;
            for (int i = 0; i < num_windows; i++) {
                if (!windows[i].visible) continue;
                if (sys_mouse.x >= windows[i].x &&
                    sys_mouse.x < windows[i].x + windows[i].w &&
                    sys_mouse.y >= windows[i].y &&
                    sys_mouse.y < windows[i].y + windows[i].h) {
                    if (windows[i].z > highest_z) {
                        highest_z = windows[i].z;
                        clicked_win = i;
                    }
                }
            }

            if (clicked_win == WINDOW_SPECIAL_DASHBOARD) {
                int rel_x = sys_mouse.x - windows[WINDOW_SPECIAL_DASHBOARD].x;
                int rel_y = sys_mouse.y - windows[WINDOW_SPECIAL_DASHBOARD].y;
                if (screen_height < 700U || windows[WINDOW_SPECIAL_DASHBOARD].w < 240) {
                    /* Compact dashboard rows: SCHED=250, BG=272, NIC=294. */
                    if (rel_x >= 64 && rel_x < 150 && rel_y >= 246 && rel_y < 270)
                        kconf_sched = !kconf_sched;
                    else if (rel_x >= 64 && rel_x < 150 && rel_y >= 268 && rel_y < 292)
                        kconf_bg = !kconf_bg;
                    else if (rel_x >= 64 && rel_x < 150 && rel_y >= 290 && rel_y < 314)
                        kconf_nic = !kconf_nic;
                } else {
                    if (rel_x >= 95 && rel_x <= 125 && rel_y >= 546 && rel_y <= 566) kconf_sched = !kconf_sched;
                    else if (rel_x >= 95 && rel_x <= 125 && rel_y >= 576 && rel_y <= 596) kconf_bg = !kconf_bg;
                    else if (rel_x >= 95 && rel_x <= 125 && rel_y >= 606 && rel_y <= 626) kconf_nic = !kconf_nic;
                }
                changed = 1;
                sys_mouse.active_window_focus = WINDOW_SPECIAL_CONSOLE;
                window_set_active(WINDOW_SPECIAL_CONSOLE);
            }

            if (clicked_win >= 0 && clicked_win != WINDOW_SPECIAL_DASHBOARD) {
                sys_mouse.active_window_focus = clicked_win;
                window_set_active(clicked_win);
                int old_z = windows[clicked_win].z;
                for (int j = 0; j < num_windows; j++)
                    if (windows[j].z > old_z) windows[j].z--;
                windows[clicked_win].z = num_windows - 1;
                changed = 1;

                if (clicked_win == WINDOW_SPECIAL_CONSOLE) {
                    window_t* win = &windows[WINDOW_SPECIAL_CONSOLE];
                    int rel_x = sys_mouse.x - win->x;
                    uint32_t bottom = console_shell_bottom((uint32_t)win->h);
                    int rel_y = sys_mouse.y - win->y;
                    if (console_history_count > 0U && rel_x >= win->w - (int)CONSOLE_SCROLLBAR_W &&
                        rel_y >= (int)CONSOLE_TEXT_TOP && rel_y < (int)bottom) {
                        sys_mouse.is_scroll_dragging = 1;
                        sys_mouse.is_resizing = 0;
                        sys_mouse.is_dragging = 0;
                        sys_mouse.scroll_drag_start_y = sys_mouse.y;
                        sys_mouse.scroll_drag_start_offset = console_scrollbar_grab_offset(sys_mouse.y);
                        console_scrollbar_drag_to(sys_mouse.y, sys_mouse.scroll_drag_start_offset);
                    } else {
                        sys_mouse.is_scroll_dragging = 0;
                        sys_mouse.is_resizing = 0;
                        sys_mouse.is_dragging = 0;
                        console_scroll_to_bottom();
                    }
                } else if (window_is_app(clicked_win)) {
                    window_t* win = &windows[clicked_win];
                    int rel_x = sys_mouse.x - win->x;
                    int rel_y = sys_mouse.y - win->y;
                    int grip_x = win->w - WINDOW_RESIZE_GRIP;
                    int grip_y = win->h - WINDOW_RESIZE_GRIP;
                    int max_y = win->content_h - win->h;
                    if ((win->flags & WINDOW_FLAG_SCROLLABLE) && max_y > 0 &&
                        rel_x >= win->w - WINDOW_SCROLLBAR_WIDTH) {
                        sys_mouse.is_scroll_dragging = 1;
                        sys_mouse.is_resizing = 0;
                        sys_mouse.is_dragging = 0;
                        sys_mouse.scroll_drag_start_y = sys_mouse.y;
                        sys_mouse.scroll_drag_start_offset = window_scrollbar_grab_offset(clicked_win, sys_mouse.y);
                        window_scrollbar_drag_to(clicked_win, sys_mouse.y, sys_mouse.scroll_drag_start_offset);
                    } else if ((win->flags & WINDOW_FLAG_RESIZABLE) &&
                               rel_x >= grip_x && rel_y >= grip_y) {
                        sys_mouse.is_resizing = 1;
                        sys_mouse.is_scroll_dragging = 0;
                        sys_mouse.is_dragging = 0;
                        sys_mouse.resize_start_x = sys_mouse.x;
                        sys_mouse.resize_start_y = sys_mouse.y;
                        sys_mouse.resize_start_w = win->w;
                        sys_mouse.resize_start_h = win->h;
                    } else if (win->flags & WINDOW_FLAG_MOVABLE) {
                        sys_mouse.is_dragging = 1;
                        sys_mouse.is_resizing = 0;
                        sys_mouse.is_scroll_dragging = 0;
                        sys_mouse.drag_offset_x = sys_mouse.x - win->x;
                        sys_mouse.drag_offset_y = sys_mouse.y - win->y;
                    }
                } else {
                    sys_mouse.is_dragging = 0;
                    sys_mouse.is_resizing = 0;
                    sys_mouse.is_scroll_dragging = 0;
                }
            }
        } else if (sys_mouse.active_window_focus >= 0) {
            int id = sys_mouse.active_window_focus;
            if (sys_mouse.is_scroll_dragging) {
                if (pointer_changed) {
                    if (id == WINDOW_SPECIAL_CONSOLE)
                        console_scrollbar_drag_to(sys_mouse.y, sys_mouse.scroll_drag_start_offset);
                    else
                        window_scrollbar_drag_to(id, sys_mouse.y, sys_mouse.scroll_drag_start_offset);
                    changed = 1;
                }
            } else if (pointer_changed && id >= 2 && window_is_app(id) && sys_mouse.is_resizing) {
                window_resize(id,
                              sys_mouse.resize_start_w + (sys_mouse.x - sys_mouse.resize_start_x),
                              sys_mouse.resize_start_h + (sys_mouse.y - sys_mouse.resize_start_y));
                changed = changed || pointer_changed;
            } else if (pointer_changed && id >= 2 && window_is_app(id) && sys_mouse.is_dragging) {
                window_move(id,
                            sys_mouse.x - sys_mouse.drag_offset_x,
                            sys_mouse.y - sys_mouse.drag_offset_y);
                changed = 1;
            }
        }
    } else {
        if (sys_mouse.is_dragging || sys_mouse.is_resizing || sys_mouse.is_scroll_dragging) changed = 1;
        sys_mouse.is_dragging = 0;
        sys_mouse.is_resizing = 0;
        sys_mouse.is_scroll_dragging = 0;
        sys_mouse.scroll_drag_start_y = 0;
        sys_mouse.scroll_drag_start_offset = 0;
    }
    sys_mouse.prev_left_click = sys_mouse.left_click;

    /* HID mice report even when motion/buttons are unchanged.  Avoid copying
     * the whole 1280x720 frame for those idle reports. */
    if (changed) {
        if (pointer_changed && !button_changed && wheel == 0 &&
            !sys_mouse.left_click && !sys_mouse.is_dragging &&
            !sys_mouse.is_resizing && !sys_mouse.is_scroll_dragging) {
            compositor_mark_damage(old_x, old_y, 18, 20);
            compositor_mark_damage(sys_mouse.x, sys_mouse.y, 18, 20);
        } else {
            compositor_mark_full_dirty();
        }
        if (total_cpu_cores > 2U) apic_send_wakeup(local_apic_ids[2]);
    }
}

void mouse_handler() {
    static uint8_t first_mouse_packet_logged = 0U;
    __sync_fetch_and_add(&arkm_irq_vector2c_count, 1U);
    uint8_t status = inb(0x64);
    if (!(status & 0x01U) || !(status & 0x20U)) {
        arkm_apic_eoi();
        return;
    }

    uint8_t data = inb(0x60);
    if (mouse_cycle == 0U && !(data & 0x08U)) {
        arkm_apic_eoi();
        return;
    }
    mouse_byte[mouse_cycle++] = data;
    uint8_t packet_len = mouse_has_wheel ? 4U : 3U;
    if (mouse_cycle == packet_len) {
        mouse_cycle = 0U;
        if (!(mouse_byte[0] & 0xC0U)) {
            int dx = (int)(int8_t)mouse_byte[1];
            int dy = (int)(int8_t)mouse_byte[2];
            int wheel = mouse_has_wheel ? (int)(mouse_byte[3] & 0x0FU) : 0;
            if (mouse_has_wheel && (wheel & 0x08)) wheel |= ~0x0F;
            if (!first_mouse_packet_logged) {
                qemu_serial_write("[INPUT] first PS/2 mouse packet received\n");
                first_mouse_packet_logged = 1U;
            }
            mouse_process_packet(dx, dy, mouse_byte[0], wheel);
        }
    }
    arkm_apic_eoi();
}

void keyboard_handler() {
    static uint8_t first_keyboard_scancode_logged = 0U;
    __sync_fetch_and_add(&arkm_irq_vector21_count, 1U);
    static int shift_pressed = 0;
    static int ctrl_pressed = 0;
    static int alt_pressed = 0;
    static int caps_lock = 0;
    static int text_selected = 0;
    static uint8_t e0_prefix = 0;

    uint8_t status = inb(0x64);
    if ((status & 0x01) && !(status & 0x20)) {
        uint8_t scancode = inb(0x60);
        if (!first_keyboard_scancode_logged) {
            qemu_serial_write("[INPUT] first PS/2 keyboard scancode received\n");
            first_keyboard_scancode_logged = 1U;
        }
        if (scancode == 0xE0) { e0_prefix = 1; arkm_apic_eoi(); return; }

        int extended = e0_prefix;
        e0_prefix = 0;
        int released = (scancode & 0x80) != 0;
        uint8_t code = scancode & 0x7F;

        if (code == 0x2A || code == 0x36) { shift_pressed = !released; arkm_apic_eoi(); return; }
        if (code == 0x1D) { ctrl_pressed = !released; arkm_apic_eoi(); return; }
        if (!extended && code == 0x38) { alt_pressed = !released; arkm_apic_eoi(); return; }
        if (extended && code == 0x38) { alt_pressed = !released; arkm_apic_eoi(); return; }
        if (!released && !extended && code == 0x3A) { caps_lock = !caps_lock; arkm_apic_eoi(); return; }

        if (released) { arkm_apic_eoi(); return; }

        uint16_t modifiers = 0;
        if (shift_pressed) modifiers |= 1U;
        if (ctrl_pressed) modifiers |= 2U;
        if (alt_pressed) modifiers |= 4U;

        /* Full-screen kernel UI.  This changes the guest display layout;
         * the host/QEMU window itself remains under QEMU's control. */
        if (!extended && code == 0x57) {
            toggle_kernel_fullscreen();
            arkm_apic_eoi();
            return;
        }
        if (!extended && code == 0x01 && kernel_ui_fullscreen) { /* Esc */
            toggle_kernel_fullscreen();
            arkm_apic_eoi();
            return;
        }
        if (!extended && code == 0x1C && alt_pressed) { /* Alt+Enter */
            window_toggle_maximize(active_window_id);
            arkm_apic_eoi();
            return;
        }

        /* Window manager control keys. */
        if (extended) {
            int handled = 1;
            int dx = 0, dy = 0;
            switch (code) {
                case 0x48: dy = -16; break; /* Up */
                case 0x50: dy = 16;  break; /* Down */
                case 0x4B: dx = -16; break; /* Left */
                case 0x4D: dx = 16;  break; /* Right */
                case 0x49: if (active_window_id == WINDOW_SPECIAL_CONSOLE) console_scroll_by(12); else window_scroll_by(active_window_id, 0, -(active_window_id >= 2 ? windows[active_window_id].h - 32 : 120)); break; /* PgUp */
                case 0x51: if (active_window_id == WINDOW_SPECIAL_CONSOLE) console_scroll_by(-12); else window_scroll_by(active_window_id, 0,  (active_window_id >= 2 ? windows[active_window_id].h - 32 : 120)); break; /* PgDn */
                case 0x47: if (active_window_id == WINDOW_SPECIAL_CONSOLE) console_scroll_to_top(); else if (window_is_app(active_window_id)) { windows[active_window_id].scroll_y = 0; windows[active_window_id].scroll_x = 0; compositor_mark_full_dirty(); } break; /* Home */
                case 0x4F: if (active_window_id == WINDOW_SPECIAL_CONSOLE) console_scroll_to_bottom(); else window_scroll_to_bottom(active_window_id); break; /* End */
                case 0x53: /* Delete */ handled = 0; break;
                default: handled = 0; break;
            }

            if (dx || dy) {
                int scroll_key_handled = 0;
                if (window_is_app(active_window_id)) {
                    if (ctrl_pressed && alt_pressed) {
                        window_resize(active_window_id,
                                      windows[active_window_id].w + dx,
                                      windows[active_window_id].h + dy);
                    } else if (alt_pressed) {
                        window_move(active_window_id,
                                    windows[active_window_id].x + dx,
                                    windows[active_window_id].y + dy);
                    } else if ((code == 0x48 || code == 0x50) && !ctrl_pressed) {
                        /* Up/Down scroll the active app window without Ctrl. */
                        window_scroll_by(active_window_id, 0, dy < 0 ? -24 : 24);
                        scroll_key_handled = 1;
                    } else if (ctrl_pressed) {
                        window_scroll_by(active_window_id, dx, dy);
                    } else {
                        send_key_event_to_active_service(code, modifiers, 0);
                    }
                } else if (active_window_id == WINDOW_SPECIAL_CONSOLE &&
                           (code == 0x48 || code == 0x50) && !ctrl_pressed && !alt_pressed) {
                    /* Console Up/Down moves through captured output history. */
                    console_scroll_by(dy < 0 ? 3 : -3);
                    scroll_key_handled = 1;
                }
                if (scroll_key_handled) {
                    compositor_mark_full_dirty();
                    if (total_cpu_cores > 2U) apic_send_wakeup(local_apic_ids[2]);
                    arkm_apic_eoi();
                    return;
                }
                handled = 1;
            }

            if (ctrl_pressed && alt_pressed && code == 0x3B) { /* E0 F2-style extension ignored safely */ }
            if (handled) {
                send_key_event_to_active_service(code, modifiers, 0);
                compositor_mark_full_dirty();
                if (total_cpu_cores > 2U) apic_send_wakeup(local_apic_ids[2]);
                arkm_apic_eoi();
                return;
            }
        }

        if (!extended && code == 0x0F) { /* Tab */
            if (ctrl_pressed || alt_pressed) {
                int start = active_window_id;
                int next = start;
                for (int n = 0; n < num_windows; n++) {
                    next++;
                    if (next >= num_windows) next = 2;
                    if (window_is_app(next)) break;
                }
                if (window_is_app(next)) {
                    active_window_id = next;
                    windows[next].z = MAX_WINDOWS - 1;
                    compositor_mark_full_dirty();
                }
                arkm_apic_eoi();
                return;
            }
        }

        if (!extended && code == 0x3E && alt_pressed) { /* F4 */
            if (window_is_app(active_window_id)) {
                int closing = active_window_id;
                uint64_t service_irq = 0ULL;
                arkm_lock_irqsave(&arkm_service_graph_lock, &service_irq);
                for (int i = 0; i < registered_services_count; i++) {
                    if (micro_registry[i].win_id == closing) {
                        micro_registry[i].active_status = 0;
                        micro_registry[i].restart_pending = 0U;
                        if (micro_registry[i].cr3 == app_context.cr3) app_context.valid = 0;
                    }
                }
                arkm_unlock_irqrestore(&arkm_service_graph_lock, service_irq);
                windows[closing].visible = 0;
                active_window_id = 0;
                compositor_mark_full_dirty();
            }
            arkm_apic_eoi();
            return;
        }

        if (!extended && code == 0x44 && alt_pressed) { /* F10 */
            window_toggle_maximize(active_window_id);
            arkm_apic_eoi();
            return;
        }

        /* Send control/special keys to native app services. */
        if (window_is_app(active_window_id) && (ctrl_pressed || alt_pressed)) {
            uint16_t keycode = (uint16_t)code | (extended ? 0x0100U : 0U);
            send_key_event_to_active_service(keycode, modifiers, 0);
            compositor_mark_full_dirty();
            if (total_cpu_cores > 2U) apic_send_wakeup(local_apic_ids[2]);
            arkm_apic_eoi();
            return;
        }

        if (!extended && code < 128U) {
            char c = shift_pressed ? kbd_us_shift[code] : kbd_us[code];
            /* Keyboard telemetry is sampled rather than taking the telemetry
             * lock on every character; the UI input path stays responsive. */
            static uint32_t key_telemetry_sample = 0U;
            if ((++key_telemetry_sample & 0x0FU) == 0U) log_telemetry(1, scancode);
            if (c >= 'A' && c <= 'Z') {
                int is_upper = shift_pressed ^ caps_lock;
                if (!is_upper) c = (char)(c + 32);
            } else if (c >= 'a' && c <= 'z') {
                int is_upper = shift_pressed ^ caps_lock;
                if (is_upper) c = (char)(c - 32);
            }

            if (window_is_app(active_window_id)) {
                send_key_event_to_active_service(code, modifiers, c);
            } else if (active_window_id == 0) {
                /* Typing always returns a scrolled console to its live bottom. */
                console_scroll_to_bottom();
                int prev_win = active_window_id;
                window_set_active(0);
                uint32_t console_w = windows[0].w;

                if (ctrl_pressed) {
                    if (c == 'c' || c == 'C') {
                        if (text_selected) { memcpy(sys_clipboard, cmd_buffer, cmd_idx); sys_clipboard[cmd_idx] = '\0'; }
                    } else if (c == 'v' || c == 'V') {
                        if (text_selected) {
                            draw_rect(20 + (16 * 6), cursor_y, cmd_idx * 16, 16, 20, 25, 30);
                            cmd_idx = 0; cursor_x = 20 + (16 * 6); text_selected = 0;
                        }
                        for (int i = 0; sys_clipboard[i] != '\0' && cmd_idx < 255; i++) {
                            cmd_buffer[cmd_idx++] = sys_clipboard[i];
                            draw_char(cursor_x, cursor_y, sys_clipboard[i], 0, 255, 255);
                            cursor_x += 16;
                            if (cursor_x >= console_w - 40) { cursor_x = 20; shell_newline(); }
                        }
                    } else if (c == 'a' || c == 'A') {
                        text_selected = 1;
                        uint32_t temp_x = 20 + (16 * 6);
                        for (uint32_t i = 0; i < cmd_idx; i++) {
                            draw_rect(temp_x, cursor_y, 16, 16, 0, 100, 200);
                            draw_char(temp_x, cursor_y, cmd_buffer[i], 255, 255, 255);
                            temp_x += 16;
                        }
                    } else if (c == 's' || c == 'S') execute_command("SAVE");
                    window_set_active(prev_win);
                    arkm_apic_eoi();
                    return;
                }

                if (text_selected && c != 0) {
                    draw_rect(20 + (16 * 6), cursor_y, cmd_idx * 16, 16, 20, 25, 30);
                    cmd_idx = 0; cursor_x = 20 + (16 * 6); text_selected = 0;
                }
                if (c == '\b') {
                    if (cmd_idx > 0) { cmd_idx--; cursor_x -= 16; draw_rect(cursor_x, cursor_y, 16, 16, 20, 25, 30); }
                } else if (c == '\n') {
                    cmd_buffer[cmd_idx] = '\0'; execute_command(cmd_buffer);
                } else if (c == '\t') {
                    if (cmd_idx < 255) { cmd_buffer[cmd_idx++] = ' '; cmd_buffer[cmd_idx++] = ' '; cmd_buffer[cmd_idx++] = ' '; cmd_buffer[cmd_idx++] = ' '; }
                } else if (c != 0 && cmd_idx < 255) {
                    cmd_buffer[cmd_idx++] = c; draw_char(cursor_x, cursor_y, c, 0, 255, 255); cursor_x += 16;
                    if (cursor_x >= console_w - 40) { cursor_x = 20; shell_newline(); }
                }
                window_set_active(prev_win);
            }
        }
    }
    if (active_window_id == WINDOW_SPECIAL_CONSOLE) {
        compositor_mark_damage((int)cursor_x - 16, (int)cursor_y, 34, 16);
    } else {
        compositor_mark_full_dirty();
    }
    if (total_cpu_cores > 2U) apic_send_wakeup(local_apic_ids[2]);
    arkm_apic_eoi();
}


/* Some UEFI/Q35 configurations deliver PS/2 IRQs inconsistently after the
 * PIC is masked.  Poll the i8042 output buffer from the BSP idle loop as a
 * fallback; the normal IRQ handlers remain the single scancode/packet parser. */
static void arkm_i8042_poll_fallback(void) {
    uint64_t saved_flags = 0U;
    __asm__ volatile("pushfq; popq %0; cli" : "=r"(saved_flags) :: "memory");
    for (uint32_t drained = 0U; drained < 16U; ++drained) {
        uint8_t status = inb(0x64U);
        if ((status & 0x01U) == 0U) break;
        if (status & 0x20U) mouse_handler();
        else keyboard_handler();
    }
    if (saved_flags & (1ULL << 9)) __asm__ volatile("sti" ::: "memory");
}



int microkernel_register_service(const char* name, uint64_t cr3, uint64_t rsp, uint64_t entry, int win_id) {
    uint64_t irq = 0ULL;
    int result = -1;
    int restarting = 0;
    uint64_t saved_caps = 0ULL, saved_affinity = 0ULL;
    uint32_t saved_domain = 0U, saved_uid = 0U, saved_gid = 0U;
    uint8_t saved_policy_valid = 0U;
    arkm_lock_irqsave(&arkm_service_graph_lock, &irq);
    if (arkm_service_restart_loading && arkm_service_restart_id >= 0 &&
        arkm_service_restart_id < registered_services_count) {
        int idx = arkm_service_restart_id;
        micro_service_slot_t* svc = &micro_registry[idx];
        restarting = 1;
        saved_caps = svc->saved_capabilities;
        saved_affinity = svc->saved_affinity_mask;
        saved_domain = svc->saved_domain_id;
        saved_uid = svc->saved_uid;
        saved_gid = svc->saved_gid;
        saved_policy_valid = svc->saved_policy_valid;
        svc->cr3 = cr3;
        svc->retired_cr3 = 0U;
        svc->rsp = rsp;
        svc->entry = entry;
        svc->win_id = win_id;
        svc->active_status = 1;
        svc->restart_pending = 0U;
        svc->restart_after_tick = 0U;
        svc->restart_attempts = 0U;
        svc->last_fault_reason = 0U;
        /* Preserve dependency graph, crash-window history and saved policy. */
        if (name) {
            uint32_t n = 0U;
            while (name[n] && n < sizeof(svc->name) - 1U) { svc->name[n] = name[n]; n++; }
            svc->name[n] = '\0';
        }
        result = idx;
    } else if (registered_services_count < MAX_MICRO_SERVICES) {
        int idx = registered_services_count++;
        memset(&micro_registry[idx], 0, sizeof(micro_registry[idx]));
        micro_registry[idx].service_id = (uint32_t)idx;
        if (name) {
            uint32_t n = 0U;
            while (name[n] && n < sizeof(micro_registry[idx].name) - 1U) {
                micro_registry[idx].name[n] = name[n]; n++;
            }
            micro_registry[idx].name[n] = '\0';
        }
        micro_registry[idx].cr3 = cr3;
        micro_registry[idx].rsp = rsp;
        micro_registry[idx].entry = entry;
        micro_registry[idx].win_id = win_id;
        micro_registry[idx].active_status = 1;
        result = idx;
    }
    arkm_unlock_irqrestore(&arkm_service_graph_lock, irq);

    if (result >= 0) {
        if (restarting && saved_policy_valid)
            arkm_service_restore_process_policy(cr3, saved_caps, saved_affinity,
                                                saved_domain, saved_uid, saved_gid);
        arkm_service_capture_process_policy((uint32_t)result, cr3);
    }
    return result;
}

void* memset(void* dest, int val, size_t count) {
    uint8_t* d = (uint8_t*)dest;
    for (size_t i = 0; i < count; i++) d[i] = (uint8_t)val;
    return dest;
}

void* memcpy(void* dest, const void* src, size_t count) {
    uint8_t* d = (uint8_t*)dest;
    const uint8_t* s = (const uint8_t*)src;
    uint64_t cr4 = 0ULL;
    __asm__ volatile("mov %%cr4, %0" : "=r"(cr4));
    uint8_t local_smap = (uint8_t)((cr4 >> 21) & 1ULL);
    if (local_smap) __asm__ volatile("stac" ::: "memory");
    for (size_t i = 0; i < count; i++) d[i] = s[i];
    if (local_smap) __asm__ volatile("clac" ::: "memory");
    return dest;
}

int memcmp(const void* s1, const void* s2, size_t n) {
    const uint8_t* a = (const uint8_t*)s1; 
    const uint8_t* b = (const uint8_t*)s2;
    for (size_t i = 0; i < n; i++) { 
        if (a[i] != b[i]) return (int)a[i] - (int)b[i]; 
    } 
    return 0;
}

int strcmp(const char* s1, const char* s2) {
    while (*s1 && *s1 == *s2) { s1++; s2++; } 
    return *(unsigned char*)s1 - *(unsigned char*)s2;
}

void strcpy(char* dest, const char* src) {
    while (*src) { *dest++ = *src++; } 
    *dest = '\0';
}

int str_contains(const char* str, const char* sub) {
    if (!*sub) return 1;
    while (*str) {
        const char* s1 = str; 
        const char* s2 = sub;
        while (*s1 && *s2 && *s1 == *s2) { s1++; s2++; }
        if (!*s2) return 1; 
        str++;
    } 
    return 0;
}

int atoi(const char* str) {
    int result = 0; 
    while (*str >= '0' && *str <= '9') { 
        result = result * 10 + (*str - '0'); 
        str++; 
    } 
    return result;
}

void itoa_dec(uint32_t val, char* buf) {
    char temp[12]; 
    int i = 0;
    if (val == 0) { buf[0] = '0'; buf[1] = '\0'; return; }
    while (val > 0) { 
        temp[i++] = '0' + (val % 10); 
        val /= 10; 
    }
    int j = 0; 
    while (i > 0) buf[j++] = temp[--i]; 
    buf[j] = '\0';
}

void itoa_hex(uint64_t val, char* buf) {
    const char hex[] = "0123456789ABCDEF"; 
    buf[0] = '0'; 
    buf[1] = 'x';
    for (int i = 15; i >= 0; i--) { 
        buf[2 + (15 - i)] = hex[(val >> (i * 4)) & 0xF]; 
    } 
    buf[18] = '\0';
}

void spin_lock(spinlock_t* lock) { 
    while (__sync_lock_test_and_set(lock, 1)) { 
        __asm__ volatile("pause"); 
    } 
}
void spin_unlock(spinlock_t* lock) { 
    __sync_lock_release(lock); 
}

void log_telemetry(uint8_t type, uint64_t data) {
    uint64_t flags;
    arkm_lock_irqsave(&telemetry_lock, &flags);
    uint32_t idx = telemetry_index % TELEMETRY_SIZE;
    telemetry_bus[idx].event_type = type; 
    telemetry_bus[idx].data = data;
    telemetry_bus[idx].timestamp = timer_ticks; 
    telemetry_index++;
    arkm_unlock_irqrestore(&telemetry_lock, flags);
}

void bitmap_set(uint32_t index) { memory_bitmap[index / 8] |= (1 << (index % 8)); }
void bitmap_clear(uint32_t index) { memory_bitmap[index / 8] &= ~(1 << (index % 8)); }
int bitmap_test(uint32_t index) { return memory_bitmap[index / 8] & (1 << (index % 8)); }

void pmm_init() {
    memset(memory_bitmap, 0, BITMAP_SIZE);
    memset(pmm_page_state, 0, sizeof(pmm_page_state));
    memset(pmm_cpu_cache_count, 0, sizeof(pmm_cpu_cache_count));
    memset(pmm_cpu_cache, 0, sizeof(pmm_cpu_cache));

    /* Reserve the low 64 MiB.  This protects the framebuffer/window pools,
     * low-memory DMA/trampoline regions and other statically addressed state. */
    uint32_t protected_pages = (64 * 1024 * 1024) / PAGE_SIZE;
    if (protected_pages > TOTAL_PAGES) protected_pages = TOTAL_PAGES;
    for (uint32_t i = 0; i < protected_pages; i++) {
        bitmap_set(i);
        pmm_page_state[i] = PMM_PAGE_RESERVED;
    }
    last_allocated_page = protected_pages ? (protected_pages - 1U) : 0U;
    arkm_prod_state.boot_stage = ARKM_PROD_STAGE_MEMORY;
    log_telemetry(2, protected_pages);
}
 
uint32_t get_used_ram_kb() {
    uint32_t used_pages = 0U;
    for (uint32_t byte_off = 0U; byte_off < BITMAP_SIZE; byte_off += 8U) {
        uint64_t word = 0ULL;
        memcpy(&word, &memory_bitmap[byte_off], sizeof(word));
        used_pages += (uint32_t)__builtin_popcountll(word);
    }
    return used_pages * (PAGE_SIZE / 1024U);
}

int check_memory_guardrail(uint32_t requested_pages) {
    uint32_t used_kb = get_used_ram_kb();
    uint32_t req_kb = requested_pages * 4;
    if (used_kb + req_kb < used_kb) return 0;
    if (((used_kb + req_kb) * 100) / (TOTAL_PAGES * 4) > 95) return 0;
    return 1;
}

static uint32_t pmm_cache_slot(void) {
    return get_core_id() & 31U;
}

static void pmm_cache_flush_slot(uint32_t slot) {
    if (slot >= 32U) return;
    uint64_t flags;
    arkm_lock_irqsave(&pmm_lock, &flags);
    while (pmm_cpu_cache_count[slot] > 0) {
        uint32_t idx = pmm_cpu_cache[slot][pmm_cpu_cache_count[slot] - 1U];
        pmm_cpu_cache_count[slot]--;
        if (idx < TOTAL_PAGES && pmm_page_state[idx] == PMM_PAGE_CACHED) {
            pmm_page_state[idx] = PMM_PAGE_FREE;
            bitmap_clear(idx);
        }
    }
    arkm_unlock_irqrestore(&pmm_lock, flags);
}

static uint32_t pmm_cache_flush_all(void) {
    uint32_t flushed = 0U;
    uint64_t flags;
    arkm_lock_irqsave(&pmm_lock, &flags);
    for (uint32_t slot = 0U; slot < 32U; ++slot) {
        while (pmm_cpu_cache_count[slot] > 0U) {
            uint32_t idx = pmm_cpu_cache[slot][--pmm_cpu_cache_count[slot]];
            if (idx < TOTAL_PAGES && pmm_page_state[idx] == PMM_PAGE_CACHED) {
                pmm_page_state[idx] = PMM_PAGE_FREE;
                bitmap_clear(idx);
                flushed++;
            }
        }
    }
    arkm_unlock_irqrestore(&pmm_lock, flags);
    return flushed;
}

static uint32_t pmm_pressure_level(void) {
    uint32_t used = get_used_ram_kb();
    uint32_t total = TOTAL_PAGES * (PAGE_SIZE / 1024U);
    if (!total) return 3U;
    uint32_t pct = (uint32_t)(((uint64_t)used * 100ULL) / total);
    if (pct >= 95U) return 3U;
    if (pct >= 85U) return 2U;
    if (pct >= 70U) return 1U;
    return 0U;
}

void* pmm_alloc_page() {
    uint32_t slot = pmm_cache_slot();
    uint64_t flags;

    arkm_lock_irqsave(&pmm_lock, &flags);
    if (slot < 32U && pmm_cpu_cache_count[slot] > 0U) {
        uint32_t idx = pmm_cpu_cache[slot][--pmm_cpu_cache_count[slot]];
        if (idx < TOTAL_PAGES && pmm_page_state[idx] == PMM_PAGE_CACHED) {
            pmm_page_state[idx] = PMM_PAGE_ALLOCATED;
            arkm_prod_state.pmm_cache_hits++;
            advanced_page_allocated(idx);
            last_allocated_page = idx;
            arkm_unlock_irqrestore(&pmm_lock, flags);
            return (void*)(uint64_t)(idx * PAGE_SIZE);
        }
    }
    arkm_prod_state.pmm_cache_misses++;
    arkm_unlock_irqrestore(&pmm_lock, flags);

    if (!check_memory_guardrail(1U)) {
        (void)pmm_cache_flush_all();
        /* Reclaim only pages whose advanced reference metadata says they
         * are unreferenced. Never terminate a service as an OOM shortcut. */
        (void)advanced_reclaim();
        if (!check_memory_guardrail(1U)) {
            __atomic_store_n(&arkm_oom_request_pending, 1U, __ATOMIC_RELEASE);
            arkm_prod_state.invariant_failures++;
            log_telemetry(9U, 0x504D4D4F4F4D0001ULL);
            return NULL;
        }
    }

    arkm_lock_irqsave(&pmm_lock, &flags);
    const uint32_t words = (TOTAL_PAGES + 63U) / 64U;
    const uint32_t start_page = (last_allocated_page + 1U) % TOTAL_PAGES;
    const uint32_t start_word = start_page / 64U;
    const uint32_t start_bit = start_page & 63U;

    /* Two-phase next-fit scan: ctzll finds free candidates in each 64-bit
     * bitmap word, and the page-state array remains the final authority. */
    for (uint32_t pass = 0U; pass < 2U; ++pass) {
        uint32_t begin = (pass == 0U) ? start_word : 0U;
        uint32_t end = (pass == 0U) ? words : (start_word + 1U);
        for (uint32_t w = begin; w < end; ++w) {
            uint64_t occupied = 0ULL;
            memcpy(&occupied, &memory_bitmap[w * 8U], sizeof(occupied));
            uint64_t candidates = ~occupied;
            if (pass == 0U && w == start_word && start_bit != 0U)
                candidates &= (~0ULL << start_bit);
            if (pass == 1U && w == start_word)
                candidates &= (start_bit == 0U) ? 0ULL : ((1ULL << start_bit) - 1ULL);

            while (candidates != 0ULL) {
                uint32_t bit = (uint32_t)__builtin_ctzll(candidates);
                candidates &= candidates - 1ULL;
                uint32_t idx = w * 64U + bit;
                if (idx >= TOTAL_PAGES) continue;
                if (pmm_page_state[idx] != PMM_PAGE_FREE || bitmap_test(idx))
                    continue;

                bitmap_set(idx);
                pmm_page_state[idx] = PMM_PAGE_ALLOCATED;
                advanced_page_allocated(idx);
                last_allocated_page = idx;
                log_telemetry(2U, (uint64_t)idx * PAGE_SIZE);
                arkm_unlock_irqrestore(&pmm_lock, flags);
                return (void*)((uint64_t)idx * PAGE_SIZE);
            }
        }
    }
    arkm_unlock_irqrestore(&pmm_lock, flags);
    return NULL;
}


void pmm_free_page(void* page) {
    if (!page) return;

    uint64_t addr = (uint64_t)page;
    if ((addr & (PAGE_SIZE - 1)) != 0) {
        arkm_prod_state.invalid_pointer_errors++;
        return;
    }

    uint64_t page_index64 = addr / PAGE_SIZE;
    if (page_index64 >= TOTAL_PAGES) {
        arkm_prod_state.invalid_pointer_errors++;
        return;
    }

    uint32_t page_index = (uint32_t)page_index64;
    uint32_t slot = pmm_cache_slot();
    uint64_t flags;
    arkm_lock_irqsave(&pmm_lock, &flags);

    if (pmm_page_state[page_index] == PMM_PAGE_RESERVED ||
        pmm_page_state[page_index] == PMM_PAGE_FREE ||
        pmm_page_state[page_index] == PMM_PAGE_CACHED) {
        arkm_prod_state.double_free_errors++;
        arkm_prod_state.invariant_failures++;
        log_telemetry(9, ((uint64_t)0xD0 << 56) | page_index);
        arkm_unlock_irqrestore(&pmm_lock, flags);
        return;
    }

    advanced_page_released(page_index);
    if (advanced_page_reference_count(page_index) != 0U) {
        /* Another COW/address-space reference still owns this physical frame. */
        arkm_unlock_irqrestore(&pmm_lock, flags);
        return;
    }

    if (slot < 32U && pmm_cpu_cache_count[slot] < PMM_CPU_CACHE_CAP) {
        pmm_cpu_cache[slot][pmm_cpu_cache_count[slot]++] = page_index;
        pmm_page_state[page_index] = PMM_PAGE_CACHED;
        /* Keep the bitmap set while cached so accounting cannot hand the page
         * to a second CPU before its owner reuses or flushes it. */
    } else {
        pmm_page_state[page_index] = PMM_PAGE_FREE;
        bitmap_clear(page_index);
    }

    arkm_unlock_irqrestore(&pmm_lock, flags);
}

/* Allocate a physically contiguous run for hardware tables that require one
 * base address. Cached frames are deliberately skipped; ownership is marked
 * under the PMM lock before the returned physical base is exposed. */
static void* pmm_alloc_contiguous_pages(uint32_t count) {
    if (count == 0U || count > TOTAL_PAGES) return NULL;
    if (!check_memory_guardrail(count)) {
        (void)pmm_cache_flush_all();
        (void)advanced_reclaim();
        if (!check_memory_guardrail(count)) return NULL;
    }

    uint64_t flags;
    arkm_lock_irqsave(&pmm_lock, &flags);
    uint32_t run = 0U;
    uint32_t start = 0U;
    for (uint32_t i = 0U; i < TOTAL_PAGES; ++i) {
        if (pmm_page_state[i] == PMM_PAGE_FREE && !bitmap_test(i)) {
            if (run == 0U) start = i;
            run++;
            if (run == count) {
                for (uint32_t j = 0U; j < count; ++j) {
                    uint32_t idx = start + j;
                    bitmap_set(idx);
                    pmm_page_state[idx] = PMM_PAGE_ALLOCATED;
                    advanced_page_allocated(idx);
                }
                last_allocated_page = start + count - 1U;
                arkm_unlock_irqrestore(&pmm_lock, flags);
                return (void*)((uint64_t)start * PAGE_SIZE);
            }
        } else {
            run = 0U;
        }
    }
    arkm_unlock_irqrestore(&pmm_lock, flags);
    return NULL;
}

static void pmm_free_contiguous_pages(void* base, uint32_t count) {
    if (!base || !count) return;
    uint64_t address = (uint64_t)(uintptr_t)base;
    if ((address & (PAGE_SIZE - 1ULL)) ||
        count > (UINT64_MAX - address) / PAGE_SIZE ||
        address / PAGE_SIZE + count > TOTAL_PAGES) return;
    for (uint32_t i = 0U; i < count; ++i)
        pmm_free_page((void*)(uintptr_t)(address + (uint64_t)i * PAGE_SIZE));
}

void kmalloc_init() {
    void* initial_heap = pmm_alloc_page(); 
    pmm_alloc_page(); 
    pmm_alloc_page();
    heap_head = (heap_block_t*)initial_heap;
    heap_head->size = (PAGE_SIZE * 4) - sizeof(heap_block_t);
    heap_head->is_free = 1; 
    heap_head->next = NULL;
    heap_head->canary = HEAP_CANARY; // Set initial canary
}

void* kmalloc(size_t size) {
    if (size == 0) return NULL;
    size = (size + 7) & ~7;
    if (size > (size_t)-1 - sizeof(heap_block_t) - 8) return NULL; // Strict overflow check
    uint64_t flags;
    arkm_lock_irqsave(&heap_lock, &flags);
    heap_block_t* curr = heap_head;
    while (curr) {
        if (curr->is_free && curr->size >= size) {
            if (curr->size > size + sizeof(heap_block_t) + 8) {
                heap_block_t* new_block = (heap_block_t*)((uint8_t*)curr + sizeof(heap_block_t) + size);
                new_block->size = curr->size - size - sizeof(heap_block_t);
                new_block->is_free = 1; 
                new_block->next = curr->next;
                new_block->canary = HEAP_CANARY;
                curr->size = size; 
                curr->next = new_block;
            }
            curr->is_free = 0; 
            curr->canary = HEAP_CANARY; // Set canary for allocated block
            arkm_unlock_irqrestore(&heap_lock, flags);
            return (void*)((uint8_t*)curr + sizeof(heap_block_t));
        }
        curr = curr->next;
    }
    arkm_unlock_irqrestore(&heap_lock, flags); 
    return NULL; 
}

void kfree(void* ptr) {
    if (!ptr) return;
    uint64_t flags;
    arkm_lock_irqsave(&heap_lock, &flags);
    heap_block_t* block = (heap_block_t*)((uint8_t*)ptr - sizeof(heap_block_t));
    if (block->canary != HEAP_CANARY) {
        // Memory corruption detected! Safely ignore the free to prevent a crash.
        arkm_unlock_irqrestore(&heap_lock, flags);
        return;
    }
    block->canary = 0; // Clear canary before marking free
    block->is_free = 1; 
    heap_block_t* curr = heap_head;
    while (curr) {
        if (curr->is_free && curr->next && curr->next->is_free) {
            curr->size += sizeof(heap_block_t) + curr->next->size;
            curr->next = curr->next->next;
        }
        curr = curr->next;
    }
    arkm_unlock_irqrestore(&heap_lock, flags);
}

void outb(uint16_t port, uint8_t val) { __asm__ volatile ("outb %0, %1" : : "a"(val), "Nd"(port)); }
uint8_t inb(uint16_t port) { uint8_t ret; __asm__ volatile ("inb %1, %0" : "=a"(ret) : "Nd"(port)); return ret; }
uint16_t inw(uint16_t port) { uint16_t ret; __asm__ volatile ("inw %1, %0" : "=a"(ret) : "Nd"(port)); return ret; }
uint32_t ind(uint16_t port) { uint32_t ret; __asm__ volatile ("inl %1, %0" : "=a"(ret) : "Nd"(port)); return ret; }
void outd(uint16_t port, uint32_t val) { __asm__ volatile ("outl %0, %1" : : "a"(val), "Nd"(port)); }
void outw(uint16_t port, uint16_t val) { __asm__ volatile ("outw %0, %1" : : "a"(val), "Nd"(port)); }

void ahci_port_start(volatile hba_port_t *port) {
    if (!port) return;
    uint32_t spin = 0U;
    while ((port->cmd & 0x8000U) && spin++ < 1000000U)
        __asm__ volatile("pause");
    if (port->cmd & 0x8000U) return;
    port->cmd |= 0x0010U;
    port->cmd |= 0x0001U;
}

void ahci_port_stop(volatile hba_port_t *port) {
    if (!port) return;
    port->cmd &= ~0x0001U;
    port->cmd &= ~0x0010U;
    for (uint32_t spin = 0U; spin < 1000000U &&
         (port->cmd & (0x4000U | 0x8000U)); ++spin)
        __asm__ volatile("pause");
}

static int ahci_port_rebase(volatile hba_port_t *port, int port_no, uint8_t bus, uint8_t slot, uint8_t func) {
    (void)port_no;
    if (!port) return 0;

    void *clb_page = NULL;
    void *fb_page = NULL;
    void *cmd_pages[32] = {0};
    ahci_port_stop(port);

    clb_page = pmm_alloc_page();
    fb_page = pmm_alloc_page();
    if (!clb_page || !fb_page) goto fail;
    for (uint32_t i = 0; i < 32U; ++i) {
        cmd_pages[i] = pmm_alloc_page();
        if (!cmd_pages[i]) goto fail;
    }

    memset(clb_page, 0, PAGE_SIZE);
    memset(fb_page, 0, PAGE_SIZE);
    port->clb = (uint32_t)(uintptr_t)clb_page;
    port->clbu = 0U;
    port->fb = (uint32_t)(uintptr_t)fb_page;
    port->fbu = 0U;

    ahci_cmd_header_t *cmdheader = (ahci_cmd_header_t *)clb_page;
    for (uint32_t i = 0; i < 32U; ++i) {
        cmdheader[i].prdtl = 1U;
        cmdheader[i].ctba = (uint32_t)(uintptr_t)cmd_pages[i];
        cmdheader[i].ctbau = 0U;
        memset(cmd_pages[i], 0, PAGE_SIZE);
    }

    if (!arkm_iommu_prepare_dma(bus, slot, func, (uint64_t)clb_page,
                                PAGE_SIZE, 3U, NULL) ||
        !arkm_iommu_prepare_dma(bus, slot, func, (uint64_t)fb_page,
                                PAGE_SIZE, 3U, NULL) ||
        !arkm_iommu_prepare_dma(bus, slot, func,
                                (uint64_t)arkm_ahci_dma_sector,
                                sizeof(arkm_ahci_dma_sector), 3U, NULL)) goto fail;
    for (uint32_t i = 0U; i < 32U; ++i) {
        if (!arkm_iommu_prepare_dma(bus, slot, func,
                                    (uint64_t)cmd_pages[i], PAGE_SIZE,
                                    3U, NULL)) goto fail;
    }
    uint16_t pci_cmd = pci_config_read_word(bus, slot, func, 0x04U);
    pci_config_write_word(bus, slot, func, 0x04U,
                          (uint16_t)(pci_cmd | 0x0006U));

    ahci_port_start(port);
    if ((port->cmd & (0x0010U | 0x0001U)) != (0x0010U | 0x0001U))
        goto fail;
    return 1;

fail:
    ahci_port_stop(port);
    port->clb = 0U; port->clbu = 0U;
    port->fb = 0U; port->fbu = 0U;
    for (uint32_t i = 0; i < 32U; ++i)
        if (cmd_pages[i]) pmm_free_page(cmd_pages[i]);
    if (fb_page) pmm_free_page(fb_page);
    if (clb_page) pmm_free_page(clb_page);
    return 0;
}

static int ahci_read_sector_unlocked(uint32_t startlba, uint8_t *buffer) {
    if (!sata_port || !buffer) return 0;

    const uint32_t slot = 0U;
    uint32_t spin = 0U;
    ahci_cmd_header_t *cmdheader =
        (ahci_cmd_header_t *)(uintptr_t)sata_port->clb;
    if (!cmdheader || !cmdheader[slot].ctba ||
        (uint64_t)(uintptr_t)arkm_ahci_dma_sector > 0xFFFFFFFFULL)
        return 0;

    /* The command engine must be ready and slot zero must be idle. */
    while ((sata_port->tfd & (0x80U | 0x08U)) != 0U ||
           (sata_port->ci & (1U << slot)) != 0U) {
        if (++spin > 10000000U) {
            if (!arkm_ahci_read_error_reported) {
                qemu_serial_write("[AHCI] read timed out waiting for command slot/device readiness\n");
                arkm_ahci_read_error_reported = 1U;
            }
            return 0;
        }
        __asm__ volatile("pause" ::: "memory");
    }

    sata_port->is = 0xFFFFFFFFU;   /* write-one-to-clear stale interrupt status */
    sata_port->serr = 0xFFFFFFFFU;

    cmdheader[slot].cfl = (uint8_t)(sizeof(fis_reg_h2d_t) / sizeof(uint32_t));
    cmdheader[slot].a = 0U;
    cmdheader[slot].c = 0U;       /* READ: command-header W bit is clear. */
    cmdheader[slot].prdtl = 1U;
    cmdheader[slot].prdbc = 0U;

    ahci_cmd_tbl_t *cmdtbl =
        (ahci_cmd_tbl_t *)(uintptr_t)cmdheader[slot].ctba;
    memset(cmdtbl, 0, sizeof(ahci_cmd_tbl_t));
    cmdtbl->prdt_entry[0].dba =
        (uint32_t)(uintptr_t)arkm_ahci_dma_sector;
    cmdtbl->prdt_entry[0].dbau = 0U;
    cmdtbl->prdt_entry[0].reserved = 0U;
    cmdtbl->prdt_entry[0].dbc_ioc = 511U | 0x80000000U;

    fis_reg_h2d_t *cmdfis = (fis_reg_h2d_t *)&cmdtbl->cfis;
    cmdfis->fis_type = FIS_TYPE_REG_H2D;
    cmdfis->c = 1U;
    cmdfis->command = 0x25U;      /* READ DMA EXT (0x24 is READ SECTORS EXT/PIO). */
    cmdfis->lba0 = (uint8_t)startlba;
    cmdfis->lba1 = (uint8_t)(startlba >> 8);
    cmdfis->lba2 = (uint8_t)(startlba >> 16);
    cmdfis->device = (uint8_t)(1U << 6);
    cmdfis->lba3 = (uint8_t)(startlba >> 24);
    cmdfis->lba4 = 0U;
    cmdfis->lba5 = 0U;
    cmdfis->countl = 1U;
    cmdfis->counth = 0U;

    __asm__ volatile("mfence" ::: "memory");
    sata_port->ci = (1U << slot);

    spin = 0U;
    while ((sata_port->ci & (1U << slot)) != 0U) {
        if ((sata_port->is & (1U << 30)) != 0U) {
            if (!arkm_ahci_read_error_reported) {
                qemu_serial_write("[AHCI] READ DMA EXT task-file error\n");
                arkm_ahci_read_error_reported = 1U;
            }
            sata_port->is = 0xFFFFFFFFU;
            return 0;
        }
        if (++spin > 10000000U) {
            if (!arkm_ahci_read_error_reported) {
                qemu_serial_write("[AHCI] READ DMA EXT completion timeout\n");
                arkm_ahci_read_error_reported = 1U;
            }
            return 0;
        }
        __asm__ volatile("pause" ::: "memory");
    }

    if ((sata_port->is & (1U << 30)) != 0U ||
        (sata_port->tfd & (0x01U | 0x20U)) != 0U) {
        if (!arkm_ahci_read_error_reported) {
            qemu_serial_write("[AHCI] READ DMA EXT finished with device error\n");
            arkm_ahci_read_error_reported = 1U;
        }
        sata_port->is = 0xFFFFFFFFU;
        return 0;
    }

    __asm__ volatile("mfence" ::: "memory");
    memcpy(buffer, arkm_ahci_dma_sector, 512U);
    return 1;
}

int ahci_read_sector(uint32_t startlba, uint8_t *buffer) {
    if (!sata_port || !buffer) return 0;
    log_telemetry(3U, startlba);
    uint64_t flags = 0U;
    arkm_lock_irqsave(&arkm_ahci_io_lock, &flags);
    int ok = ahci_read_sector_unlocked(startlba, buffer);
    arkm_unlock_irqrestore(&arkm_ahci_io_lock, flags);
    return ok;
}

/* AHCI single-sector write. READ DMA EXT is 0x25; WRITE DMA EXT is 0x35. */
static int ahci_write_sector_unlocked(uint32_t startlba, const uint8_t *buffer) {
    if (!sata_port || !buffer) return 0;

    sata_port->is = 0xFFFFFFFFU;
    sata_port->serr = 0xFFFFFFFFU;

    const uint32_t slot = 0U;
    uint32_t spin = 0U;
    ahci_cmd_header_t *cmdheader =
        (ahci_cmd_header_t *)(uint64_t)sata_port->clb;
    if (!cmdheader || !cmdheader[slot].ctba) return 0;

    cmdheader[slot].cfl = (uint8_t)(sizeof(fis_reg_h2d_t) / sizeof(uint32_t));
    cmdheader[slot].a = 0;
    cmdheader[slot].c = 1; /* AHCI command-header W bit (bit 6). */
    cmdheader[slot].prdtl = 1U;
    cmdheader[slot].prdbc = 0U;
    if ((uint64_t)(uintptr_t)arkm_ahci_dma_sector > 0xFFFFFFFFULL) return 0;
    memcpy(arkm_ahci_dma_sector, buffer, 512U);

    ahci_cmd_tbl_t *cmdtbl =
        (ahci_cmd_tbl_t *)(uintptr_t)cmdheader[slot].ctba;
    memset(cmdtbl, 0, sizeof(ahci_cmd_tbl_t));
    cmdtbl->prdt_entry[0].dba = (uint32_t)(uintptr_t)arkm_ahci_dma_sector;
    cmdtbl->prdt_entry[0].dbau = 0U;
    cmdtbl->prdt_entry[0].reserved = 0U;
    cmdtbl->prdt_entry[0].dbc_ioc = 511U | 0x80000000U;

    fis_reg_h2d_t *cmdfis = (fis_reg_h2d_t *)&cmdtbl->cfis;
    cmdfis->fis_type = FIS_TYPE_REG_H2D;
    cmdfis->c = 1;
    cmdfis->command = 0x35U; /* WRITE DMA EXT */
    cmdfis->lba0 = (uint8_t)startlba;
    cmdfis->lba1 = (uint8_t)(startlba >> 8);
    cmdfis->lba2 = (uint8_t)(startlba >> 16);
    cmdfis->device = (uint8_t)(1U << 6);
    cmdfis->lba3 = (uint8_t)(startlba >> 24);
    cmdfis->lba4 = 0;
    cmdfis->lba5 = 0;
    cmdfis->countl = 1;
    cmdfis->counth = 0;

    /* Do not reuse command slot 0 while hardware still owns it. */
    while ((sata_port->tfd & (0x80U | 0x08U)) != 0U ||
           (sata_port->ci & (1U << slot)) != 0U) {
        if (++spin > 10000000U) {
            if (!arkm_ahci_write_error_reported) {
                qemu_serial_write("[AHCI] write timed out waiting for command slot/device readiness\n");
                arkm_ahci_write_error_reported = 1U;
            }
            return 0;
        }
        __asm__ volatile("pause" ::: "memory");
    }
    __asm__ volatile("mfence" ::: "memory");
    sata_port->ci = (1U << slot);

    spin = 0U;
    while ((sata_port->ci & (1U << slot)) != 0U) {
        if ((sata_port->is & (1U << 30)) != 0U) {
            if (!arkm_ahci_write_error_reported) {
                qemu_serial_write("[AHCI] WRITE DMA EXT task-file error\n");
                arkm_ahci_write_error_reported = 1U;
            }
            sata_port->is = 0xFFFFFFFFU;
            return 0;
        }
        if (++spin > 10000000U) {
            if (!arkm_ahci_write_error_reported) {
                qemu_serial_write("[AHCI] WRITE DMA EXT completion timeout\n");
                arkm_ahci_write_error_reported = 1U;
            }
            return 0;
        }
        __asm__ volatile("pause" ::: "memory");
    }

    if ((sata_port->is & (1U << 30)) != 0U ||
        (sata_port->tfd & (0x01U | 0x20U)) != 0U) {
        if (!arkm_ahci_write_error_reported) {
            qemu_serial_write("[AHCI] WRITE DMA EXT finished with device error\n");
            arkm_ahci_write_error_reported = 1U;
        }
        sata_port->is = 0xFFFFFFFFU;
        return 0;
    }
    return 1;
}

static int ahci_flush_cache_unlocked(void) {
    if (!sata_port) return 0;
    ahci_cmd_header_t *cmdheader =
        (ahci_cmd_header_t *)(uint64_t)sata_port->clb;
    if (!cmdheader || !cmdheader[0].ctba) return 0;
    uint32_t spin = 0U;
    while ((sata_port->tfd & (0x80U | 0x08U)) != 0U ||
           (sata_port->ci & 1U) != 0U) {
        if (++spin > 10000000U) return 0;
        __asm__ volatile("pause" ::: "memory");
    }
    cmdheader[0].cfl = (uint8_t)(sizeof(fis_reg_h2d_t) / sizeof(uint32_t));
    cmdheader[0].a = 0U;
    cmdheader[0].c = 0U; /* AHCI W bit: FLUSH is a device command, not a write. */
    cmdheader[0].p = 0U;
    cmdheader[0].r = 0U;
    cmdheader[0].b = 0U;
    cmdheader[0].c_clear = 0U;
    cmdheader[0].rsv0 = 0U;
    cmdheader[0].pmp = 0U;
    cmdheader[0].prdtl = 0U;
    cmdheader[0].prdbc = 0U;
    ahci_cmd_tbl_t *cmdtbl =
        (ahci_cmd_tbl_t *)(uintptr_t)cmdheader[0].ctba;
    memset(cmdtbl, 0, sizeof(ahci_cmd_tbl_t));
    fis_reg_h2d_t *cmdfis = (fis_reg_h2d_t *)&cmdtbl->cfis;
    cmdfis->fis_type = FIS_TYPE_REG_H2D;
    cmdfis->c = 1U;
    cmdfis->command = 0xEAU; /* ATA FLUSH CACHE EXT: persistence barrier. */
    __asm__ volatile("mfence" ::: "memory");
    sata_port->ci = 1U;
    spin = 0U;
    while ((sata_port->ci & 1U) != 0U) {
        if ((sata_port->is & (1U << 30)) != 0U || ++spin > 10000000U) {
            sata_port->is = 0xFFFFFFFFU;
            return 0;
        }
        __asm__ volatile("pause" ::: "memory");
    }
    if ((sata_port->is & (1U << 30)) != 0U ||
        (sata_port->tfd & (0x01U | 0x20U)) != 0U) {
        sata_port->is = 0xFFFFFFFFU;
        return 0;
    }
    __asm__ volatile("mfence" ::: "memory");
    return 1;
}

int ata_flush_cache(void) {
    if (arkm_ramdisk_active || (!nvme_ready && !sata_port)) return 0;
    int ok = 1;
    /* Sector writes prefer NVMe and may fall back to AHCI, so flush every
     * initialized backend to cover a mixed-success sequence. RAMDisk is not
     * a persistence backend and is deliberately rejected above. */
    if (nvme_ready && !nvme_flush_namespace()) ok = 0;
    if (sata_port) {
        uint64_t flags = 0U;
        arkm_lock_irqsave(&arkm_ahci_io_lock, &flags);
        int sata_ok = ahci_flush_cache_unlocked();
        arkm_unlock_irqrestore(&arkm_ahci_io_lock, flags);
        if (!sata_ok) ok = 0;
    }
    return ok;
}

static int ahci_write_sector(uint32_t startlba, const uint8_t *buffer) {
    if (!sata_port || !buffer) return 0;
    log_telemetry(3U, startlba);
    uint64_t flags = 0U;
    arkm_lock_irqsave(&arkm_ahci_io_lock, &flags);
    int ok = ahci_write_sector_unlocked(startlba, buffer);
    arkm_unlock_irqrestore(&arkm_ahci_io_lock, flags);
    return ok;
}

int ata_is_busy(void) {
    /* The primary ATA status port is not a valid modern q35/UEFI fallback. */
    if (sata_port) return (sata_port->tfd & (0x80U | 0x08U)) != 0U;
    return 0;
}

static int arkm_storage_nvme_read_sector(uint32_t lba, uint8_t *buffer) {
    if (!buffer || !nvme_ready) return 0;
    if (((uintptr_t)buffer & 0xFFFU) == 0U)
        return nvme_read_blocks((uint64_t)lba, 1U, buffer);
    uint64_t flags;
    arkm_lock_irqsave(&arkm_storage_bounce_lock, &flags);
    int ok = nvme_read_blocks((uint64_t)lba, 1U, arkm_storage_bounce);
    if (ok) memcpy(buffer, arkm_storage_bounce, 512U);
    arkm_unlock_irqrestore(&arkm_storage_bounce_lock, flags);
    return ok;
}

static int arkm_storage_nvme_write_sector(uint32_t lba, const uint8_t *buffer) {
    if (!buffer || !nvme_ready) return 0;
    if (((uintptr_t)buffer & 0xFFFU) == 0U)
        return nvme_write_blocks((uint64_t)lba, 1U, (void*)buffer);
    uint64_t flags;
    arkm_lock_irqsave(&arkm_storage_bounce_lock, &flags);
    memcpy(arkm_storage_bounce, buffer, 512U);
    int ok = nvme_write_blocks((uint64_t)lba, 1U, arkm_storage_bounce);
    arkm_unlock_irqrestore(&arkm_storage_bounce_lock, flags);
    return ok;
}

static int arkm_storage_read_sector_raw(uint32_t lba, uint8_t* buffer) {
    if (!buffer) return 0;
    if (!arkm_ramdisk_active) {
        if (nvme_ready && arkm_storage_nvme_read_sector(lba, buffer)) return 1;
        if (sata_port && ahci_read_sector(lba, buffer)) return 1;

        /* Use RAMDisk only when no hardware backend was discovered. A live
         * device I/O error must not silently switch to another disk image. */
        if (!nvme_ready && !sata_port) arkm_ramdisk_active = 1U;
        else {
            memset(buffer, 0, 512U);
            if (__atomic_exchange_n(&arkm_storage_error_reported, 1U,
                                    __ATOMIC_ACQ_REL) == 0U)
                qemu_serial_write("[STORAGE] sector read failed; hardware backend retained\n");
            log_telemetry(9U, ((uint64_t)lba << 1) | 1U);
            return 0;
        }
    }

    if (lba < ARKM_RAMDISK_SECTORS) {
        memcpy(buffer, &arkm_ramdisk[(size_t)lba * 512U], 512U);
        return 1;
    }
    memset(buffer, 0, 512U);
    return 0;
}

static int arkm_storage_write_sector_raw(uint32_t lba, const uint8_t* buffer) {
    if (!buffer) return 0;
    if (!arkm_ramdisk_active) {
        if (nvme_ready && arkm_storage_nvme_write_sector(lba, buffer)) return 1;
        if (sata_port && ahci_write_sector(lba, buffer)) return 1;

        /* Never mask a real hardware write failure by persisting to RAMDisk. */
        if (!nvme_ready && !sata_port) arkm_ramdisk_active = 1U;
        else {
            if (__atomic_exchange_n(&arkm_storage_error_reported, 1U,
                                    __ATOMIC_ACQ_REL) == 0U)
                qemu_serial_write("[STORAGE] sector write failed; hardware backend retained\n");
            log_telemetry(9U, ((uint64_t)lba << 1) | 2U);
            return 0;
        }
    }

    if (lba < ARKM_RAMDISK_SECTORS) {
        memcpy(&arkm_ramdisk[(size_t)lba * 512U], buffer, 512U);
        return 1;
    }
    return 0;
}

int ata_read_sector(uint32_t lba, uint8_t* buffer) {
    if (!buffer) return 0;
    /* Keep cache state and the backing-sector image ordered across CPUs. */
    uint64_t io_irq;
    arkm_lock_irqsave(&arkm_storage_io_lock, &io_irq);
    if (advanced_cache_lookup((uint64_t)lba, buffer)) {
        arkm_unlock_irqrestore(&arkm_storage_io_lock, io_irq);
        return 1;
    }
    int ok = arkm_storage_read_sector_raw(lba, buffer);
    if (ok) (void)advanced_cache_store((uint64_t)lba, buffer, 0U);
    arkm_unlock_irqrestore(&arkm_storage_io_lock, io_irq);
    return ok;
}

int ata_write_sector(uint32_t lba, const uint8_t* buffer) {
    if (!buffer) return 0;
    uint64_t io_irq;
    arkm_lock_irqsave(&arkm_storage_io_lock, &io_irq);

    /* Reserve a non-evictable after-image before I/O. Success marks it clean;
     * failure leaves it pinned until an explicit journal-aware retry. */
    if (!advanced_cache_store((uint64_t)lba, buffer, 1U)) {
        /* All cache slots may be pinned dirty after earlier device failures.
         * Do not issue a write that cannot preserve its after-image on error. */
        arkm_unlock_irqrestore(&arkm_storage_io_lock, io_irq);
        return 0;
    }
    int ok = arkm_storage_write_sector_raw(lba, buffer);
    if (ok) (void)advanced_cache_store((uint64_t)lba, buffer, 0U);

    arkm_unlock_irqrestore(&arkm_storage_io_lock, io_irq);
    return ok;
}


static int arkm_pci_ecam_region_for_bus(uint8_t bus, uint32_t* out_index) {
    for (uint32_t i = 0; i < arkm_pci_ecam_region_count; i++) {
        arkm_pci_ecam_region_t* r = &arkm_pci_ecam_regions[i];
        if (!r->valid) continue;
        if (r->segment_group != 0U) continue; /* public API is segment-0 */
        if (bus >= r->start_bus && bus <= r->end_bus) {
            if (out_index) *out_index = i;
            return 1;
        }
    }
    return 0;
}

static int arkm_pci_ecam_map_2m(uint64_t virt, uint64_t phys) {
    const uint64_t pml4_idx = (virt >> 39) & 0x1FFULL;
    const uint64_t pdp_idx  = (virt >> 30) & 0x1FFULL;
    const uint64_t pd_idx   = (virt >> 21) & 0x1FFULL;

    if ((virt & 0x1FFFFFULL) || (phys & 0x1FFFFFULL)) return 0;
    /* This mapper owns only PML4[0]/PDP[4] (virtual 4-5 GiB). */
    if (pml4_idx != 0ULL || pdp_idx != 4ULL) return 0;
    /* A 2-MiB leaf must fit the architectural address field without truncation. */
    if (phys > 0x000FFFFFFFE00000ULL) return 0;

    uint64_t* pml4 = p4_table;
    if (!(pml4[pml4_idx] & 1ULL)) {
        uint64_t* new_pdp = (uint64_t*)pmm_alloc_page();
        if (!new_pdp) return 0;
        memset(new_pdp, 0, PAGE_SIZE);
        pml4[pml4_idx] = (uint64_t)new_pdp | 0x03ULL;
    }

    uint64_t* pdp = (uint64_t*)(pml4[pml4_idx] & ~0xFFFULL);
    if (pdp[pdp_idx] & (1ULL << 7)) return 0; /* 1-GiB leaf conflict */
    if (!(pdp[pdp_idx] & 1ULL)) {
        uint64_t* new_pd = (uint64_t*)pmm_alloc_page();
        if (!new_pd) return 0;
        memset(new_pd, 0, PAGE_SIZE);
        pdp[pdp_idx] = (uint64_t)new_pd | 0x03ULL;
    }

    uint64_t* pd = (uint64_t*)(pdp[pdp_idx] & ~0xFFFULL);
    uint64_t existing = pd[pd_idx];
    uint64_t wanted = (phys & 0x000FFFFFFFE00000ULL) | ARKM_PCI_ECAM_PDE_FLAGS;

    if (existing & 1ULL) {
        const uint64_t cache_mask = (1ULL << 3) | (1ULL << 4) | (1ULL << 12);
        if ((existing & 0x000FFFFFFFE00000ULL) !=
            (phys & 0x000FFFFFFFE00000ULL) || !(existing & (1ULL << 7)) ||
            (existing & cache_mask) != (wanted & cache_mask)) return 0;
        return 1;
    }

    pd[pd_idx] = wanted;
    __asm__ volatile("invlpg (%0)" : : "r"(virt) : "memory");
    return 1;
}

static int arkm_pci_ecam_map_region(uint32_t index) {
    if (index >= arkm_pci_ecam_region_count) return 0;
    arkm_pci_ecam_region_t* r = &arkm_pci_ecam_regions[index];
    if (!r->valid) return 0;

    const uint64_t bytes =
        ((uint64_t)r->end_bus - (uint64_t)r->start_bus + 1ULL) << 20;
    if (!bytes || bytes > ARKM_PCI_ECAM_WINDOW_BYTES ||
        r->phys_base > UINT64_MAX - bytes) return 0;

    const uint64_t phys_start = r->phys_base & ~0x1FFFFFULL;
    const uint64_t phys_offset = r->phys_base - phys_start;
    if (bytes > UINT64_MAX - phys_offset - 0x1FFFFFULL) return 0;
    const uint64_t map_size =
        (bytes + phys_offset + 0x1FFFFFULL) & ~0x1FFFFFULL;
    if (!map_size || map_size > ARKM_PCI_ECAM_WINDOW_BYTES ||
        phys_start > UINT64_MAX - map_size) return 0;
    const uint64_t virt_offset =
        (uint64_t)index * ARKM_PCI_ECAM_WINDOW_BYTES;
    const uint64_t virt_start = ARKM_PCI_ECAM_WINDOW_BASE + virt_offset;

    if (virt_start < ARKM_PCI_ECAM_WINDOW_BASE ||
        virt_start >= ARKM_PCI_ECAM_WINDOW_END ||
        map_size > ARKM_PCI_ECAM_WINDOW_END - virt_start) return 0;

    for (uint64_t off = 0; off < map_size; off += 0x200000ULL) {
        if (!arkm_pci_ecam_map_2m(virt_start + off, phys_start + off)) return 0;
    }

    r->phys_map_base = phys_start;
    r->virt_base = virt_start;
    r->map_size = map_size;
    return 1;
}

static volatile uint32_t* arkm_pci_ecam_ptr(uint8_t bus, uint8_t slot, uint8_t func, uint8_t offset) {
    uint32_t index = 0;
    if (!arkm_pci_ecam_ready || !arkm_pci_ecam_region_for_bus(bus, &index)) return NULL;
    arkm_pci_ecam_region_t* r = &arkm_pci_ecam_regions[index];
    uint64_t phys = r->phys_base + (((uint64_t)bus - r->start_bus) << 20) +
                    ((uint64_t)slot << 15) + ((uint64_t)func << 12) + (offset & 0xFFCULL);
    if (phys < r->phys_map_base || phys + 4ULL > r->phys_map_base + r->map_size) return NULL;
    return (volatile uint32_t*)(r->virt_base + (phys - r->phys_map_base));
}

uint16_t pci_config_read_word(uint8_t bus, uint8_t slot, uint8_t func, uint8_t offset) {
    uint64_t flags;
    arkm_lock_irqsave(&pci_config_lock, &flags);
    volatile uint32_t* ecam = arkm_pci_ecam_ptr(bus, slot, func, offset);
    uint32_t data = ecam ? *ecam : 0xFFFFFFFFU;
    arkm_unlock_irqrestore(&pci_config_lock, flags);
    if (!ecam) return 0xFFFFU;
    return (uint16_t)((data >> ((offset & 2U) * 8U)) & 0xFFFFU);
}

void pci_config_write_word(uint8_t bus, uint8_t slot, uint8_t func,
                           uint8_t offset, uint16_t value) {
    if (offset == 0x04U && !arkm_iommu_pci_command_allowed(bus, slot, func, value))
        return;
    uint64_t flags;
    arkm_lock_irqsave(&pci_config_lock, &flags);
    volatile uint32_t* ecam = arkm_pci_ecam_ptr(bus, slot, func, offset);
    if (ecam) {
        uint32_t old = *ecam;
        uint32_t shift = (offset & 2U) * 8U;
        *ecam = (old & ~(0xFFFFU << shift)) | ((uint32_t)value << shift);
    }
    arkm_unlock_irqrestore(&pci_config_lock, flags);
}

void pci_config_write_dword(uint8_t bus, uint8_t slot, uint8_t func,
                            uint8_t offset, uint32_t value) {
    if (offset == 0x04U && (value & 0x0004U) &&
        !arkm_iommu_pci_command_allowed(bus, slot, func, (uint16_t)value))
        return;
    uint64_t flags;
    arkm_lock_irqsave(&pci_config_lock, &flags);
    volatile uint32_t* ecam = arkm_pci_ecam_ptr(bus, slot, func, offset);
    if (ecam) *ecam = value;
    arkm_unlock_irqrestore(&pci_config_lock, flags);
}

uint32_t pci_config_read_dword(uint8_t bus, uint8_t slot, uint8_t func, uint8_t offset) {
    uint64_t flags;
    arkm_lock_irqsave(&pci_config_lock, &flags);
    volatile uint32_t* ecam = arkm_pci_ecam_ptr(bus, slot, func, offset);
    uint32_t data = ecam ? *ecam : 0xFFFFFFFFU;
    arkm_unlock_irqrestore(&pci_config_lock, flags);
    return data;
}


static void arkm_pci_ecam_diag_hex(const char* label, uint64_t value) {
    char text[19];
    itoa_hex(value, text);
    qemu_serial_write(label);
    qemu_serial_write(text);
    qemu_serial_write("\n");
}

int ecam_init(void) {
    memset(arkm_pci_ecam_regions, 0, sizeof(arkm_pci_ecam_regions));
    arkm_pci_ecam_region_count = 0;
    arkm_pci_ecam_ready = 0;
    ecam_base = NULL;
    qemu_serial_write("[PCI-ECAM] MCFG discovery begin\n");

    struct ACPISDTHeader* hdr = arkm_x_acpi_table("MCFG");
    if (!hdr || hdr->Length < sizeof(arkm_pci_mcfg_header_t)) {
        qemu_serial_write("[PCI-ECAM] MCFG missing or invalid\n");
        return 0;
    }

    const uint32_t entries_bytes =
        hdr->Length - (uint32_t)sizeof(arkm_pci_mcfg_header_t);
    if ((entries_bytes % (uint32_t)sizeof(arkm_pci_mcfg_entry_t)) != 0U) {
        qemu_serial_write("[PCI-ECAM] malformed MCFG allocation table length\n");
        return 0;
    }

    arkm_pci_mcfg_header_t* mcfg = (arkm_pci_mcfg_header_t*)hdr;
    uint32_t count = entries_bytes / (uint32_t)sizeof(arkm_pci_mcfg_entry_t);
    if (count > ARKM_PCI_MCFG_MAX_REGIONS) count = ARKM_PCI_MCFG_MAX_REGIONS;
    arkm_pci_ecam_diag_hex("[PCI-ECAM] MCFG length=", hdr->Length);
    arkm_pci_ecam_diag_hex("[PCI-ECAM] MCFG allocation count=", count);

    arkm_pci_mcfg_entry_t* entries =
        (arkm_pci_mcfg_entry_t*)((uint8_t*)mcfg + sizeof(arkm_pci_mcfg_header_t));

    for (uint32_t i = 0; i < count; i++) {
        arkm_pci_mcfg_entry_t* e = &entries[i];
        if (e->start_bus > e->end_bus || !e->base_address ||
            e->segment_group != 0U) continue;
        if (arkm_pci_ecam_region_count >= ARKM_PCI_MCFG_MAX_REGIONS) break;

        const uint32_t region_index = arkm_pci_ecam_region_count;
        arkm_pci_ecam_region_t* r = &arkm_pci_ecam_regions[region_index];
        r->phys_base = e->base_address;
        r->segment_group = e->segment_group;
        r->start_bus = e->start_bus;
        r->end_bus = e->end_bus;
        r->valid = 1U;
        arkm_pci_ecam_region_count++;
        arkm_pci_ecam_diag_hex("[PCI-ECAM] region physical base=", r->phys_base);
        arkm_pci_ecam_diag_hex("[PCI-ECAM] region bus start/end=",
                               ((uint64_t)r->start_bus << 8) | r->end_bus);
    }

    for (uint32_t i = 0; i < arkm_pci_ecam_region_count; i++) {
        arkm_pci_ecam_region_t* r = &arkm_pci_ecam_regions[i];
        if (!arkm_pci_ecam_map_region(i)) {
            qemu_serial_write("[PCI-ECAM] region mapping FAILED\n");
            r->valid = 0U;
            continue;
        }
        arkm_pci_ecam_diag_hex("[PCI-ECAM] region virtual base=", r->virt_base);
        arkm_pci_ecam_diag_hex("[PCI-ECAM] region mapped bytes=", r->map_size);
        if (!ecam_base) ecam_base = (void*)r->virt_base;
    }

    for (uint32_t i = 0; i < arkm_pci_ecam_region_count; i++) {
        if (arkm_pci_ecam_regions[i].valid) {
            arkm_pci_ecam_ready = 1U;
            break;
        }
    }

    if (arkm_pci_ecam_ready) {
        qemu_serial_write("[PCI-ECAM] READY: dedicated 4-5 GiB virtual aperture\n");
        arkm_pci_ecam_diag_hex("[PCI-ECAM] bus0 slot5 config ID=",
                               pci_ecam_read_dword(0U, 5U, 0U, 0x00U));
        return 1;
    }
    qemu_serial_write("[PCI-ECAM] FAILED: no usable segment-0 MCFG region\n");
    return 0;
}

uint32_t pci_ecam_read_dword(uint8_t bus, uint8_t slot, uint8_t func, uint8_t offset) {
    uint64_t flags;
    arkm_lock_irqsave(&pci_config_lock, &flags);
    volatile uint32_t* ecam = arkm_pci_ecam_ptr(bus, slot, func, offset);
    uint32_t data = ecam ? *ecam : 0xFFFFFFFFU;
    arkm_unlock_irqrestore(&pci_config_lock, flags);
    return data;
}

// ==========================================
// NVMe ADMIN/BLOCK I/O (QEMU + PCIe)
// ==========================================
#define NVME_REG_CAP   0x0000
#define NVME_REG_VS    0x0008
#define NVME_REG_INTMS 0x000C
#define NVME_REG_INTMC 0x0010
#define NVME_REG_CC    0x0014
#define NVME_REG_CSTS  0x001C
#define NVME_REG_AQA   0x0024
#define NVME_REG_ASQ   0x0028
#define NVME_REG_ACQ   0x0030

#define NVME_CC_EN       0x00000001U
#define NVME_CSTS_RDY    0x00000001U
#define NVME_CSTS_CFS    0x00000002U
#define NVME_ADMIN_IDENTIFY 0x06
#define NVME_ADMIN_CREATE_IO_CQ 0x05
#define NVME_ADMIN_CREATE_IO_SQ 0x01
#define NVME_NVM_READ  0x02
#define NVME_NVM_WRITE 0x01

#define NVME_ADMIN_Q_DEPTH 16
#define NVME_IO_Q_DEPTH 32
#define NVME_PAGE_BYTES 4096


typedef struct __attribute__((packed)) {
    uint8_t  opcode;
    uint8_t  flags;
    uint16_t cid;
    uint32_t nsid;
    uint32_t cdw2;
    uint32_t cdw3;
    uint64_t metadata;
    uint64_t prp1;
    uint64_t prp2;
    uint32_t cdw10;
    uint32_t cdw11;
    uint32_t cdw12;
    uint32_t cdw13;
    uint32_t cdw14;
    uint32_t cdw15;
} nvme_cmd_t;

typedef struct __attribute__((packed)) {
    uint32_t dw0;
    uint32_t dw1;
    uint16_t sq_head;
    uint16_t sq_id;
    uint16_t cid;
    uint16_t status;
} nvme_cqe_t;

static uint8_t* nvme_admin_sq = NULL;
static uint8_t* nvme_admin_cq = NULL;
static uint8_t* nvme_identify_buf = NULL;
static uint8_t* nvme_io_sq = NULL;
static uint8_t* nvme_io_cq = NULL;
static uint8_t arkm_nvme_pci_bus = 0U;
static uint8_t arkm_nvme_pci_slot = 0U;
static uint8_t arkm_nvme_pci_func = 0U;
static uint64_t nvme_bar_base = 0;
static uint16_t nvme_admin_tail = 0;
static uint16_t nvme_admin_phase = 1;
static uint16_t nvme_io_tail = 0;
static uint16_t nvme_io_cq_head = 0;
static uint16_t nvme_io_phase = 1;
static uint16_t nvme_next_cid = 1;
static uint32_t nvme_doorbell_stride = 4;
static uint32_t nvme_namespace_id = 1;
static uint32_t nvme_block_size = 512;
volatile uint8_t nvme_ready = 0;
static spinlock_t nvme_lock = 0;

// NVMe MSI configuration: fixed Local APIC vector reserved for the controller.
#define NVME_MSI_VECTOR 45
static volatile uint8_t nvme_msi_enabled = 0;
static volatile uint32_t nvme_msi_irq_count = 0;
static volatile uint8_t nvme_msi_pending = 0;
static volatile uint8_t e1000_msi_enabled = 0;
static volatile uint32_t e1000_irq_count = 0;

static uint64_t nvme_virt_to_phys(uint64_t virt) {
    uint64_t p = e1000_virt_to_phys(virt);
    return p;
}

static volatile uint32_t* nvme_reg32(uint32_t off) {
    return (volatile uint32_t*)(nvme_bar_base + off);
}
static volatile uint64_t* nvme_reg64(uint32_t off) {
    return (volatile uint64_t*)(nvme_bar_base + off);
}

static void nvme_disable_controller(void) {
    uint32_t cc = *nvme_reg32(NVME_REG_CC);
    *nvme_reg32(NVME_REG_CC) = cc & ~NVME_CC_EN;
    for (uint32_t i = 0; i < 1000000U; i++) {
        if (!(*nvme_reg32(NVME_REG_CSTS) & NVME_CSTS_RDY)) return;
        __asm__ volatile("pause");
    }
}

static int nvme_wait_ready(int ready) {
    for (uint32_t i = 0; i < 1000000U; i++) {
        uint32_t csts = *nvme_reg32(NVME_REG_CSTS);
        if (csts & NVME_CSTS_CFS) return 0;
        if (!!(csts & NVME_CSTS_RDY) == !!ready) return 1;
        __asm__ volatile("pause");
    }
    return 0;
}

static int nvme_submit_admin(nvme_cmd_t* cmd, void* data, uint32_t* status_out) {
    if (!nvme_ready && !nvme_admin_sq) return 0;
    uint64_t flags;
    arkm_lock_irqsave(&nvme_lock, &flags);
    nvme_cmd_t* sq = (nvme_cmd_t*)nvme_admin_sq;
    nvme_cqe_t* cq = (nvme_cqe_t*)nvme_admin_cq;
    uint16_t cid = nvme_next_cid++;
    cmd->cid = cid;
    if (data) {
        uint64_t dma_data = 0ULL;
        if (!arkm_iommu_prepare_dma(arkm_nvme_pci_bus, arkm_nvme_pci_slot,
                                    arkm_nvme_pci_func, nvme_virt_to_phys((uint64_t)data),
                                    PAGE_SIZE, 3U, &dma_data)) {
            arkm_unlock_irqrestore(&nvme_lock, flags);
            return 0;
        }
        cmd->prp1 = dma_data;
    }
    sq[nvme_admin_tail] = *cmd;
    nvme_admin_tail = (uint16_t)((nvme_admin_tail + 1) % NVME_ADMIN_Q_DEPTH);
    *(volatile uint32_t*)(nvme_bar_base + 0x1000U + nvme_doorbell_stride * 0U) = nvme_admin_tail;
    for (uint32_t spin = 0; spin < 1000000U; spin++) {
        nvme_cqe_t c = cq[0];
        uint16_t phase = c.status & 1U;
        if (c.cid == cid && phase == nvme_admin_phase) {
            if (status_out) *status_out = (uint32_t)c.status;
            arkm_unlock_irqrestore(&nvme_lock, flags);
            return ((c.status >> 1) & 0x7FFU) == 0;
        }
        __asm__ volatile("pause");
    }
    arkm_unlock_irqrestore(&nvme_lock, flags);
    return 0;
}

// --------------------------------------------------------------------------
// NVMe MSI support
// --------------------------------------------------------------------------
int pci_enable_msi(uint8_t bus, uint8_t slot, uint8_t func, uint8_t vector) {
    uint16_t status = pci_config_read_word(bus, slot, func, 0x06);
    if (!(status & 0x0010U)) return 0; // PCI status: capabilities list

    uint8_t cap_ptr = (uint8_t)(pci_config_read_word(bus, slot, func, 0x34) & 0xFFU);
    for (uint32_t guard = 0; guard < 48 && cap_ptr >= 0x40; guard++) {
        uint16_t cap = pci_config_read_word(bus, slot, func, cap_ptr);
        uint8_t cap_id = (uint8_t)(cap & 0xFFU);
        uint8_t next = (uint8_t)(cap >> 8);
        if (cap_id == 0x05) { // MSI capability
            uint16_t ctrl = pci_config_read_word(bus, slot, func, (uint8_t)(cap_ptr + 2));
            uint16_t new_ctrl = (uint16_t)(ctrl & ~(1U << 7)); // disable MSI while programming
            pci_config_write_word(bus, slot, func, (uint8_t)(cap_ptr + 2), new_ctrl);

            uint32_t msi_addr_lo = 0xFEE00000U;
            uint8_t apic_dest = (total_cpu_cores > 0) ? local_apic_ids[0] : (uint8_t)get_core_id();
            msi_addr_lo |= ((uint32_t)apic_dest << 12);
            pci_config_write_dword(bus, slot, func, (uint8_t)(cap_ptr + 4), msi_addr_lo);

            if (ctrl & (1U << 7)) {
                // 64-bit capable MSI: write the high half of the message address.
                pci_config_write_dword(bus, slot, func, (uint8_t)(cap_ptr + 8), 0);
                pci_config_write_word(bus, slot, func, (uint8_t)(cap_ptr + 12), vector);
            } else {
                pci_config_write_word(bus, slot, func, (uint8_t)(cap_ptr + 8), vector);
            }

            // Enable MSI and request exactly one message.
            new_ctrl = (uint16_t)((ctrl & ~0x0070U) | (ctrl & 0x0070U) | (1U << 7));
            // Multiple Message Enable = 0 (one vector); clear mask bit if present.
            new_ctrl &= ~(1U << 8);
            pci_config_write_word(bus, slot, func, (uint8_t)(cap_ptr + 2), new_ctrl);
            return 1;
        }
        if (next == 0 || next == cap_ptr) break;
        cap_ptr = next;
    }
    return 0;
}

void nvme_msi_handler_c(void) {
    nvme_msi_irq_count++;
    nvme_msi_pending = 1;
    advanced_trace(0x31, NVME_MSI_VECTOR, nvme_msi_irq_count);

    // EOI to the Local APIC. ACPI supplies the architectural APIC base.
    volatile uint32_t* eoi = (volatile uint32_t*)((uint64_t)(local_apic_base ? local_apic_base : 0xFEE00000U) + 0xB0U);
    *eoi = 0;
}

__attribute__((naked)) void nvme_stub(void) {
    __asm__ volatile(
        "pushq %rax\n\t"
        "pushq %rbx\n\t"
        "pushq %rcx\n\t"
        "pushq %rdx\n\t"
        "pushq %rsi\n\t"
        "pushq %rdi\n\t"
        "pushq %rbp\n\t"
        "pushq %r8\n\t"
        "pushq %r9\n\t"
        "pushq %r10\n\t"
        "pushq %r11\n\t"
        "pushq %r12\n\t"
        "pushq %r13\n\t"
        "pushq %r14\n\t"
        "pushq %r15\n\t"
        "call nvme_msi_handler_c\n\t"
        "popq %r15\n\t"
        "popq %r14\n\t"
        "popq %r13\n\t"
        "popq %r12\n\t"
        "popq %r11\n\t"
        "popq %r10\n\t"
        "popq %r9\n\t"
        "popq %r8\n\t"
        "popq %rbp\n\t"
        "popq %rdi\n\t"
        "popq %rsi\n\t"
        "popq %rdx\n\t"
        "popq %rcx\n\t"
        "popq %rbx\n\t"
        "popq %rax\n\t"
        "iretq\n\t"
    );
}

void nvme_init(uint32_t bar0) {
    nvme_ready = 0;
    if (!bar0) return;
    nvme_bar_base = (uint64_t)(bar0 & 0xFFFFFFF0U);
    if (!nvme_bar_base) return;
    uint64_t cap = *nvme_reg64(NVME_REG_CAP);
    nvme_doorbell_stride = 4U << ((uint32_t)((cap >> 32) & 0x0FU));

    // Enable PCI memory-space and bus-mastering before touching controller MMIO.
    // The PCI probe performs this as well; this is deliberately idempotent.
    nvme_admin_sq = (uint8_t*)pmm_alloc_page();
    nvme_admin_cq = (uint8_t*)pmm_alloc_page();
    nvme_identify_buf = (uint8_t*)pmm_alloc_page();
    nvme_io_sq = (uint8_t*)pmm_alloc_page();
    nvme_io_cq = (uint8_t*)pmm_alloc_page();
    if (!nvme_admin_sq || !nvme_admin_cq || !nvme_identify_buf || !nvme_io_sq || !nvme_io_cq) return;

    memset(nvme_admin_sq, 0, PAGE_SIZE);
    memset(nvme_admin_cq, 0, PAGE_SIZE);
    memset(nvme_identify_buf, 0, PAGE_SIZE);
    memset(nvme_io_sq, 0, PAGE_SIZE);
    memset(nvme_io_cq, 0, PAGE_SIZE);

    /* Stage the five persistent DMA pages in this controller's private
     * requester domain before publishing queue addresses to hardware. */
    if (!arkm_iommu_prepare_dma(arkm_nvme_pci_bus, arkm_nvme_pci_slot,
                                arkm_nvme_pci_func, (uint64_t)nvme_admin_sq,
                                PAGE_SIZE, 3U, NULL) ||
        !arkm_iommu_prepare_dma(arkm_nvme_pci_bus, arkm_nvme_pci_slot,
                                arkm_nvme_pci_func, (uint64_t)nvme_admin_cq,
                                PAGE_SIZE, 3U, NULL) ||
        !arkm_iommu_prepare_dma(arkm_nvme_pci_bus, arkm_nvme_pci_slot,
                                arkm_nvme_pci_func, (uint64_t)nvme_identify_buf,
                                PAGE_SIZE, 3U, NULL) ||
        !arkm_iommu_prepare_dma(arkm_nvme_pci_bus, arkm_nvme_pci_slot,
                                arkm_nvme_pci_func, (uint64_t)nvme_io_sq,
                                PAGE_SIZE, 3U, NULL) ||
        !arkm_iommu_prepare_dma(arkm_nvme_pci_bus, arkm_nvme_pci_slot,
                                arkm_nvme_pci_func, (uint64_t)nvme_io_cq,
                                PAGE_SIZE, 3U, NULL)) return;
    /* First stop any firmware-owned queue context while bus mastering remains
     * disabled.  Only then may this driver publish its staged queues and grant
     * the controller DMA permission. */
    nvme_disable_controller();
    uint16_t pci_cmd = pci_config_read_word(arkm_nvme_pci_bus,
                                             arkm_nvme_pci_slot,
                                             arkm_nvme_pci_func, 0x04U);
    pci_config_write_word(arkm_nvme_pci_bus, arkm_nvme_pci_slot,
                          arkm_nvme_pci_func, 0x04U,
                          (uint16_t)(pci_cmd | 0x0006U));
    uint64_t asq = nvme_virt_to_phys((uint64_t)nvme_admin_sq);
    uint64_t acq = nvme_virt_to_phys((uint64_t)nvme_admin_cq);
    uint64_t iosq = nvme_virt_to_phys((uint64_t)nvme_io_sq);
    uint64_t iocq = nvme_virt_to_phys((uint64_t)nvme_io_cq);
    if (!asq || !acq || !iosq || !iocq) return;

    *nvme_reg32(NVME_REG_AQA) = ((NVME_ADMIN_Q_DEPTH - 1) << 16) | (NVME_ADMIN_Q_DEPTH - 1);
    *nvme_reg64(NVME_REG_ASQ) = asq;
    *nvme_reg64(NVME_REG_ACQ) = acq;

    uint32_t cc = *nvme_reg32(NVME_REG_CC);
    cc &= ~0x00FF00FFU;
    cc |= (0 << 4);      // CSS NVM
    cc |= (6 << 16);     // MPS=4KiB
    *nvme_reg32(NVME_REG_CC) = cc | NVME_CC_EN;
    if (!nvme_wait_ready(1)) return;

    // MSI replaces legacy INTx notification; clear the controller interrupt mask.
    if (nvme_msi_enabled) {
        *nvme_reg32(NVME_REG_INTMC) = 0x00000001U;
    }

    nvme_cmd_t identify;
    memset(&identify, 0, sizeof(identify));
    identify.opcode = NVME_ADMIN_IDENTIFY;
    identify.nsid = 0;
    identify.cdw10 = 1; // Identify Controller
    nvme_identify_buf[0] = 0;
    uint32_t status = 0;
    (void)nvme_submit_admin(&identify, nvme_identify_buf, &status);

    // Standard Identify Namespace geometry is used when namespace 1 is present.
    nvme_namespace_id = 1;
    uint8_t flbas = nvme_identify_buf[26];
    uint32_t lbaf_index = flbas & 0x0FU;
    uint32_t lbaf_off = 128U + lbaf_index * 4U;
    uint8_t lbads = nvme_identify_buf[lbaf_off + 2];
    if (lbads < 9 || lbads > 16) lbads = 9;
    nvme_block_size = 1U << lbads;

    // Create I/O completion queue then submission queue using the physical pages above.
    memset(&identify, 0, sizeof(identify));
    identify.opcode = NVME_ADMIN_CREATE_IO_CQ;
    identify.prp1 = iocq;
    identify.cdw10 = ((NVME_IO_Q_DEPTH - 1) << 16) | 1;
    identify.cdw11 = 1;
    (void)nvme_submit_admin(&identify, NULL, NULL);

    memset(&identify, 0, sizeof(identify));
    identify.opcode = NVME_ADMIN_CREATE_IO_SQ;
    identify.prp1 = iosq;
    identify.cdw10 = ((NVME_IO_Q_DEPTH - 1) << 16) | 1;
    identify.cdw11 = (1 << 16) | 1;
    (void)nvme_submit_admin(&identify, NULL, NULL);

    nvme_admin_tail = 0;
    nvme_io_tail = 0;
    nvme_io_cq_head = 0;
    nvme_io_phase = 1;
    nvme_ready = 1;
}

int nvme_read_blocks(uint64_t lba, uint32_t count, void* buffer) {
    if (!nvme_ready || !buffer || count == 0 || nvme_block_size != 512) return 0;
    if (((uint64_t)buffer & 0xFFFULL) != 0) return 0;
    if (count * nvme_block_size > PAGE_SIZE) return 0;
    if (!arkm_iommu_prepare_dma(arkm_nvme_pci_bus, arkm_nvme_pci_slot,
                                arkm_nvme_pci_func, (uint64_t)buffer,
                                (uint64_t)count * nvme_block_size, 3U, NULL)) return 0;
    uint64_t flags;
    arkm_lock_irqsave(&nvme_lock, &flags);
    nvme_cmd_t* sq = (nvme_cmd_t*)nvme_io_sq;
    nvme_cqe_t* cq = (nvme_cqe_t*)nvme_io_cq;
    uint16_t cid = nvme_next_cid++;
    nvme_cmd_t cmd;
    memset(&cmd, 0, sizeof(cmd));
    cmd.opcode = NVME_NVM_READ;
    cmd.cid = cid;
    cmd.nsid = nvme_namespace_id;
    cmd.prp1 = nvme_virt_to_phys((uint64_t)buffer);
    cmd.cdw10 = (uint32_t)lba;
    cmd.cdw11 = (uint32_t)(lba >> 32);
    cmd.cdw12 = count - 1;
    sq[nvme_io_tail] = cmd;
    nvme_io_tail = (uint16_t)((nvme_io_tail + 1) % NVME_IO_Q_DEPTH);
    *(volatile uint32_t*)(nvme_bar_base + 0x1000U + nvme_doorbell_stride * 2U) = nvme_io_tail;
    for (uint32_t spin = 0; spin < 1000000U; spin++) {
        nvme_cqe_t c = cq[nvme_io_cq_head];
        uint16_t phase = c.status & 1U;
        if (c.cid == cid && phase == nvme_io_phase) {
            nvme_io_cq_head = (uint16_t)((nvme_io_cq_head + 1) % NVME_IO_Q_DEPTH);
            if (nvme_io_cq_head == 0) nvme_io_phase ^= 1;
            arkm_unlock_irqrestore(&nvme_lock, flags);
            return ((c.status >> 1) & 0x7FFU) == 0;
        }
        __asm__ volatile("pause");
    }
    arkm_unlock_irqrestore(&nvme_lock, flags);
    return 0;
}

int nvme_write_blocks(uint64_t lba, uint32_t count, const void* buffer) {
    if (!nvme_ready || !buffer || count == 0 || nvme_block_size != 512) return 0;
    if (((uint64_t)buffer & 0xFFFULL) != 0) return 0;
    if (count * nvme_block_size > PAGE_SIZE) return 0;
    if (!arkm_iommu_prepare_dma(arkm_nvme_pci_bus, arkm_nvme_pci_slot,
                                arkm_nvme_pci_func, (uint64_t)buffer,
                                (uint64_t)count * nvme_block_size, 3U, NULL)) return 0;
    uint64_t flags;
    arkm_lock_irqsave(&nvme_lock, &flags);
    nvme_cmd_t* sq = (nvme_cmd_t*)nvme_io_sq;
    nvme_cqe_t* cq = (nvme_cqe_t*)nvme_io_cq;
    uint16_t cid = nvme_next_cid++;
    nvme_cmd_t cmd;
    memset(&cmd, 0, sizeof(cmd));
    cmd.opcode = NVME_NVM_WRITE;
    cmd.cid = cid;
    cmd.nsid = nvme_namespace_id;
    cmd.prp1 = nvme_virt_to_phys((uint64_t)buffer);
    cmd.cdw10 = (uint32_t)lba;
    cmd.cdw11 = (uint32_t)(lba >> 32);
    cmd.cdw12 = count - 1;
    sq[nvme_io_tail] = cmd;
    nvme_io_tail = (uint16_t)((nvme_io_tail + 1) % NVME_IO_Q_DEPTH);
    *(volatile uint32_t*)(nvme_bar_base + 0x1000U + nvme_doorbell_stride * 2U) = nvme_io_tail;
    for (uint32_t spin = 0; spin < 1000000U; spin++) {
        nvme_cqe_t c = cq[nvme_io_cq_head];
        uint16_t phase = c.status & 1U;
        if (c.cid == cid && phase == nvme_io_phase) {
            nvme_io_cq_head = (uint16_t)((nvme_io_cq_head + 1) % NVME_IO_Q_DEPTH);
            if (nvme_io_cq_head == 0) nvme_io_phase ^= 1;
            arkm_unlock_irqrestore(&nvme_lock, flags);
            return ((c.status >> 1) & 0x7FFU) == 0;
        }
        __asm__ volatile("pause");
    }
    arkm_unlock_irqrestore(&nvme_lock, flags);
    return 0;
}

static int nvme_flush_namespace(void) {
    if (!nvme_ready) return 0;
    uint64_t flags;
    arkm_lock_irqsave(&nvme_lock, &flags);
    nvme_cmd_t* sq = (nvme_cmd_t*)nvme_io_sq;
    nvme_cqe_t* cq = (nvme_cqe_t*)nvme_io_cq;
    uint16_t cid = nvme_next_cid++;
    nvme_cmd_t cmd;
    memset(&cmd, 0, sizeof(cmd));
    cmd.opcode = 0x00U; /* NVMe NVM Flush */
    cmd.cid = cid;
    cmd.nsid = nvme_namespace_id;
    sq[nvme_io_tail] = cmd;
    nvme_io_tail = (uint16_t)((nvme_io_tail + 1U) % NVME_IO_Q_DEPTH);
    *(volatile uint32_t*)(nvme_bar_base + 0x1000U + nvme_doorbell_stride * 2U) = nvme_io_tail;
    for (uint32_t spin = 0U; spin < 1000000U; ++spin) {
        nvme_cqe_t c = cq[nvme_io_cq_head];
        uint16_t phase = c.status & 1U;
        if (c.cid == cid && phase == nvme_io_phase) {
            nvme_io_cq_head = (uint16_t)((nvme_io_cq_head + 1U) % NVME_IO_Q_DEPTH);
            if (nvme_io_cq_head == 0U) nvme_io_phase ^= 1U;
            arkm_unlock_irqrestore(&nvme_lock, flags);
            return ((c.status >> 1) & 0x7FFU) == 0U;
        }
        __asm__ volatile("pause" ::: "memory");
    }
    arkm_unlock_irqrestore(&nvme_lock, flags);
    return 0;
}

// ==========================================
// PROTOCOL PARSER & NETWORK DISPATCHER
// ==========================================

void tcp_congestion_control(arkm_socket_t* sock, int event) {
    if (!sock) return;
    switch (event) {
        case 0: // ACK received
            if (sock->cwnd < sock->ssthresh)
                sock->cwnd += 1460;               // slow start
            else
                sock->cwnd += (1460 * 1460) / sock->cwnd; // congestion avoidance
            sock->dup_ack_count = 0;
            sock->fast_retransmit = 0;
            break;
        case 1: // duplicate ACK
            sock->dup_ack_count++;
            if (sock->dup_ack_count == 3) {
                sock->ssthresh = sock->cwnd / 2;
                sock->cwnd = sock->ssthresh + 3 * 1460;
                sock->fast_retransmit = 1;
            }
            break;
        case 2: // timeout
            sock->ssthresh = sock->cwnd / 2;
            sock->cwnd = 1460;
            sock->dup_ack_count = 0;
            sock->fast_retransmit = 0;
            break;
    }
}

// Caller holds net_stack_lock.
void tcp_send_control_locked(arkm_socket_t* sock, uint32_t seq_num, uint32_t ack_num, uint8_t flags) {
    uint8_t out_pkt[128];
    ethernet_hdr_t* eth = (ethernet_hdr_t*)out_pkt;
    ipv4_hdr_t* ip = (ipv4_hdr_t*)(out_pkt + sizeof(ethernet_hdr_t));
    tcp_hdr_t* tcp = (tcp_hdr_t*)(out_pkt + sizeof(ethernet_hdr_t) + sizeof(ipv4_hdr_t));

    uint8_t dest_mac[6] = {0xFF,0xFF,0xFF,0xFF,0xFF,0xFF};
    for (int k = 0; k < MAX_ARP_ENTRIES; k++) {
        if (arp_table[k].valid && arp_table[k].ip == sock->remote_ip) {
            memcpy(dest_mac, arp_table[k].mac, 6);
            break;
        }
    }

    memcpy(eth->dest_mac, dest_mac, 6);
    memcpy(eth->src_mac, mac_addr, 6);
    eth->ethertype = htons(0x0800);

    ip->version_ihl = 0x45;
    ip->tos = 0;
    ip->total_len = htons(sizeof(ipv4_hdr_t) + sizeof(tcp_hdr_t));
    ip->id = htons(0);
    ip->flags_offset = 0;
    ip->ttl = 64;
    ip->protocol = 6;
    ip->src_ip = local_kernel_ip;
    ip->dest_ip = sock->remote_ip;
    ip->checksum = 0;
    ip->checksum = net_checksum(ip, sizeof(ipv4_hdr_t));

    tcp->src_port = htons(sock->local_port);
    tcp->dest_port = htons(sock->remote_port);
    tcp->seq_num = htonl(seq_num);
    tcp->ack_num = htonl(ack_num);
    tcp->data_offset = (sizeof(tcp_hdr_t) / 4) << 4;
    tcp->flags = flags;
    tcp->window_size = htons(8192);
    tcp->checksum = 0;
    tcp->urgent_ptr = 0;

    struct { uint32_t src_ip; uint32_t dest_ip; uint8_t zero; uint8_t protocol; uint16_t tcp_len; } __attribute__((packed)) pseudo;
    pseudo.src_ip = local_kernel_ip;
    pseudo.dest_ip = sock->remote_ip;
    pseudo.zero = 0;
    pseudo.protocol = 6;
    pseudo.tcp_len = htons(sizeof(tcp_hdr_t));

    uint32_t sum = 0;
    uint16_t *ptr = (uint16_t*)&pseudo;
    for (size_t k = 0; k < sizeof(pseudo)/2; k++) sum += ptr[k];
    ptr = (uint16_t*)tcp;
    int count = sizeof(tcp_hdr_t);
    while (count > 1) { sum += *ptr++; count -= 2; }
    if (count) sum += *(uint8_t*)ptr;
    while (sum >> 16) sum = (sum & 0xFFFF) + (sum >> 16);
    tcp->checksum = (uint16_t)(~sum);

    e1000_send_packet(out_pkt, sizeof(ethernet_hdr_t) + sizeof(ipv4_hdr_t) + sizeof(tcp_hdr_t));
}

void net_process_tcp(ipv4_hdr_t* ip, tcp_hdr_t* tcp, uint8_t* payload, uint16_t payload_len) {
    uint16_t dport = ntohs(tcp->dest_port);
    uint16_t sport = ntohs(tcp->src_port);
    uint8_t flags = tcp->flags;
    uint32_t seq = ntohl(tcp->seq_num);
    uint32_t ack = ntohl(tcp->ack_num);
    uint32_t wnd = ntohs(tcp->window_size);

    uint64_t stack_flags;
    arkm_lock_irqsave(&net_stack_lock, &stack_flags);

    int target_sock = -1;
    if ((flags & 0x02) && !(flags & 0x10)) {
        for (int i = 0; i < MAX_SOCKETS; i++) {
            if (socket_table[i].in_use && socket_table[i].local_port == dport && socket_table[i].state == SOCK_STATE_LISTEN) {
                for (int j = 0; j < MAX_SOCKETS; j++) {
                    if (!socket_table[j].in_use) {
                        arkm_socket_t* sck = &socket_table[j];
                        uint32_t accept_pid = socket_table[i].owner_pid;
                        uint32_t accept_generation = socket_table[i].owner_generation;
                        if (!accept_pid || !accept_generation ||
                            !arkm_rm_reserve_identity(accept_pid, accept_generation, ARKM_RM_SOCKETS, 1U)) break;
                        memset(sck, 0, sizeof(*sck));
                        sck->id = j + 3;
                        sck->local_ip = local_kernel_ip;
                        sck->local_port = dport;
                        sck->remote_ip = ip->src_ip;
                        sck->remote_port = sport;
                        sck->state = SOCK_STATE_SYN_RECEIVED;
                        sck->expected_ack = seq + 1;
                        sck->rcv_nxt = seq + 1;
                        sck->snd_una = 0;
                        sck->snd_nxt = 1;
                        sck->snd_wnd = wnd ? wnd : 8192;
                        sck->rwnd = 8192;
                        sck->cwnd = 1460;
                        sck->ssthresh = 65535;
                        sck->protocol = 6;
                        sck->type = 1;
                        sck->owner_pid = accept_pid;
                        sck->owner_generation = accept_generation;
                        sck->in_use = 1;
                        arkm_rm_commit_identity(accept_pid, accept_generation, ARKM_RM_SOCKETS, 1U);
                        sck->accept_claimed = 0;
                        target_sock = j;
                        break;
                    }
                }
                break;
            }
        }
        if (target_sock >= 0) tcp_send_control_locked(&socket_table[target_sock], 0, seq + 1, 0x12);
        arkm_unlock_irqrestore(&net_stack_lock, stack_flags);
        return;
    }

    for (int i = 0; i < MAX_SOCKETS; i++) {
        if (!socket_table[i].in_use) continue;
        if (socket_table[i].local_port != dport || socket_table[i].remote_port != sport || socket_table[i].remote_ip != ip->src_ip) continue;
        target_sock = i;
        break;
    }
    if (target_sock < 0) {
        arkm_unlock_irqrestore(&net_stack_lock, stack_flags);
        return;
    }

    arkm_socket_t* sock = &socket_table[target_sock];
    sock->snd_wnd = wnd ? wnd : sock->snd_wnd;

    if (sock->state == SOCK_STATE_SYN_RECEIVED) {
        if ((flags & 0x10) && ack >= sock->snd_nxt) {
            sock->snd_una = ack;
            sock->last_ack = ack;
            sock->state = SOCK_STATE_ESTABLISHED;
        } else {
            arkm_unlock_irqrestore(&net_stack_lock, stack_flags);
            return;
        }
    }

    if (flags & 0x10) {
        if (ack > sock->snd_una && ack <= sock->snd_nxt) {
            sock->snd_una = ack;
            sock->last_ack = ack;
            tcp_congestion_control(sock, 0);
        } else if (ack == sock->snd_una) {
            tcp_congestion_control(sock, 1);
        }

        if (sock->state == SOCK_STATE_FIN_WAIT_1 && ack >= sock->snd_nxt) {
            sock->fin_acked = 1;
            sock->state = (flags & 0x01) ? SOCK_STATE_CLOSING : SOCK_STATE_FIN_WAIT_2;
        } else if (sock->state == SOCK_STATE_LAST_ACK && ack >= sock->snd_nxt) {
            sock->fin_acked = 1;
            uint32_t owner_pid = sock->owner_pid;
            uint32_t owner_generation = sock->owner_generation;
            sock->state = SOCK_STATE_CLOSED;
            sock->in_use = 0;
            sock->owner_pid = 0U;
            sock->owner_generation = 0U;
            arkm_unlock_irqrestore(&net_stack_lock, stack_flags);
            arkm_rm_release_identity(owner_pid, owner_generation, ARKM_RM_SOCKETS, 1U);
            return;
        }
    }

    if (payload_len > 0 && (sock->state == SOCK_STATE_ESTABLISHED || sock->state == SOCK_STATE_FIN_WAIT_1 || sock->state == SOCK_STATE_FIN_WAIT_2)) {
        if (seq == sock->expected_ack) {
            uint32_t queued = 0U;
            int rx_allowed = !sock->owner_pid ||
                arkm_rm_periodic_admit(sock->owner_pid, sock->owner_generation,
                                       ARKM_RM_PERIODIC_NETWORK, payload_len);
            if (!rx_allowed) {
                sock->rx_dropped_bytes += payload_len;
                sock->rx_quota_drops++;
            }
            uint32_t rx_used = (sock->rx_buffer_head + 4096U - sock->rx_buffer_tail) % 4096U;
            uint32_t rx_free = 4095U - rx_used;
            uint32_t enqueue_len = rx_allowed ? payload_len : 0U;
            if (enqueue_len > rx_free) {
                sock->rx_dropped_bytes += (uint64_t)(enqueue_len - rx_free);
                enqueue_len = rx_free;
            }
            for (uint32_t b = 0U; b < enqueue_len; b++) {
                uint32_t next = (sock->rx_buffer_head + 1U) % 4096U;
                if (next == sock->rx_buffer_tail) break;
                sock->rx_ring[sock->rx_buffer_head] = payload[b];
                sock->rx_buffer_head = next;
                queued++;
            }
            sock->expected_ack = seq + queued;
            sock->rcv_nxt = sock->expected_ack;
            uint32_t new_used = (sock->rx_buffer_head + 4096U - sock->rx_buffer_tail) % 4096U;
            if (new_used > sock->rx_high_watermark) sock->rx_high_watermark = new_used;
            if (queued && sock->owner_pid)
                arkm_rm_network_identity(sock->owner_pid, sock->owner_generation, queued, 0U);
        }
        tcp_send_control_locked(sock, sock->snd_nxt, sock->expected_ack, 0x10);
    }

    if (flags & 0x01) {
        uint32_t fin_seq = seq + payload_len;
        if (fin_seq == sock->expected_ack) sock->expected_ack++;
        sock->rcv_nxt = sock->expected_ack;
        tcp_send_control_locked(sock, sock->snd_nxt, sock->expected_ack, 0x10);

        if (sock->state == SOCK_STATE_FIN_WAIT_1) {
            sock->state = sock->fin_acked ? SOCK_STATE_TIME_WAIT : SOCK_STATE_CLOSING;
            sock->time_wait_until = timer_ticks + 180;
        } else if (sock->state == SOCK_STATE_FIN_WAIT_2 || sock->state == SOCK_STATE_CLOSING) {
            sock->state = SOCK_STATE_TIME_WAIT;
            sock->time_wait_until = timer_ticks + 180;
        } else if (sock->state == SOCK_STATE_ESTABLISHED) {
            sock->state = SOCK_STATE_CLOSE_WAIT;
        }
    }

    arkm_unlock_irqrestore(&net_stack_lock, stack_flags);
}

void net_process_arp(arp_hdr_t* arp) {
    if (!arp) return;

    uint16_t opcode = ntohs(arp->opcode);
    if (opcode != 1 && opcode != 2) return;

    /* Cache both requests and replies.  In particular, PING depends on the
     * QEMU gateway's ARP reply being learned by the guest. */
    uint64_t flags;
    arkm_lock_irqsave(&net_stack_lock, &flags);
    for (int i = 0; i < MAX_ARP_ENTRIES; i++) {
        if (!arp_table[i].valid || arp_table[i].ip == arp->src_ip) {
            arp_table[i].ip = arp->src_ip;
            memcpy(arp_table[i].mac, arp->src_mac, 6);
            arp_table[i].valid = 1;
            break;
        }
    }
    arkm_unlock_irqrestore(&net_stack_lock, flags);

    if (opcode == 1 && arp->dest_ip == local_kernel_ip) {
        uint8_t reply_buf[sizeof(ethernet_hdr_t) + sizeof(arp_hdr_t)];
        ethernet_hdr_t* eth_out = (ethernet_hdr_t*)reply_buf;
        arp_hdr_t* arp_out = (arp_hdr_t*)(reply_buf + sizeof(ethernet_hdr_t));

        memcpy(eth_out->dest_mac, arp->src_mac, 6);
        memcpy(eth_out->src_mac, mac_addr, 6);
        eth_out->ethertype = htons(0x0806);

        arp_out->hw_type = htons(1);
        arp_out->proto_type = htons(0x0800);
        arp_out->hw_len = 6;
        arp_out->proto_len = 4;
        arp_out->opcode = htons(2);
        memcpy(arp_out->src_mac, mac_addr, 6);
        arp_out->src_ip = local_kernel_ip;
        memcpy(arp_out->dest_mac, arp->src_mac, 6);
        arp_out->dest_ip = arp->src_ip;

        e1000_send_packet(reply_buf, sizeof(reply_buf));
    }
}

void net_process_udp(ipv4_hdr_t* ip, udp_hdr_t* udp, uint8_t* payload, uint16_t len) {
    (void)ip;
    uint16_t dport = ntohs(udp->dest_port);
    uint64_t flags;
    arkm_lock_irqsave(&net_stack_lock, &flags);
    for (int i = 0; i < MAX_SOCKETS; i++) {
        if (socket_table[i].in_use && socket_table[i].local_port == dport && socket_table[i].protocol == 17) {
            uint32_t queued = 0U;
            arkm_socket_t* sock = &socket_table[i];
            int rx_allowed = !sock->owner_pid ||
                arkm_rm_periodic_admit(sock->owner_pid, sock->owner_generation,
                                       ARKM_RM_PERIODIC_NETWORK, len);
            if (!rx_allowed) {
                sock->rx_dropped_bytes += len;
                sock->rx_quota_drops++;
                break;
            }
            uint32_t rx_used = (sock->rx_buffer_head + 4096U - sock->rx_buffer_tail) % 4096U;
            uint32_t rx_free = 4095U - rx_used;
            uint32_t enqueue_len = len > rx_free ? rx_free : len;
            if (enqueue_len < len) sock->rx_dropped_bytes += (uint64_t)(len - enqueue_len);
            for (uint16_t b = 0; b < enqueue_len; b++) {
                uint32_t next = (sock->rx_buffer_head + 1U) % 4096U;
                if (next == socket_table[i].rx_buffer_tail) break;
                socket_table[i].rx_ring[socket_table[i].rx_buffer_head] = payload[b];
                socket_table[i].rx_buffer_head = next;
                queued++;
            }
            uint32_t new_used = (sock->rx_buffer_head + 4096U - sock->rx_buffer_tail) % 4096U;
            if (new_used > sock->rx_high_watermark) sock->rx_high_watermark = new_used;
            if (queued && sock->owner_pid)
                arkm_rm_network_identity(sock->owner_pid, sock->owner_generation, queued, 0U);
            break;
        }
    }
    arkm_unlock_irqrestore(&net_stack_lock, flags);
}

void net_process_icmp(ipv4_hdr_t* ip, uint8_t* icmp, uint16_t len) {
    if (len < 8 || ip->dest_ip != local_kernel_ip) return;

    /* Handle ICMP echo replies generated by the QEMU gateway. */
    if (icmp[0] == 0) {
        uint16_t identifier = 0;
        uint16_t sequence = 0;
        memcpy(&identifier, icmp + 4, sizeof(identifier));
        memcpy(&sequence, icmp + 6, sizeof(sequence));
        identifier = ntohs(identifier);
        sequence = ntohs(sequence);

        if (ip->src_ip == ping_target_ip &&
            identifier == ping_identifier &&
            sequence == ping_sequence) {
            ping_reply_received = 1;
        }
        return;
    }

    if (icmp[0] != 8) return;

    uint8_t reply[1600];
    if ((uint32_t)len + sizeof(ipv4_hdr_t) + sizeof(ethernet_hdr_t) > sizeof(reply)) return;

    ethernet_hdr_t* eth_in = (ethernet_hdr_t*)((uint8_t*)ip - sizeof(ethernet_hdr_t));
    ethernet_hdr_t* eth_out = (ethernet_hdr_t*)reply;
    ipv4_hdr_t* ip_out = (ipv4_hdr_t*)(reply + sizeof(ethernet_hdr_t));
    uint8_t* icmp_out = reply + sizeof(ethernet_hdr_t) + sizeof(ipv4_hdr_t);

    memcpy(eth_out->dest_mac, eth_in->src_mac, 6);
    memcpy(eth_out->src_mac, mac_addr, 6);
    eth_out->ethertype = htons(0x0800);

    *ip_out = *ip;
    ip_out->src_ip = local_kernel_ip;
    ip_out->dest_ip = ip->src_ip;
    ip_out->ttl = 64;
    ip_out->checksum = 0;
    ip_out->checksum = net_checksum(ip_out, sizeof(ipv4_hdr_t));

    memcpy(icmp_out, icmp, len);
    icmp_out[0] = 0;
    icmp_out[2] = 0;
    icmp_out[3] = 0;
    uint16_t csum = net_checksum(icmp_out, len);
    memcpy(icmp_out + 2, &csum, sizeof(csum));

    e1000_send_packet(reply, sizeof(ethernet_hdr_t) + sizeof(ipv4_hdr_t) + len);
}

void net_process_ipv4(ipv4_hdr_t* ip, uint16_t len) {
    if (!ip || len < sizeof(ipv4_hdr_t)) return;
    if ((ip->version_ihl >> 4) != 4U) return;

    uint16_t ip_hdr_len = (uint16_t)((ip->version_ihl & 0x0FU) * 4U);
    uint16_t total_len = ntohs(ip->total_len);
    if (ip_hdr_len < sizeof(ipv4_hdr_t) || ip_hdr_len > len) return;
    if (total_len < ip_hdr_len || total_len > len) return;

    uint8_t* payload = ((uint8_t*)ip) + ip_hdr_len;
    uint16_t payload_len = (uint16_t)(total_len - ip_hdr_len);

    if (ip->protocol == 1U) {
        if (payload_len >= 8U) net_process_icmp(ip, payload, payload_len);
    } else if (ip->protocol == 17U) {
        if (payload_len < sizeof(udp_hdr_t)) return;
        udp_hdr_t* udp = (udp_hdr_t*)payload;
        uint16_t udp_len = ntohs(udp->length);
        if (udp_len < sizeof(udp_hdr_t) || udp_len > payload_len) return;
        uint8_t* udp_payload = payload + sizeof(udp_hdr_t);
        uint16_t udp_payload_len = (uint16_t)(udp_len - sizeof(udp_hdr_t));
        if (!arkm_xnet_udp_hook(ip, udp, udp_payload, udp_payload_len))
            net_process_udp(ip, udp, udp_payload, udp_payload_len);
    } else if (ip->protocol == 6U) {
        if (payload_len < sizeof(tcp_hdr_t)) return;
        tcp_hdr_t* tcp = (tcp_hdr_t*)payload;
        uint16_t tcp_hdr_len = (uint16_t)((tcp->data_offset >> 4) * 4U);
        if (tcp_hdr_len < sizeof(tcp_hdr_t) || tcp_hdr_len > payload_len) return;
        net_process_tcp(ip, tcp, payload + tcp_hdr_len,
                        (uint16_t)(payload_len - tcp_hdr_len));
    }
}

void arkm_net_ingress_handler(uint8_t* raw_packet, uint16_t packet_len) {
    if (packet_len < sizeof(ethernet_hdr_t)) return;
    ethernet_hdr_t* eth = (ethernet_hdr_t*)raw_packet;
    uint16_t ethertype = ntohs(eth->ethertype);

    if (ethertype == 0x0806) {
        if (packet_len >= sizeof(ethernet_hdr_t) + sizeof(arp_hdr_t))
            net_process_arp((arp_hdr_t*)(raw_packet + sizeof(ethernet_hdr_t)));
    } else if (ethertype == 0x86DD) {
        arkm_xnet6_ingress(raw_packet, packet_len);
    } else if (ethertype == 0x0800) {
        if (packet_len < sizeof(ethernet_hdr_t) + sizeof(ipv4_hdr_t)) return;
        ipv4_hdr_t* ip = (ipv4_hdr_t*)(raw_packet + sizeof(ethernet_hdr_t));

        uint64_t flags;
        arkm_lock_irqsave(&net_stack_lock, &flags);
        int found = 0;
        for (int i = 0; i < MAX_ARP_ENTRIES; i++) {
            if (arp_table[i].valid && arp_table[i].ip == ip->src_ip) {
                memcpy(arp_table[i].mac, eth->src_mac, 6);
                found = 1; break;
            }
        }
        if (!found) {
            for (int i = 0; i < MAX_ARP_ENTRIES; i++) {
                if (!arp_table[i].valid) {
                    arp_table[i].ip = ip->src_ip;
                    memcpy(arp_table[i].mac, eth->src_mac, 6);
                    arp_table[i].valid = 1;
                    break;
                }
            }
        }
        arkm_unlock_irqrestore(&net_stack_lock, flags);

        net_process_ipv4(ip, packet_len - sizeof(ethernet_hdr_t));
    }
}

void e1000_write_reg(uint16_t offset, uint32_t val) {
    *(volatile uint32_t*)((uint64_t)e1000_mmio_base + offset) = val;
}

uint32_t e1000_read_reg(uint16_t offset) {
    return *(volatile uint32_t*)((uint64_t)e1000_mmio_base + offset);
}

static uint64_t e1000_virt_to_phys(uint64_t virt) {
    uint64_t pml4e = p4_table[(virt >> 39) & 0x1FF];
    if (!(pml4e & 1)) return 0;

    uint64_t* pdp = (uint64_t*)(pml4e & ~0xFFFULL);
    uint64_t pdpe = pdp[(virt >> 30) & 0x1FF];
    if (!(pdpe & 1)) return 0;
    if (pdpe & (1ULL << 7)) {
        return (pdpe & 0x000FFFFFC0000000ULL) | (virt & 0x3FFFFFFFULL);
    }

    uint64_t* pd = (uint64_t*)(pdpe & ~0xFFFULL);
    uint64_t pde = pd[(virt >> 21) & 0x1FF];
    if (!(pde & 1)) return 0;
    if (pde & (1ULL << 7)) {
        return (pde & 0x000FFFFFE0000000ULL) | (virt & 0x1FFFFFULL);
    }

    uint64_t* pt = (uint64_t*)(pde & ~0xFFFULL);
    uint64_t pte = pt[(virt >> 12) & 0x1FF];
    if (!(pte & 1)) return 0;
    return (pte & ~0xFFFULL) | (virt & 0xFFFULL);
}

void e1000_irq_handler_c(void) {
    if (e1000_mmio_base == 0) return;
    uint32_t cause = e1000_read_reg(E1000_REG_ICR);
    if (cause == 0) return;
    e1000_irq_count++;
    if (cause & (1U << 7)) {
        e1000_poll_rx();
    }
    advanced_trace(0x32, E1000_MSI_VECTOR, ((uint64_t)e1000_irq_count << 32) | cause);
    volatile uint32_t* eoi = (volatile uint32_t*)((uint64_t)(local_apic_base ? local_apic_base : 0xFEE00000U) + 0xB0U);
    *eoi = 0;
}

