#define ARKM6_FEATURE_POWER_ABI     (1ULL << 26)
#define ARKM6_FEATURE_VM_ABI        (1ULL << 27)
#define ARKM6_FEATURE_PROC_AFFINITY (1ULL << 28)
#define ARKM6_FEATURE_EVENT_READ    (1ULL << 29)
#define ARKM6_FEATURE_AUDIT_READ    (1ULL << 30)
#define ARKM6_FEATURE_POSIX_CWD     (1ULL << 31)
#define ARKM6_FEATURE_SHELL_UTILS   (1ULL << 32)
#define ARKM6_FEATURE_DRIVER_GATE   (1ULL << 33)

#define ARKM6_CAP_PROCESS   (1ULL << 0)
#define ARKM6_CAP_SIGNAL    (1ULL << 1)
#define ARKM6_CAP_PIPE      (1ULL << 2)
#define ARKM6_CAP_VM        (1ULL << 3)
#define ARKM6_CAP_FS        (1ULL << 4)
#define ARKM6_CAP_NET       (1ULL << 5)
#define ARKM6_CAP_DEVICE    (1ULL << 6)
#define ARKM6_CAP_AUDIO     (1ULL << 7)
