#define ARKM6_CAP_DOMAIN    (1ULL << 9)
#define ARKM6_CAP_ADMIN     (1ULL << 10)
#define ARKM6_CAP_TRACE     (1ULL << 11)
#define ARKM6_CAP_POWER     (1ULL << 12)
#define ARKM6_CAP_TRANSFER  (1ULL << 13)

#define ARKM6_PROC_FREE     0U
#define ARKM6_PROC_READY    1U
#define ARKM6_PROC_RUNNING  2U
#define ARKM6_PROC_SLEEPING 3U
#define ARKM6_PROC_EXITED   4U
