/* Explicit lifecycle is separate from the legacy-compatible scheduler state. */
#define ARKM6_LIFE_CREATED  0U
#define ARKM6_LIFE_LOADING  1U
#define ARKM6_LIFE_READY    2U
#define ARKM6_LIFE_RUNNING  3U
#define ARKM6_LIFE_BLOCKED  4U
