typedef struct {
    uint32_t op;       /* First field preserves syscall operation dispatch. */
    uint32_t version;
    uint32_t size;
    uint32_t target_pid;
    uint64_t capability_mask;
} arkm6_cap_transfer_args_t;

#define ARKM6_DOMAIN_CREATE 1U
#define ARKM6_DOMAIN_GET    2U
