#define ARKM6_DRIVER_UNKNOWN    0U
#define ARKM6_DRIVER_XHCI      1U
#define ARKM6_DRIVER_HID       2U
#define ARKM6_DRIVER_USB_MASS  3U
#define ARKM6_DRIVER_HDA       4U
#define ARKM6_DRIVER_WIFI      5U
#define ARKM6_DRIVER_BLUETOOTH 6U
#define ARKM6_DRIVER_CAMERA    7U
#define ARKM6_DRIVER_PRINTER   8U
#define ARKM6_DRIVER_STORAGE   9U
#define ARKM6_DRIVER_NETWORK   10U

#define ARKM6_DEVICE_DISCOVERED 0x01U
#define ARKM6_DEVICE_ONLINE     0x02U
