/* Caller holds arkm6_process_lock. REAPED is not reached until a real
 * address-space destructor exists; wait-status consumption alone is not reap. */
static int arkm6_lifecycle_transition_locked(arkm6_process_t* p, uint8_t next) {
    if (!p || next > ARKM6_LIFE_REAPED) return 0;
    uint8_t current = p->lifecycle;
    if (current == next) return 1;
    int allowed = 0;
    switch (current) {
        case ARKM6_LIFE_CREATED: allowed = (next == ARKM6_LIFE_LOADING || next == ARKM6_LIFE_STOPPING); break;
        case ARKM6_LIFE_LOADING: allowed = (next == ARKM6_LIFE_READY || next == ARKM6_LIFE_STOPPING); break;
        case ARKM6_LIFE_READY: allowed = (next == ARKM6_LIFE_RUNNING || next == ARKM6_LIFE_BLOCKED || next == ARKM6_LIFE_STOPPING); break;
        case ARKM6_LIFE_RUNNING: allowed = (next == ARKM6_LIFE_READY || next == ARKM6_LIFE_BLOCKED || next == ARKM6_LIFE_STOPPING); break;
        case ARKM6_LIFE_BLOCKED: allowed = (next == ARKM6_LIFE_READY || next == ARKM6_LIFE_STOPPING); break;
        case ARKM6_LIFE_STOPPING: allowed = (next == ARKM6_LIFE_EXITED); break;
        case ARKM6_LIFE_EXITED: allowed = (next == ARKM6_LIFE_REAPED); break;
        default: allowed = 0; break;
    }
    if (!allowed) {
        __atomic_fetch_add(&arkm_prod_state.invariant_failures, 1U, __ATOMIC_RELAXED);
        return 0;
    }
    p->lifecycle = next;
    p->lifecycle_generation++;
    return 1;
}

