/* ========================================================================
 * ARKM RESOURCE MANAGEMENT LAYER (RML)
 * ------------------------------------------------------------------------
 * One account per ARKM6 process identity. CPU accounting uses TSC cycles
 * sampled at user/kernel transitions; it is not converted to nanoseconds.
 * Resource admission is enforced for the integrated memory/handle/IPC/DMA
 * paths. CPU quotas currently provide accounting and cooperative syscall
 * throttling only. The BSP timer preempts kernel-worker contexts; AP vector
 * 0x20 remains a wake/probe IPI, not a periodic per-CPU timer. The Ring-3
 * application context is single-instance, so hard CPU isolation is not claimed.
 * ======================================================================== */
#define ARKM_RM_VERSION             1U
#define ARKM_RM_STATE_ACTIVE        1U
#define ARKM_RM_STATE_STOPPING      2U
#define ARKM_RM_STATE_EXITED        3U
#define ARKM_RM_LIMIT_UNLIMITED     UINT64_MAX
#define ARKM_RM_DEFAULT_HANDLES     16ULL
#define ARKM_RM_DEFAULT_IPC         8ULL
#define ARKM_RM_DEFAULT_DMA         64ULL
#define ARKM_RM_DEFAULT_CHILDREN    32ULL
#define ARKM_RM_PRIORITY_BEST_EFFORT 0U
#define ARKM_RM_PRIORITY_BACKGROUND 1U
#define ARKM_RM_PRIORITY_INTERACTIVE 2U
#define ARKM_RM_PRIORITY_SERVICE 3U
#define ARKM_RM_PRIORITY_CRITICAL 4U
#define ARKM_RM_EXIT_VOLUNTARY 1U
#define ARKM_RM_EXIT_SIGNAL 2U
#define ARKM_RM_EXIT_FAULT 3U
#define ARKM_RM_EXIT_RESOURCE 4U
#define ARKM_RM_EXIT_OOM 5U
#define ARKM_RM_ACTION_REJECT       1U
#define ARKM_RM_ACTION_BACKPRESSURE 2U
#define ARKM_RM_DOMAIN_SLOTS        (ARKM6_MAX_DOMAINS + 1U)

