#define ARKM_X_OK                    0
#define ARKM_X_ERR                  -1
#define ARKM_X_BUSY                 -2
#define ARKM_X_UNSUPPORTED          -3

#define ARKM_XHCI_MMIO_VIRTUAL_BASE 0x0000000140000000ULL /* 5 GiB; ECAM owns 4-5 GiB */
#define ARKM_XHCI_MMIO_WINDOW_BYTES  0x0000000000010000ULL /* 64-KiB xHCI register window */
#define ARKM_XHCI_CAPLENGTH          0x00U
#define ARKM_XHCI_HCSPARAMS1         0x04U
#define ARKM_XHCI_HCCPARAMS1         0x10U
#define ARKM_XHCI_DBOFF              0x14U
#define ARKM_XHCI_RTSOFF             0x18U
#define ARKM_XHCI_USBCMD             0x00U
#define ARKM_XHCI_USBSTS             0x04U
#define ARKM_XHCI_PAGESIZE           0x08U
#define ARKM_XHCI_CRCR               0x18U
#define ARKM_XHCI_DCBAAP             0x30U
#define ARKM_XHCI_CONFIG             0x38U
#define ARKM_XHCI_PORT_BASE          0x400U
#define ARKM_XHCI_PORT_STRIDE        0x10U
#define ARKM_XHCI_USBCMD_RS          (1U << 0)
#define ARKM_XHCI_USBCMD_HCRST       (1U << 1)
#define ARKM_XHCI_USBSTS_HCH         (1U << 0)
#define ARKM_XHCI_USBSTS_CNR         (1U << 11)
