#define ARKM_XHCI_TRB_LINK           6U
#define ARKM_XHCI_TRB_EVENT          32U
#define ARKM_XHCI_TRB_CMD_COMPLETE   33U
#define ARKM_XHCI_TRB_TRANSFER_EVT   32U

#define ARKM_XHDA_GCAP               0x00U
#define ARKM_XHDA_GCTL               0x08U
#define ARKM_XHDA_STATESTS           0x0EU
#define ARKM_XHDA_CORBLBASE          0x40U
#define ARKM_XHDA_CORBUBASE          0x44U
#define ARKM_XHDA_CORBWP             0x48U
#define ARKM_XHDA_CORBRP             0x4AU
#define ARKM_XHDA_CORBCTL            0x4CU
#define ARKM_XHDA_CORBSTS            0x4DU
#define ARKM_XHDA_CORBSIZE           0x4EU
#define ARKM_XHDA_RIRBLBASE          0x50U
