#define ARKM_XVM_PRESENT              0x001ULL
#define ARKM_XVM_WRITE                0x002ULL
#define ARKM_XVM_USER                 0x004ULL
#define ARKM_XVM_PS                   0x080ULL
#define ARKM_XVM_NX                   (1ULL << 63)

