static int arkm_x_page_is_free(uint32_t idx) {
    if (idx >= TOTAL_PAGES) return 0;
    return pmm_page_state[idx] == PMM_PAGE_FREE && !bitmap_test(idx);
}

static uint64_t arkm_x_alloc_contiguous(uint32_t pages) {
    if (!pages || pages > TOTAL_PAGES) return 0;
    uint64_t flags;
    arkm_lock_irqsave(&pmm_lock, &flags);
    uint32_t start_min = (64U * 1024U * 1024U) / PAGE_SIZE;
    if (start_min >= TOTAL_PAGES) {
        arkm_unlock_irqrestore(&pmm_lock, flags);
        return 0;
    }
    for (uint32_t start = start_min; start + pages <= TOTAL_PAGES; start++) {
        uint32_t i = 0;
        for (; i < pages; i++) if (!arkm_x_page_is_free(start + i)) break;
        if (i != pages) { start += i; continue; }
        for (i = 0; i < pages; i++) {
            uint32_t idx = start + i;
            bitmap_set(idx);
            pmm_page_state[idx] = PMM_PAGE_ALLOCATED;
            advanced_page_allocated(idx);
            memset((void*)arkm_x_phys_of_page(idx), 0, PAGE_SIZE);
        }
        last_allocated_page = start + pages - 1U;
        arkm_unlock_irqrestore(&pmm_lock, flags);
        return arkm_x_phys_of_page(start);
    }
    arkm_unlock_irqrestore(&pmm_lock, flags);
    return 0;
}

static uint64_t arkm_x_alloc_contiguous_aligned(uint32_t pages, uint32_t align_pages) {
    if (align_pages == 1U) return arkm_x_alloc_contiguous(pages);
    if (!pages || !align_pages || pages > TOTAL_PAGES) return 0;
    uint64_t irq;
    arkm_lock_irqsave(&pmm_lock, &irq);
    uint32_t start_min=(64U*1024U*1024U)/PAGE_SIZE;
    if (start_min>=TOTAL_PAGES) { arkm_unlock_irqrestore(&pmm_lock, irq); return 0; }
    uint32_t start=(start_min + align_pages - 1U) & ~(align_pages - 1U);
    for (; start + pages <= TOTAL_PAGES; start += align_pages) {
        uint32_t i=0;
        for (; i<pages; i++) if (!arkm_x_page_is_free(start+i)) break;
        if (i!=pages) continue;
        for (i=0; i<pages; i++) {
            uint32_t idx=start+i;
            bitmap_set(idx); pmm_page_state[idx]=PMM_PAGE_ALLOCATED; advanced_page_allocated(idx);
            memset((void*)arkm_x_phys_of_page(idx),0,PAGE_SIZE);
        }
        last_allocated_page=start+pages-1U;
        arkm_unlock_irqrestore(&pmm_lock, irq);
        return arkm_x_phys_of_page(start);
    }
    arkm_unlock_irqrestore(&pmm_lock, irq);
    return 0;
}

static void arkm_x_free_contiguous(uint64_t phys, uint32_t pages) {
    if (!pages || (phys & (PAGE_SIZE - 1ULL))) return;
    uint32_t start = arkm_x_page_index(phys);
    if (start + pages > TOTAL_PAGES) return;
    uint64_t flags;
    arkm_lock_irqsave(&pmm_lock, &flags);
    for (uint32_t i = 0; i < pages; i++) {
        uint32_t idx = start + i;
        if (pmm_page_state[idx] == PMM_PAGE_ALLOCATED) {
            advanced_page_released(idx);
            if (advanced_page_reference_count(idx) == 0U) {
                pmm_page_state[idx] = PMM_PAGE_FREE;
                bitmap_clear(idx);
            }
        }
    }
    arkm_unlock_irqrestore(&pmm_lock, flags);
}

static void arkm_x_mem_init(void) {
    spin_lock(&arkm_x_memory_lock);
    memset(arkm_x_memnodes, 0, sizeof(arkm_x_memnodes));
    arkm_x_memnode_count = 1;
    arkm_x_memnodes[0].active = 1;
    arkm_x_memnodes[0].id = 0;
    arkm_x_memnodes[0].page_base = 0;
    arkm_x_memnodes[0].page_end = TOTAL_PAGES;
    arkm_x_memnodes[0].cpu_mask = (total_cpu_cores >= 64U) ? ~0ULL :
                                   (total_cpu_cores ? ((1ULL << total_cpu_cores) - 1ULL) : 1ULL);
    for (uint32_t i = 0; i < TOTAL_PAGES; i++)
        if (pmm_page_state[i] == PMM_PAGE_FREE) arkm_x_memnodes[0].free_pages++;
    spin_unlock(&arkm_x_memory_lock);
}

static void arkm_x_mem_refresh(void) {
    spin_lock(&arkm_x_memory_lock);
    if (!arkm_x_memnode_count) { spin_unlock(&arkm_x_memory_lock); return; }
    for (uint32_t n = 0; n < arkm_x_memnode_count; n++) arkm_x_memnodes[n].free_pages = 0;
    for (uint32_t i = 0; i < TOTAL_PAGES; i++) {
        if (pmm_page_state[i] != PMM_PAGE_FREE) continue;
        for (uint32_t n = 0; n < arkm_x_memnode_count; n++) {
            if (i >= arkm_x_memnodes[n].page_base && i < arkm_x_memnodes[n].page_end) {
                arkm_x_memnodes[n].free_pages++;
                break;
            }
        }
    }
    spin_unlock(&arkm_x_memory_lock);
}

static int arkm_x_cow_register(uint64_t cr3, uint64_t virt, uint64_t phys) {
    /* Single registration path: the same CR3-aware table is used by clone,
     * page-fault recovery and legacy advanced_* entry points. */
    return arkm_x7_cow_add(cr3, virt, phys);
}

static int arkm_x_cow_fault(uint64_t cr3, uint64_t fault_addr) {
    return arkm_x7_cow_fault(cr3, fault_addr);
}

static int arkm_xvm_walk(uint64_t* pml4, uint64_t va, uint64_t** out_pte) {
    if (!pml4 || !out_pte) return 0;
    uint64_t a = (va >> 39) & 0x1FFULL;
    uint64_t b = (va >> 30) & 0x1FFULL;
    uint64_t c = (va >> 21) & 0x1FFULL;
    uint64_t d = (va >> 12) & 0x1FFULL;
    if (!(pml4[a] & 1ULL)) return 0;
    uint64_t* pdp = (uint64_t*)(pml4[a] & ~0xFFFULL);
    if (!(pdp[b] & 1ULL)) return 0;
    uint64_t* pd = (uint64_t*)(pdp[b] & ~0xFFFULL);
    if (!(pd[c] & 1ULL) || (pd[c] & ARKM_XVM_PS)) return 0;
    uint64_t* pt = (uint64_t*)(pd[c] & ~0xFFFULL);
    *out_pte = &pt[d];
    return 1;
}

static int arkm_xvm_gap(uint64_t* out_addr, uint64_t length) {
    uint64_t base = 0x20000000ULL;
    uint64_t limit = 0x70000000ULL;
    uint64_t candidate = base;
    for (;;) {
        uint64_t next = limit;
        for (uint32_t i = 0; i < ARKM6_MAX_VM_AREAS; i++) {
            if (!arkm6_vm_areas[i].active) continue;
            uint64_t s = arkm6_vm_areas[i].virt;
            uint64_t e = s + arkm6_vm_areas[i].length;
            if (e <= candidate) continue;
            if (s < next) next = s;
        }
        if (candidate + length <= next && candidate + length <= limit) {
            *out_addr = candidate;
            return 1;
        }
        if (next <= candidate || next >= limit) return 0;
        candidate = (next + PAGE_SIZE - 1ULL) & ~(PAGE_SIZE - 1ULL);
    }
}

static uint64_t arkm_xvm_unmap_pages(uint64_t cr3, uint64_t start, uint64_t end) {
    uint64_t released_pages = 0U;
    for (uint64_t va = start; va < end; va += PAGE_SIZE) {
        uint64_t* pte = NULL;
        if (!arkm_xvm_walk((uint64_t*)cr3, va, &pte)) continue;
        uint64_t old = *pte;
        if (!(old & ARKM_XVM_PRESENT)) continue;
        uint64_t phys = old & 0x000FFFFFFFFFF000ULL;
        *pte = 0;
        __asm__ volatile("invlpg (%0)" : : "r"(va) : "memory");
        if (!(old & ARKM_XVM_PS)) { pmm_free_page((void*)phys); released_pages++; }
    }
    return released_pages;
}

/* Kernel-shell diagnostics may run when no user application is active.
 * In that case use the established user_pml4 fallback used by the COW test
 * command, rather than treating app_context.cr3 == 0 as a mapping failure. */
static uint64_t arkm_x8_swap_context_cr3(void) {
    if (app_context.cr3) return (uint64_t)app_context.cr3;
    if ((uint64_t)user_pml4) return (uint64_t)user_pml4;
    return 0;
}

/* Reclaimers run on the BSP but operate on the selected address space.  Never
 * infer the owner from the BSP's current CR3, and never edit a page table while
 * any CPU advertises that CR3 as active. */
static uint32_t arkm_process_pid_for_cr3(uint64_t cr3) {
    if (!cr3) return 0U;
    uint32_t pid = 0U;
    uint64_t irq;
    arkm_lock_irqsave(&arkm6_process_lock, &irq);
    for (uint32_t i = 0U; i < ARKM6_MAX_PROCESSES; ++i) {
        const arkm6_process_t* p = &arkm6_processes[i];
        if (p->state != ARKM6_PROC_FREE && p->cr3 == (cr3 & ~0xFFFULL) &&
            p->lifecycle != ARKM6_LIFE_EXITED && p->lifecycle != ARKM6_LIFE_REAPED) {
            pid = p->pid;
            break;
        }
    }
    arkm_unlock_irqrestore(&arkm6_process_lock, irq);
    if (!pid && cr3 == (uint64_t)user_pml4) pid = 1U;
    return pid;
}

static int arkm_cr3_active_on_any_cpu(uint64_t cr3) {
    if (!cr3) return 0;
    uint64_t target = cr3 & ~0xFFFULL;
    uint64_t online = __atomic_load_n(&smp_online_mask, __ATOMIC_ACQUIRE);
    for (uint32_t slot = 0U; slot < 32U; ++slot) {
        if ((online & (1ULL << slot)) == 0ULL) continue;
        if (__atomic_load_n(&arkm_cpu_active_cr3[slot], __ATOMIC_ACQUIRE) == target)
            return 1;
    }
    return 0;
}

static uint64_t arkm_xvm_map(uint64_t addr, uint64_t length, uint32_t prot, uint32_t flags) {
    if (!length || length > (32ULL * 1024ULL * 1024ULL)) return (uint64_t)-1;
    if ((prot & 0x2U) && (prot & 0x4U)) return (uint64_t)-1;
    if (!(arkm6_caps_allow(ARKM6_CAP_VM))) return (uint64_t)-1;
    uint64_t pages = (length + PAGE_SIZE - 1ULL) / PAGE_SIZE;
    length = pages * PAGE_SIZE;
    uint64_t cr3 = arkm_x8_swap_context_cr3();
    if (!cr3) return (uint64_t)-1;
    arkm6_process_t* p = arkm6_current_process();
    uint32_t owner_pid = p ? p->pid : arkm6_current_pid_fast();
    uint32_t owner_generation = p ? p->identity_generation : arkm_rm_generation_for_pid(owner_pid);
    if (!owner_pid || !owner_generation ||
        !arkm_rm_reserve_identity(owner_pid, owner_generation, ARKM_RM_MEMORY, length)) return (uint64_t)-1;
    if (arkm_x7_vm_map_charge(cr3, pages) == (uint64_t)-1) {
        arkm_rm_cancel(owner_pid, ARKM_RM_MEMORY, length);
        return (uint64_t)-1;
    }
    if ((flags & ARKM_X_VM_HUGE_FLAG) && pages >= 512U && !(addr & 0x1FFFFFULL)) {
        if (addr == 0) {
            arkm_x7_vm_unmap_release(cr3, pages);
            arkm_rm_cancel(owner_pid, ARKM_RM_MEMORY, length);
            return (uint64_t)-1;
        }
        uint64_t hp = arkm_xhuge_map(addr, prot, flags);
        if (hp != (uint64_t)-1) {
            arkm_rm_commit(owner_pid, ARKM_RM_MEMORY, length);
            if (p) { p->vm_bytes += length; if (p->vm_bytes > p->vm_peak) p->vm_peak = p->vm_bytes; }
            return hp;
        }
    }
    if (addr == 0) {
        if (!arkm_xvm_gap(&addr, length)) {
            arkm_x7_vm_unmap_release(cr3, pages);
            arkm_rm_cancel(owner_pid, ARKM_RM_MEMORY, length);
            return (uint64_t)-1;
        }
    }
    addr &= ~(PAGE_SIZE - 1ULL);
    if (!arkm_x_vm_range_safe(addr, length)) {
        arkm_x7_vm_unmap_release(cr3, pages);
        arkm_rm_cancel(owner_pid, ARKM_RM_MEMORY, length);
        return (uint64_t)-1;
    }
    uint64_t mapped = 0;
    for (uint64_t i = 0; i < pages; i++) {
        uint64_t va = addr + i * PAGE_SIZE;
        if (app_vmm_user_page_mapped((uint64_t*)cr3, va)) { arkm_xvm_unmap_pages(cr3, addr, va); arkm_x7_vm_unmap_release(cr3, mapped); arkm_rm_cancel(owner_pid, ARKM_RM_MEMORY, length); return (uint64_t)-1; }
        void* page = pmm_alloc_page();
        if (!page) { arkm_xvm_unmap_pages(cr3, addr, va); arkm_x7_vm_unmap_release(cr3, mapped); arkm_rm_cancel(owner_pid, ARKM_RM_MEMORY, length); return (uint64_t)-1; }
        uint64_t pte_flags = ARKM_XVM_PRESENT | ARKM_XVM_USER;
        if (prot & 0x2U) pte_flags |= ARKM_XVM_WRITE;
        if (!(prot & 0x4U) && aegis_nxe_enabled) pte_flags |= ARKM_XVM_NX;
        if (!app_vmm_map_user_page((uint64_t*)cr3, va, (uint64_t)page, pte_flags)) {
            pmm_free_page(page); arkm_xvm_unmap_pages(cr3, addr, va); arkm_x7_vm_unmap_release(cr3, mapped); arkm_rm_cancel(owner_pid, ARKM_RM_MEMORY, length); return (uint64_t)-1;
        }
        memset(page, 0, PAGE_SIZE);
        mapped++;
    }
    for (uint32_t i = 0; i < ARKM6_MAX_VM_AREAS; i++) {
        if (!arkm6_vm_areas[i].active) {
            memset(&arkm6_vm_areas[i], 0, sizeof(arkm6_vm_areas[i]));
            arkm6_vm_areas[i].active = 1;
            arkm6_vm_areas[i].virt = addr;
            arkm6_vm_areas[i].length = length;
            arkm6_vm_areas[i].pages = mapped;
            arkm6_vm_areas[i].prot = prot;
            arkm6_vm_areas[i].flags = flags;
            arkm6_vm_areas[i].owner_pid = p ? p->pid : 1U;
            if (p) { p->vm_bytes += length; if (p->vm_bytes > p->vm_peak) p->vm_peak = p->vm_bytes; }
            arkm_rm_commit(owner_pid, ARKM_RM_MEMORY, length);
            arkm6_event_push(ARKM6_EVT_VM, addr, length);
            arkm6_audit_record(ARKM6_EVT_VM, 0x3010U, addr, length);
            return addr;
        }
    }
    arkm_xvm_unmap_pages(cr3, addr, addr + length);
    arkm_x7_vm_unmap_release(cr3, mapped);
    arkm_rm_cancel(owner_pid, ARKM_RM_MEMORY, length);
    return (uint64_t)-1;
}

static int arkm_xvm_unmap(uint64_t addr, uint64_t length) {
    if (!arkm6_caps_allow(ARKM6_CAP_VM) || !length) return -1;
    addr &= ~(PAGE_SIZE - 1ULL);
    length = (length + PAGE_SIZE - 1ULL) & ~(PAGE_SIZE - 1ULL);
    if (!arkm_x_vm_range_safe(addr, length)) return -1;
    uint64_t cr3 = arkm_x8_swap_context_cr3();
    if (!cr3) return -1;
    uint64_t end = addr + length;
    uint64_t released_pages = arkm_xvm_unmap_pages(cr3, addr, end);
    if (released_pages) arkm_x7_vm_unmap_release(cr3, released_pages);
    arkm6_process_t* p = arkm6_current_process();
    uint32_t owner_pid = p ? p->pid : arkm6_current_pid_fast();
    uint32_t owner_generation = p ? p->identity_generation : arkm_rm_generation_for_pid(owner_pid);
    if (released_pages && owner_pid && owner_generation)
        arkm_rm_release_identity(owner_pid, owner_generation, ARKM_RM_MEMORY,
                                 released_pages * PAGE_SIZE);
    for (uint32_t i = 0; i < ARKM6_MAX_VM_AREAS; i++) {
        arkm6_vm_area_t* a = &arkm6_vm_areas[i];
        if (!a->active || a->virt >= end || a->virt + a->length <= addr) continue;
        uint64_t as = a->virt, ae = as + a->length;
        if (addr <= as && end >= ae) {
            if (p && p->vm_bytes >= a->length) p->vm_bytes -= a->length;
            memset(a, 0, sizeof(*a));
        } else if (addr <= as) {
            uint64_t cut = end - as;
            a->virt = end;
            a->length = ae - end;
            a->pages = a->length / PAGE_SIZE;
            if (p && p->vm_bytes >= cut) p->vm_bytes -= cut;
        } else if (end >= ae) {
            uint64_t cut = ae - addr;
            a->length = addr - as;
            a->pages = a->length / PAGE_SIZE;
            if (p && p->vm_bytes >= cut) p->vm_bytes -= cut;
        } else {
            for (uint32_t j = 0; j < ARKM6_MAX_VM_AREAS; j++) {
                if (arkm6_vm_areas[j].active) continue;
                arkm6_vm_areas[j] = *a;
                arkm6_vm_areas[j].virt = end;
                arkm6_vm_areas[j].length = ae - end;
                arkm6_vm_areas[j].pages = arkm6_vm_areas[j].length / PAGE_SIZE;
                a->length = addr - as;
                a->pages = a->length / PAGE_SIZE;
                if (p && p->vm_bytes >= length) p->vm_bytes -= length;
                break;
            }
        }
    }
    arkm6_event_push(ARKM6_EVT_VM, addr, length);
    arkm6_audit_record(ARKM6_EVT_VM, 0x3011U, addr, length);
    return 0;
}

static int arkm_xvm_protect(uint64_t addr, uint64_t length, uint32_t prot) {
    if (!arkm6_caps_allow(ARKM6_CAP_VM) || !length) return -1;
    if ((prot & 0x2U) && (prot & 0x4U)) return -1;
    addr &= ~(PAGE_SIZE - 1ULL);
    length = (length + PAGE_SIZE - 1ULL) & ~(PAGE_SIZE - 1ULL);
    if (!arkm_x_vm_range_safe(addr, length)) return -1;
    uint64_t end = addr + length;
    for (uint64_t va = addr; va < end; va += PAGE_SIZE) {
        uint64_t* pte = NULL;
        if (!arkm_xvm_walk((uint64_t*)app_context.cr3, va, &pte)) return -1;
        uint64_t x = *pte;
        if (!(x & ARKM_XVM_PRESENT)) return -1;
        x &= ~(ARKM_XVM_WRITE | ARKM_XVM_NX);
        x |= ARKM_XVM_USER;
        if (prot & 0x2U) x |= ARKM_XVM_WRITE;
        if (!(prot & 0x4U) && aegis_nxe_enabled) x |= ARKM_XVM_NX;
        *pte = x;
        if (!arkm_tlb_shootdown_cr3(app_context.cr3, va)) return -1;
    }
    for (uint32_t i = 0; i < ARKM6_MAX_VM_AREAS; i++) {
        if (!arkm6_vm_areas[i].active) continue;
        if (arkm6_vm_areas[i].virt <= addr && arkm6_vm_areas[i].virt + arkm6_vm_areas[i].length >= end)
            arkm6_vm_areas[i].prot = prot;
    }
    arkm6_audit_record(ARKM6_EVT_VM, 0x3012U, addr, prot);
    return 0;
}

static int arkm_x_vm_range_safe(uint64_t addr, uint64_t length) {
    if (!length || addr < 0x20000000ULL || addr >= 0x70000000ULL) return 0;
    if (addr + length < addr || addr + length > 0x70000000ULL) return 0;
    return 1;
}

static uint64_t arkm_xhuge_map(uint64_t virt, uint32_t prot, uint32_t flags) {
    (void)flags;
    if ((virt & 0x1FFFFFULL) || virt < 0x20000000ULL || virt + 0x200000ULL > 0x70000000ULL) return (uint64_t)-1;
    if ((prot & 0x2U) && (prot & 0x4U)) return (uint64_t)-1;
    for (uint32_t i = 0; i < ARKM_X_HUGE_AREAS; i++) if (arkm_x_huge_areas[i].active && arkm_x_huge_areas[i].virt == virt) return (uint64_t)-1;
    uint64_t phys = arkm_x_alloc_contiguous_aligned(512U, 512U);
    if (!phys || (phys & 0x1FFFFFULL)) return (uint64_t)-1;
    uint64_t* pml4 = (uint64_t*)app_context.cr3;
    if (!pml4) { arkm_x_free_contiguous(phys, 512U); return (uint64_t)-1; }
    uint64_t pi = (virt >> 39) & 0x1FFULL;
    uint64_t di = (virt >> 30) & 0x1FFULL;
    uint64_t ti = (virt >> 21) & 0x1FFULL;
    if (!(pml4[pi] & 1ULL)) {
        uint64_t* p = (uint64_t*)pmm_alloc_page(); if (!p) { arkm_x_free_contiguous(phys,512U); return (uint64_t)-1; }
        memset(p,0,PAGE_SIZE); pml4[pi] = (uint64_t)p | 0x07ULL;
    }
    pml4[pi] |= 0x04ULL;
    uint64_t* pdp = (uint64_t*)(pml4[pi] & ~0xFFFULL);
    if (!(pdp[di] & 1ULL)) {
        uint64_t* p = (uint64_t*)pmm_alloc_page(); if (!p) { arkm_x_free_contiguous(phys,512U); return (uint64_t)-1; }
        memset(p,0,PAGE_SIZE); pdp[di] = (uint64_t)p | 0x07ULL;
    }
    pdp[di] |= 0x04ULL;
    uint64_t* pd = (uint64_t*)(pdp[di] & ~0xFFFULL);
    uint64_t pf = ARKM_XVM_PRESENT | ARKM_XVM_PS | ARKM_XVM_USER;
    if (prot & 0x2U) pf |= ARKM_XVM_WRITE;
    if (!(prot & 0x4U) && aegis_nxe_enabled) pf |= ARKM_XVM_NX;
    pd[ti] = phys | pf;
    __asm__ volatile("invlpg (%0)" : : "r"(virt) : "memory");
    for (uint32_t i = 0; i < ARKM_X_HUGE_AREAS; i++) if (!arkm_x_huge_areas[i].active) {
        arkm_x_huge_areas[i].active = 1;
        arkm_x_huge_areas[i].virt = virt;
        arkm_x_huge_areas[i].phys = phys;
        arkm_x_huge_areas[i].pages = 512U;
        arkm_x_huge_areas[i].owner_pid = arkm6_current_pid_fast();
        arkm_x_huge_areas[i].owner_generation = arkm_rm_generation_for_pid(arkm_x_huge_areas[i].owner_pid);
        arkm_x_huge_areas[i].prot = prot;
        arkm_x_huge_areas[i].flags = flags;
        return virt;
    }
    pd[ti] = 0;
    arkm_x_free_contiguous(phys,512U);
    return (uint64_t)-1;
}

static int arkm_xhuge_unmap(uint64_t virt) {
    if (virt & 0x1FFFFFULL) return -1;
    uint64_t pi=(virt>>39)&0x1FFULL, di=(virt>>30)&0x1FFULL, ti=(virt>>21)&0x1FFULL;
    uint64_t* pml4=(uint64_t*)app_context.cr3;
    if (!pml4 || !(pml4[pi]&1ULL)) return -1;
    uint64_t* pdp=(uint64_t*)(pml4[pi]&~0xFFFULL);
    if (!(pdp[di]&1ULL)) return -1;
    uint64_t* pd=(uint64_t*)(pdp[di]&~0xFFFULL);
    uint64_t e=pd[ti];
    if (!(e&ARKM_XVM_PRESENT) || !(e&ARKM_XVM_PS)) return -1;
    for (uint32_t i=0;i<ARKM_X_HUGE_AREAS;i++) if (arkm_x_huge_areas[i].active && arkm_x_huge_areas[i].virt==virt) {
        uint64_t phys=arkm_x_huge_areas[i].phys;
        pd[ti]=0;
        arkm_x_huge_areas[i].active=0;
        arkm_x_free_contiguous(phys,512U);
        uint32_t owner_pid = arkm_x_huge_areas[i].owner_pid;
        uint32_t owner_generation = arkm_x_huge_areas[i].owner_generation;
        arkm_rm_release_identity(owner_pid, owner_generation, ARKM_RM_MEMORY,
                                 512ULL * PAGE_SIZE);
        arkm6_process_t* owner = arkm6_find_process(owner_pid);
        if (owner && owner->vm_bytes >= 512ULL * PAGE_SIZE) owner->vm_bytes -= 512ULL * PAGE_SIZE;
        __asm__ volatile("invlpg (%0)" : : "r"(virt) : "memory");
        return 0;
    }
    return -1;
}

static int arkm_xdma_map(uint64_t phys, uint32_t length, uint32_t flags_in, uint64_t device) {
    /* This public resource-manager API is still a software ownership registry.
     * The hardware IOMMU domain mapper above is used only by kernel drivers;
     * Ring-3 callers cannot create a mapping and mistake this registry for
     * enforced device isolation. */
    if (aegis_currently_ring3()) {
        __atomic_fetch_add(&arkm_prod_state.aegis_rejections, 1U, __ATOMIC_RELAXED);
        __atomic_fetch_add(&arkm_prod_state.syscall_denials, 1U, __ATOMIC_RELAXED);
        return -1;
    }
    if (!length || !device || (flags_in & ~0x3U) != 0U ||
        (phys & (PAGE_SIZE - 1ULL)) || length > (16U*1024U*1024U)) return -1;
    uint64_t end=phys+(uint64_t)length-1ULL;
    if (end<phys || end >= (uint64_t)TOTAL_PAGES*PAGE_SIZE) return -1;
    uint32_t first=(uint32_t)(phys/PAGE_SIZE), pages=(length+PAGE_SIZE-1U)/PAGE_SIZE;
    for (uint32_t i=0;i<pages;i++) if (pmm_page_state[first+i] != PMM_PAGE_ALLOCATED) return -1;
    uint32_t owner_pid = arkm6_current_pid_fast();
    uint32_t owner_generation = owner_pid ? arkm_rm_generation_for_pid(owner_pid) : 0U;
    if (!owner_pid || !owner_generation ||
        !arkm_rm_reserve_identity(owner_pid, owner_generation, ARKM_RM_DMA, 1U)) return -1;
    uint64_t irq; arkm_lock_irqsave(&arkm_x_dma_lock,&irq);
    /* A physical range may not be concurrently exposed to two device IDs.
     * This is not an IOMMU substitute, but prevents software ownership aliasing. */
    for (uint32_t i=0;i<ARKM_X_DMA_SLOTS;i++) {
        arkm_x_dma_slot_t* live = &arkm_x_dma_slots[i];
        if (!live->active) continue;
        uint64_t live_end = live->phys + (uint64_t)live->length;
        uint64_t new_end = phys + (uint64_t)length;
        if (live_end < live->phys || new_end < phys ||
            (phys < live_end && live->phys < new_end)) {
            arkm_unlock_irqrestore(&arkm_x_dma_lock,irq);
            arkm_rm_cancel_identity(owner_pid, owner_generation, ARKM_RM_DMA, 1U);
            return -1;
        }
    }
    for (uint32_t i=0;i<ARKM_X_DMA_SLOTS;i++) if (!arkm_x_dma_slots[i].active) {
        memset(&arkm_x_dma_slots[i], 0, sizeof(arkm_x_dma_slots[i]));
        arkm_x_dma_slots[i].active=1; arkm_x_dma_slots[i].phys=phys; arkm_x_dma_slots[i].length=length; arkm_x_dma_slots[i].flags=flags_in; arkm_x_dma_slots[i].device=device;
        arkm_x_dma_slots[i].owner_pid=owner_pid;
        arkm_x_dma_slots[i].owner_generation=owner_generation;
        arkm_unlock_irqrestore(&arkm_x_dma_lock,irq);
        arkm_rm_commit_identity(owner_pid, owner_generation, ARKM_RM_DMA, 1U);
        return (int)i;
    }
    arkm_unlock_irqrestore(&arkm_x_dma_lock,irq);
    arkm_rm_cancel_identity(owner_pid, owner_generation, ARKM_RM_DMA, 1U);
    return -1;
}

static int arkm_xdma_unmap_identity(int slot, uint32_t expected_pid,
                                    uint32_t expected_generation) {
    if (slot < 0 || (uint32_t)slot >= ARKM_X_DMA_SLOTS ||
        !expected_pid || !expected_generation) return -1;
    uint64_t irq;
    arkm_lock_irqsave(&arkm_x_dma_lock, &irq);
    arkm_x_dma_slot_t* entry = &arkm_x_dma_slots[slot];
    if (!entry->active || entry->owner_pid != expected_pid ||
        entry->owner_generation != expected_generation) {
        arkm_unlock_irqrestore(&arkm_x_dma_lock, irq);
        return -1;
    }
    entry->closing = 1U;
    if (entry->in_flight != 0U) {
        /* Keep the mapping pinned until the device completion path calls end. */
        arkm_unlock_irqrestore(&arkm_x_dma_lock, irq);
        return -2;
    }
    memset(entry, 0, sizeof(*entry));
    arkm_unlock_irqrestore(&arkm_x_dma_lock, irq);
    arkm_rm_release_identity(expected_pid, expected_generation, ARKM_RM_DMA, 1U);
    return 0;
}

/* Device drivers must bracket each submitted descriptor with begin/end. These
 * primitives prevent software teardown from freeing an in-flight mapping. */
static int arkm_xdma_begin_transfer(int slot, uint32_t pid, uint32_t generation) {
    if (slot < 0 || (uint32_t)slot >= ARKM_X_DMA_SLOTS || !pid || !generation)
        return 0;
    uint64_t irq;
    arkm_lock_irqsave(&arkm_x_dma_lock, &irq);
    arkm_x_dma_slot_t* entry = &arkm_x_dma_slots[slot];
    int ok = entry->active && !entry->closing &&
             entry->owner_pid == pid && entry->owner_generation == generation &&
             entry->in_flight != UINT16_MAX;
    if (ok) entry->in_flight++;
    arkm_unlock_irqrestore(&arkm_x_dma_lock, irq);
    return ok;
}

static int arkm_xdma_end_transfer(int slot, uint32_t pid, uint32_t generation) {
    if (slot < 0 || (uint32_t)slot >= ARKM_X_DMA_SLOTS || !pid || !generation)
        return 0;
    int released = 0;
    uint64_t irq;
    arkm_lock_irqsave(&arkm_x_dma_lock, &irq);
    arkm_x_dma_slot_t* entry = &arkm_x_dma_slots[slot];
    if (!entry->active || entry->owner_pid != pid ||
        entry->owner_generation != generation || entry->in_flight == 0U) {
        arkm_unlock_irqrestore(&arkm_x_dma_lock, irq);
        return 0;
    }
    entry->in_flight--;
    if (entry->closing && entry->in_flight == 0U) {
        memset(entry, 0, sizeof(*entry));
        released = 1;
    }
    arkm_unlock_irqrestore(&arkm_x_dma_lock, irq);
    if (released) arkm_rm_release_identity(pid, generation, ARKM_RM_DMA, 1U);
    return 1;
}

static int arkm_xdma_unmap(int slot) {
    uint32_t pid = arkm6_current_pid_fast();
    uint32_t generation = arkm_rm_generation_for_pid(pid);
    return arkm_xdma_unmap_identity(slot, pid, generation);
}

static void arkm_xdma_cleanup_owner(uint32_t pid, uint32_t generation) {
    if (!pid || !generation) return;
    for (uint32_t i = 0U; i < ARKM_X_DMA_SLOTS; ++i)
        (void)arkm_xdma_unmap_identity((int)i, pid, generation);
}

static int arkm_xdriver_hotplug_poll(void) {
    int changed=0;
    for (;;) {
        uint64_t irq; arkm_lock_irqsave(&advanced_hotplug_lock,&irq);
        if (advanced_hotplug_tail == advanced_hotplug_head) { arkm_unlock_irqrestore(&advanced_hotplug_lock,irq); break; }
        advanced_hotplug_event_t ev = advanced_hotplug_queue[advanced_hotplug_tail];
        advanced_hotplug_tail = (advanced_hotplug_tail + 1U) % ADV_MAX_HOTPLUG_EVENTS;
        arkm_unlock_irqrestore(&advanced_hotplug_lock,irq);
        changed++;
        arkm_x_hotplug_tests++;
        uint64_t driver_flags;
        arkm_lock_irqsave(&advanced_driver_lock,&driver_flags);
        for (uint32_t i=0;i<advanced_driver_count;i++) {
            advanced_driver_t* d=&advanced_drivers[i];
            if (d->bus==ev.bus && d->slot==ev.slot && d->func==ev.func) {
                if (ev.type==1U) { d->active=1; d->health=ADV_DRIVER_HEALTH_OK; d->last_heartbeat=timer_ticks; }
                else if (ev.type==2U) { d->active=0; d->health=ADV_DRIVER_HEALTH_FAILED; }
            }
        }
        arkm_unlock_irqrestore(&advanced_driver_lock,driver_flags);
        arkm6_event_push(ARKM6_EVT_DEVICE, ((uint64_t)ev.bus<<32)|((uint64_t)ev.slot<<16)|ev.func, ev.type);
    }
    return changed;
}

/* ARKM-X8 swap backend. Swap is enabled only when the build explicitly reserves
 * an NVMe LBA region; ordinary boot/filesystem sectors are never assumed free. */
#define ARKM_X8_SWAP_BACKEND_NONE      0U
#define ARKM_X8_SWAP_BACKEND_NVME      1U
#define ARKM_X8_SWAP_SECTORS          (ARKM_X_SWAP_SLOTS * 8U)
static uint8_t arkm_x8_swap_backend = ARKM_X8_SWAP_BACKEND_NONE;
static uint32_t arkm_x8_swap_capacity = 0;
static uint8_t arkm_x8_qemu_profile = 0;
/* Read-only-visible swap diagnostics. These fields do not affect I/O policy. */
static volatile uint32_t arkm_x8_swap_diag_io_stage = 0;
static volatile uint32_t arkm_x8_swap_diag_test_stage = 0;
/* Fine-grained reason if creation of the isolated swap-test address space fails. */
static volatile uint32_t arkm_x8_swap_diag_page_create_stage = 0;
static volatile uint32_t arkm_x8_swap_diag_lba = 0;
static volatile uint32_t arkm_x8_swap_diag_polls = 0;
static volatile uint8_t arkm_x8_swap_diag_op = 0;       /* 1=read, 2=write */
static volatile uint8_t arkm_x8_swap_diag_cmd = 0;
static volatile uint8_t arkm_x8_swap_diag_status = 0;
static volatile uint8_t arkm_x8_swap_diag_wait_error = 0; /* 0=OK, 1=NVMe block-I/O failure */

/* Swap may use only an explicitly reserved NVMe LBA region. The old secondary
 * IDE/ATA path (ports 0x170/0x376 and READ/WRITE SECTORS commands) is removed.
 * Defaults intentionally disable disk swap until the build config provides a
 * region that cannot overlap the boot filesystem. */
#ifndef ARKM_X8_NVME_SWAP_BASE_LBA
#define ARKM_X8_NVME_SWAP_BASE_LBA 0U
#endif
#ifndef ARKM_X8_NVME_SWAP_SECTORS
#define ARKM_X8_NVME_SWAP_SECTORS 0U
#endif
static uint32_t arkm_x8_swap_base_lba = 0U;
static uint8_t arkm_x8_swap_disabled_logged = 0U;

static void arkm_x8_swap_probe(void) {
    arkm_x8_swap_backend = ARKM_X8_SWAP_BACKEND_NONE;
    arkm_x8_swap_capacity = 0U;
    arkm_x8_swap_base_lba = 0U;

    /* Do not guess that sectors near LBA 0 are free. Enabling swap on the boot
     * NVMe drive requires an explicit, reserved base + length from the build. */
    if (nvme_ready && ARKM_X8_NVME_SWAP_BASE_LBA > 0U &&
        ARKM_X8_NVME_SWAP_SECTORS >= ARKM_X8_SWAP_SECTORS &&
        ((uint64_t)ARKM_X8_NVME_SWAP_BASE_LBA +
         (uint64_t)ARKM_X8_NVME_SWAP_SECTORS) <= 0xFFFFFFFFULL) {
        arkm_x8_swap_base_lba = (uint32_t)ARKM_X8_NVME_SWAP_BASE_LBA;
        arkm_x8_swap_capacity = arkm_x8_swap_base_lba + (uint32_t)ARKM_X8_NVME_SWAP_SECTORS;
        arkm_x8_swap_backend = ARKM_X8_SWAP_BACKEND_NVME;
        qemu_serial_write("[SWAP] using explicitly reserved NVMe LBA region\n");
        return;
    }
    if (!arkm_x8_swap_disabled_logged) {
        qemu_serial_write("[SWAP] disabled: configure a dedicated NVMe swap LBA region\n");
        arkm_x8_swap_disabled_logged = 1U;
    }
}

static int arkm_xswap_disk_write(uint64_t lba, const void* buf, uint32_t sectors) {
    if (!buf || sectors == 0U || arkm_x8_swap_backend != ARKM_X8_SWAP_BACKEND_NVME ||
        lba < arkm_x8_swap_base_lba || lba > arkm_x8_swap_capacity ||
        (uint64_t)sectors > (uint64_t)arkm_x8_swap_capacity - lba)
        return 0;
    arkm_x8_swap_diag_op = 2U;
    arkm_x8_swap_diag_lba = (uint32_t)lba;
    arkm_x8_swap_diag_io_stage = 1U;
    int ok = nvme_write_blocks(lba, sectors, (void*)buf) != 0;
    arkm_x8_swap_diag_io_stage = ok ? 2U : 3U;
    arkm_x8_swap_diag_cmd = 0U;
    arkm_x8_swap_diag_status = 0U;
    arkm_x8_swap_diag_wait_error = ok ? 0U : 1U;
    return ok;
}

static int arkm_xswap_disk_read(uint64_t lba, void* buf, uint32_t sectors) {
    if (!buf || sectors == 0U || arkm_x8_swap_backend != ARKM_X8_SWAP_BACKEND_NVME ||
        lba < arkm_x8_swap_base_lba || lba > arkm_x8_swap_capacity ||
        (uint64_t)sectors > (uint64_t)arkm_x8_swap_capacity - lba)
        return 0;
    arkm_x8_swap_diag_op = 1U;
    arkm_x8_swap_diag_lba = (uint32_t)lba;
    arkm_x8_swap_diag_io_stage = 4U;
    int ok = nvme_read_blocks(lba, sectors, buf) != 0;
    arkm_x8_swap_diag_io_stage = ok ? 5U : 6U;
    arkm_x8_swap_diag_cmd = 0U;
    arkm_x8_swap_diag_status = 0U;
    arkm_x8_swap_diag_wait_error = ok ? 0U : 1U;
    return ok;
}

static uint64_t arkm_x8_swap_lba(uint32_t slot){
    return (uint64_t)arkm_x8_swap_base_lba + (uint64_t)slot * 8ULL;
}

static int arkm_xswap_find_slot(void) {
    for (uint32_t i=0;i<ARKM_X_SWAP_SLOTS;i++) if (!arkm_x_swap_entries[i].active) return (int)i;
    return -1;
}

static int arkm_xswap_out(uint64_t cr3, uint64_t va, uint32_t prot) {
    if (!cr3 || (va & (PAGE_SIZE - 1ULL)) != 0ULL ||
        arkm_x8_swap_backend == ARKM_X8_SWAP_BACKEND_NONE) return -1;
    spin_lock(&arkm_x_swap_lock);
    uint64_t* pte=NULL;
    if (!arkm_xvm_walk((uint64_t*)cr3,va,&pte)) { spin_unlock(&arkm_x_swap_lock); return -1; }
    uint64_t old=*pte;
    if (!(old&ARKM_XVM_PRESENT) || (old&ARKM_XVM_PS) ||
        (old & (ARKM_X7_COW_MARK | ADV_VM_COW))) {
        spin_unlock(&arkm_x_swap_lock); return -1;
    }
    uint64_t phys=old&0x000FFFFFFFFFF000ULL;
    int slot=arkm_xswap_find_slot(); if (slot<0) { spin_unlock(&arkm_x_swap_lock); return -1; }
    uint8_t page[PAGE_SIZE]; memcpy(page,(void*)phys,PAGE_SIZE);
    if (!arkm_xswap_disk_write(arkm_x8_swap_lba((uint32_t)slot),page,8U)) { spin_unlock(&arkm_x_swap_lock); return -1; }
    arkm_x_swap_entries[slot].active=1;
    arkm_x_swap_entries[slot].cr3=cr3;
    arkm_x_swap_entries[slot].virt=va;
    arkm_x_swap_entries[slot].slot=(uint32_t)slot;
    arkm_x_swap_entries[slot].prot=prot;
    arkm_x_swap_entries[slot].pte_flags=old & ~0x000FFFFFFFFFF000ULL;
    *pte=ARKM_X_SWAP_MARK | ((uint64_t)(slot+1U)<<ARKM_X_SWAP_SLOT_SHIFT);
    pmm_free_page((void*)phys);
    __asm__ volatile("invlpg (%0)" : : "r"(va) : "memory");
    arkm_x_swap_generation++;
    spin_unlock(&arkm_x_swap_lock);
    return slot;
}

static int arkm_xswap_in(uint64_t cr3, uint64_t va) {
    if (!cr3 || (va & (PAGE_SIZE - 1ULL)) != 0ULL ||
        arkm_x8_swap_backend == ARKM_X8_SWAP_BACKEND_NONE) return -1;
    spin_lock(&arkm_x_swap_lock);
    uint64_t* pte=NULL;
    if (!arkm_xvm_walk((uint64_t*)cr3,va,&pte)) { spin_unlock(&arkm_x_swap_lock); return -1; }
    uint64_t sw=*pte;
    if (!(sw&ARKM_X_SWAP_MARK) || (sw&ARKM_XVM_PRESENT)) { spin_unlock(&arkm_x_swap_lock); return -1; }
    uint64_t enc=(sw>>ARKM_X_SWAP_SLOT_SHIFT)&0xFFFFFU;
    if (!enc) { spin_unlock(&arkm_x_swap_lock); return -1; }
    uint32_t slot=(uint32_t)(enc-1U);
    if (slot>=ARKM_X_SWAP_SLOTS || !arkm_x_swap_entries[slot].active ||
        arkm_x_swap_entries[slot].slot != slot ||
        arkm_x_swap_entries[slot].cr3 != cr3 ||
        arkm_x_swap_entries[slot].virt != va) {
        spin_unlock(&arkm_x_swap_lock); return -1;
    }
    void* page=pmm_alloc_page(); if(!page) { spin_unlock(&arkm_x_swap_lock); return -1; }
    if (!arkm_xswap_disk_read(arkm_x8_swap_lba(slot),page,8U)) { pmm_free_page(page); spin_unlock(&arkm_x_swap_lock); return -1; }
    uint64_t restored_flags = arkm_x_swap_entries[slot].pte_flags;
    restored_flags &= ~(0x000FFFFFFFFFF000ULL | ARKM_X_SWAP_MARK |
                        (0xFFFFFULL << ARKM_X_SWAP_SLOT_SHIFT));
    restored_flags |= ARKM_XVM_PRESENT;
    *pte=((uint64_t)page)|restored_flags;
    arkm_x_swap_entries[slot].active=0;
    __asm__ volatile("invlpg (%0)" : : "r"(va) : "memory");
    arkm_x_swap_generation++;
    spin_unlock(&arkm_x_swap_lock);
    return 1;
}

static int arkm_xswap_fault(uint64_t cr3, uint64_t fault_addr) {
    uint64_t va=fault_addr&~(PAGE_SIZE-1ULL);
    return arkm_xswap_in(cr3,va);
}

static uint32_t arkm_xswap_reclaim_for_process(uint64_t cr3, uint32_t owner_pid) {
    if (arkm_x8_swap_backend == ARKM_X8_SWAP_BACKEND_NONE || !cr3 || !owner_pid ||
        arkm_cr3_active_on_any_cpu(cr3)) return 0U;
    for (uint32_t i = 0U; i < ARKM6_MAX_VM_AREAS; ++i) {
        arkm6_vm_area_t* area = &arkm6_vm_areas[i];
        if (!area->active || area->huge || area->owner_pid != owner_pid) continue;
        uint64_t start = area->virt;
        if (area->length == 0ULL || area->length > UINT64_MAX - start) continue;
        uint64_t end = start + area->length;
        for (uint64_t va = start; va < end; va += PAGE_SIZE) {
            uint64_t* pte = NULL;
            if (!arkm_xvm_walk((uint64_t*)cr3, va, &pte) || !pte) continue;
            uint64_t entry = *pte;
            if (!(entry & ARKM_XVM_PRESENT) || (entry & ARKM_XVM_PS) ||
                (entry & (ARKM_X7_COW_MARK | ADV_VM_COW))) continue;
            if (arkm_xswap_out(cr3, va, area->prot) >= 0) return 1U;
        }
    }
    return 0U;
}

static uint32_t arkm_xswap_reclaim_one(void) {
    uint64_t cr3 = arkm_x8_swap_context_cr3();
    uint32_t pid = cr3 ? arkm_process_pid_for_cr3(cr3) : 0U;
    return arkm_xswap_reclaim_for_process(cr3, pid);
}

static int arkm_x_acpi_checksum_ok(const uint8_t* p, uint32_t n) {
    uint8_t sum=0; if(!p||!n) return 0; for(uint32_t i=0;i<n;i++) sum=(uint8_t)(sum+p[i]); return sum==0;
}

static struct ACPISDTHeader* arkm_x_acpi_table(const char sig[4]) {
    struct RSDPDescriptor *rsdp = arkm_acpi_find_rsdp();
    if (!rsdp || !sig) return NULL;

    if (rsdp->Revision >= 2U && rsdp->XsdtAddress) {
        struct ACPISDTHeader *xsdt =
            (struct ACPISDTHeader *)(uintptr_t)rsdp->XsdtAddress;
        if (memcmp(xsdt->Signature, "XSDT", 4U) == 0 &&
            xsdt->Length >= sizeof(struct ACPISDTHeader) &&
            xsdt->Length <= 1024U * 1024U &&
            arkm_x_acpi_checksum_ok((const uint8_t *)xsdt, xsdt->Length)) {
            uint32_t count =
                (xsdt->Length - (uint32_t)sizeof(struct ACPISDTHeader)) / 8U;
            uint64_t *entries =
                (uint64_t *)((uint8_t *)xsdt + sizeof(struct ACPISDTHeader));
            for (uint32_t i = 0U; i < count; ++i) {
                if (!entries[i]) continue;
                struct ACPISDTHeader *h =
                    (struct ACPISDTHeader *)(uintptr_t)entries[i];
                if (memcmp(h->Signature, sig, 4U) == 0 &&
                    h->Length >= sizeof(struct ACPISDTHeader) &&
                    h->Length <= 1024U * 1024U &&
                    arkm_x_acpi_checksum_ok((const uint8_t *)h, h->Length))
                    return h;
            }
        }
    }

    if (rsdp->RsdtAddress) {
        struct ACPISDTHeader *rsdt =
            (struct ACPISDTHeader *)(uintptr_t)rsdp->RsdtAddress;
        if (memcmp(rsdt->Signature, "RSDT", 4U) == 0 &&
            rsdt->Length >= sizeof(struct ACPISDTHeader) &&
            rsdt->Length <= 1024U * 1024U &&
            arkm_x_acpi_checksum_ok((const uint8_t *)rsdt, rsdt->Length)) {
            uint32_t count =
                (rsdt->Length - (uint32_t)sizeof(struct ACPISDTHeader)) / 4U;
            uint32_t *entries =
                (uint32_t *)((uint8_t *)rsdt + sizeof(struct ACPISDTHeader));
            for (uint32_t i = 0U; i < count; ++i) {
                if (!entries[i]) continue;
                struct ACPISDTHeader *h =
                    (struct ACPISDTHeader *)(uintptr_t)entries[i];
                if (memcmp(h->Signature, sig, 4U) == 0 &&
                    h->Length >= sizeof(struct ACPISDTHeader) &&
                    h->Length <= 1024U * 1024U &&
                    arkm_x_acpi_checksum_ok((const uint8_t *)h, h->Length))
                    return h;
            }
        }
    }
    return NULL;
}

/*
 * ARKM IOMMU layer (Phase 9)
 * -------------------------
 * This layer parses the firmware topology, creates requester-specific DMA
 * domains, and stages real four-level second-stage page tables.  DMA mappings
 * are installed for the native device buffers below.  Translation is kept
 * disabled unless a later boot stage has explicitly quiesced every DMA engine;
 * the current boot sequence does not yet provide that global quiesce barrier.
 * The legacy physical-DMA path therefore remains operational on systems with
 * no IOMMU or unsupported firmware topology.
 */
#define ARKM_IOMMU_MAX_DOMAINS          64U
#define ARKM_IOMMU_MAX_DRHD             8U
#define ARKM_IOMMU_MAX_IVHD             8U
#define ARKM_IOMMU_DTE_ENTRIES         65536U
#define ARKM_IOMMU_DTE_BYTES            (ARKM_IOMMU_DTE_ENTRIES * 32U)
#define ARKM_IOMMU_DTE_PAGES            (ARKM_IOMMU_DTE_BYTES / PAGE_SIZE)
#define ARKM_IOMMU_PAGE_MASK            0x000FFFFFFFFFF000ULL
#define ARKM_IOMMU_ADDR_LIMIT           0x0001000000000000ULL
#define ARKM_IOMMU_PERM_READ            0x1U
#define ARKM_IOMMU_PERM_WRITE           0x2U
#define ARKM_IOMMU_BACKEND_NONE         0U
#define ARKM_IOMMU_BACKEND_VTD          1U
#define ARKM_IOMMU_BACKEND_AMDVI        2U
#define ARKM_IOMMU_BACKEND_SOFTWARE     3U
#define ARKM_IOMMU_CONTEXT_PRESENT      0x1ULL
#define ARKM_IOMMU_VTD_GCMD_SRTP        (1U << 30)
#define ARKM_IOMMU_VTD_GCMD_TE          (1U << 31)
#define ARKM_IOMMU_VTD_GSTS_RTPS        (1U << 30)
#define ARKM_IOMMU_VTD_GSTS_TES         (1U << 31)

/* ACPI DMAR fixed header: SDT(36) + HAW/flags/reserved(12). */
typedef struct __attribute__((packed)) {
    struct ACPISDTHeader h;
    uint8_t host_address_width;
    uint8_t flags;
    uint8_t reserved[10];
} arkm_dmar_header_t;

typedef struct __attribute__((packed)) {
    uint16_t type;
    uint16_t length;
} arkm_dmar_subheader_t;

typedef struct __attribute__((packed)) {
    uint16_t type;
    uint16_t length;
    uint8_t flags;
    uint8_t reserved;
    uint16_t segment;
    uint64_t register_base;
} arkm_dmar_drhd_t;

typedef struct __attribute__((packed)) {
    uint16_t type;
    uint16_t length;
    uint16_t reserved;
    uint16_t segment;
    uint64_t base_address;
    uint64_t limit_address;
} arkm_dmar_rmrr_t;

/* ACPI IVRS fixed header is 48 bytes (SDT + IVInfo + 8 reserved bytes). */
typedef struct __attribute__((packed)) {
    struct ACPISDTHeader h;
    uint32_t iv_info;
    uint8_t reserved[8];
} arkm_ivrs_header_t;

typedef struct __attribute__((packed)) {
    uint8_t type;
    uint8_t flags;
    uint16_t length;
    uint16_t device_id;
    uint16_t capability_offset;
    uint64_t register_base;
    uint16_t segment;
    uint16_t iommu_info;
    uint32_t reserved;
} arkm_ivrs_ivhd_t;

typedef struct __attribute__((packed)) {
    uint64_t lo;
    uint64_t hi;
} arkm_iommu_128_t;

typedef struct __attribute__((packed)) {
    uint64_t qword[4];
} arkm_iommu_amd_dte_t;

_Static_assert(sizeof(arkm_dmar_header_t) == 48U, "DMAR header layout");
_Static_assert(sizeof(arkm_dmar_drhd_t) == 16U, "DMAR DRHD layout");
_Static_assert(sizeof(arkm_dmar_rmrr_t) == 24U, "DMAR RMRR layout");
_Static_assert(sizeof(arkm_ivrs_header_t) == 48U, "IVRS header layout");
_Static_assert(sizeof(arkm_ivrs_ivhd_t) == 24U, "IVHD base header layout");
_Static_assert(sizeof(arkm_iommu_128_t) == 16U, "VT-d entry layout");
_Static_assert(sizeof(arkm_iommu_amd_dte_t) == 32U, "AMD DTE layout");

typedef struct {
    uint8_t present;
    uint8_t valid;
    uint8_t unsupported_topology;
    uint8_t translation_active;
    uint8_t vtd_eligible;
    uint8_t amdvi_eligible;
    uint8_t dmar_present;
    uint8_t ivrs_present;
    uint8_t dmar_valid;
    uint8_t ivrs_valid;
    uint8_t drhd_count;
    uint8_t ivhd_count;
    uint8_t include_all_count;
    uint8_t rmrr_count;
    uint8_t ivmd_count;
    uint8_t ats_scope_count;
    uint16_t segment;
    uint8_t host_address_width;
    uint8_t reserved0;
    uint64_t first_drhd_base;
    uint64_t first_ivhd_base;
    uint32_t malformed_entries;
} arkm_iommu_discovery_t;

/* Each requester gets a private 4-level translation root and distinct DID. */
typedef struct {
    uint8_t active;
    uint8_t backend;
    uint8_t bus;
    uint8_t slot;
    uint8_t func;
    uint8_t poisoned;
    uint16_t domain_id;
    uint32_t mapped_pages;
    uint32_t generation;
    uint64_t next_iova;
    uint64_t *pml4;
    uint64_t pml4_phys;
    spinlock_t lock;
} arkm_iommu_domain_t;

static arkm_iommu_discovery_t arkm_iommu_discovery;
static arkm_iommu_domain_t arkm_iommu_domains[ARKM_IOMMU_MAX_DOMAINS];
static spinlock_t arkm_iommu_domains_lock = 0;
static arkm_iommu_128_t *arkm_iommu_vtd_root = NULL;
static uint64_t *arkm_iommu_vtd_context[256];
static arkm_iommu_amd_dte_t *arkm_iommu_amd_dte_table = NULL;
static uint64_t *arkm_iommu_amd_deny_root = NULL;
static uint8_t arkm_iommu_amd_all_devices = 0U;
static uint8_t arkm_iommu_amd_device_coverage[ARKM_IOMMU_DTE_ENTRIES / 8U];
static uint16_t arkm_iommu_next_domain_id = 1U;
static uint32_t arkm_iommu_domain_generation = 1U;
static uint8_t arkm_iommu_tables_ready = 0U;
static uint8_t arkm_iommu_translation_active = 0U;

static uint16_t arkm_iommu_read_u16(const uint8_t *p) {
    uint16_t v = 0U;
    if (p) memcpy(&v, p, sizeof(v));
    return v;
}

static uint64_t arkm_iommu_read_u64(const uint8_t *p) {
    uint64_t v = 0ULL;
    if (p) memcpy(&v, p, sizeof(v));
    return v;
}

static int arkm_iommu_alloc_page(uint64_t **out) {
    if (!out) return 0;
    void *page = pmm_alloc_page();
    if (!page || (((uint64_t)(uintptr_t)page) & (PAGE_SIZE - 1ULL))) return 0;
    memset(page, 0, PAGE_SIZE);
    *out = (uint64_t *)page;
    return 1;
}

static uint64_t arkm_iommu_nonleaf_flags(uint8_t backend) {
    if (backend == ARKM_IOMMU_BACKEND_AMDVI)
        return 1ULL | (1ULL << 61) | (1ULL << 62); /* P | IR | IW */
    return 0x3ULL; /* Intel second-level P | R | W */
}

static uint64_t *arkm_iommu_next_table(uint64_t *parent, uint32_t index,
                                      uint8_t backend) {
    if (!parent || index >= 512U) return NULL;
    uint64_t entry = parent[index];
    if (entry & 1ULL) return (uint64_t *)(uintptr_t)(entry & ARKM_IOMMU_PAGE_MASK);
    uint64_t *child = NULL;
    if (!arkm_iommu_alloc_page(&child)) return NULL;
    parent[index] = ((uint64_t)(uintptr_t)child & ARKM_IOMMU_PAGE_MASK) |
                    arkm_iommu_nonleaf_flags(backend);
    __asm__ volatile("mfence" ::: "memory");
    return child;
}

static int arkm_iommu_map_one(arkm_iommu_domain_t *domain,
                              uint64_t iova, uint64_t phys,
                              uint32_t permissions) {
    if (!domain || !domain->active || !domain->pml4 ||
        (iova & (PAGE_SIZE - 1ULL)) || (phys & (PAGE_SIZE - 1ULL)) ||
        iova >= ARKM_IOMMU_ADDR_LIMIT || phys >= ARKM_IOMMU_ADDR_LIMIT ||
        (permissions & ~(ARKM_IOMMU_PERM_READ | ARKM_IOMMU_PERM_WRITE)) ||
        !(permissions & (ARKM_IOMMU_PERM_READ | ARKM_IOMMU_PERM_WRITE)))
        return 0;

    uint32_t pml4_i = (uint32_t)((iova >> 39) & 0x1FFULL);
    uint32_t pdpt_i = (uint32_t)((iova >> 30) & 0x1FFULL);
    uint32_t pd_i = (uint32_t)((iova >> 21) & 0x1FFULL);
    uint32_t pt_i = (uint32_t)((iova >> 12) & 0x1FFULL);
    uint64_t *pdpt = arkm_iommu_next_table(domain->pml4, pml4_i, domain->backend);
    if (!pdpt) return 0;
    uint64_t *pd = arkm_iommu_next_table(pdpt, pdpt_i, domain->backend);
    if (!pd) return 0;
    uint64_t *pt = arkm_iommu_next_table(pd, pd_i, domain->backend);
    if (!pt) return 0;

    uint64_t old = pt[pt_i];
    uint64_t perm;
    if (domain->backend == ARKM_IOMMU_BACKEND_AMDVI) {
        perm = 1ULL;
        if (permissions & ARKM_IOMMU_PERM_READ) perm |= 1ULL << 61;
        if (permissions & ARKM_IOMMU_PERM_WRITE) perm |= 1ULL << 62;
    } else {
        perm = 1ULL;
        if (permissions & ARKM_IOMMU_PERM_READ) perm |= 1ULL << 0;
        if (permissions & ARKM_IOMMU_PERM_WRITE) perm |= 1ULL << 1;
    }
    uint64_t wanted = (phys & ARKM_IOMMU_PAGE_MASK) | perm;
    if (old & 1ULL) {
        uint64_t permission_mask = (domain->backend == ARKM_IOMMU_BACKEND_AMDVI)
            ? ((1ULL << 61) | (1ULL << 62)) : 0x3ULL;
        if ((old & ARKM_IOMMU_PAGE_MASK) != (wanted & ARKM_IOMMU_PAGE_MASK) ||
            (old & permission_mask) != (wanted & permission_mask)) return 0;
        return 1; /* Exact mapping already exists. */
    }
    pt[pt_i] = wanted;
    __asm__ volatile("mfence" ::: "memory");
    domain->mapped_pages++;
    return 1;
}

static arkm_iommu_domain_t *arkm_iommu_domain_get(uint8_t bus,
                                                   uint8_t slot,
                                                   uint8_t func,
                                                   int create) {
    if (slot >= 32U || func >= 8U) return NULL;
    uint16_t requester_id = (uint16_t)(((uint16_t)bus << 8) |
                                       ((uint16_t)slot << 3) | func);
    if (arkm_iommu_discovery.amdvi_eligible &&
        !arkm_iommu_discovery.vtd_eligible &&
        !arkm_iommu_amd_device_is_covered(requester_id)) return NULL;
    uint64_t irq = 0ULL;
    arkm_lock_irqsave(&arkm_iommu_domains_lock, &irq);
    for (uint32_t i = 0U; i < ARKM_IOMMU_MAX_DOMAINS; ++i) {
        arkm_iommu_domain_t *d = &arkm_iommu_domains[i];
        if (d->active && d->bus == bus && d->slot == slot && d->func == func) {
            arkm_unlock_irqrestore(&arkm_iommu_domains_lock, irq);
            return d;
        }
    }
    if (!create || !arkm_iommu_tables_ready || arkm_iommu_next_domain_id == 0U) {
        arkm_unlock_irqrestore(&arkm_iommu_domains_lock, irq);
        return NULL;
    }
    for (uint32_t i = 0U; i < ARKM_IOMMU_MAX_DOMAINS; ++i) {
        arkm_iommu_domain_t *d = &arkm_iommu_domains[i];
        if (d->active) continue;
        uint64_t *root = NULL;
        if (!arkm_iommu_alloc_page(&root)) {
            arkm_unlock_irqrestore(&arkm_iommu_domains_lock, irq);
            return NULL;
        }
        memset(d, 0, sizeof(*d));
        d->active = 1U;
        d->backend = arkm_iommu_discovery.vtd_eligible ? ARKM_IOMMU_BACKEND_VTD :
                     (arkm_iommu_discovery.amdvi_eligible ? ARKM_IOMMU_BACKEND_AMDVI :
                      ARKM_IOMMU_BACKEND_SOFTWARE);
        d->bus = bus; d->slot = slot; d->func = func;
        d->domain_id = arkm_iommu_next_domain_id++;
        d->generation = arkm_iommu_domain_generation++;
        d->next_iova = 0x0000800000000000ULL; /* Separate high IOVA aperture. */
        d->pml4 = root;
        d->pml4_phys = (uint64_t)(uintptr_t)root;
        d->lock = 0;

        /* Publish Intel legacy root/context entries.  The hardware tables are
         * prepared now; activation is a separate, guarded operation. */
        if (d->backend == ARKM_IOMMU_BACKEND_VTD) {
            if (!arkm_iommu_vtd_context[bus]) {
                uint64_t *ctx = NULL;
                if (!arkm_iommu_alloc_page(&ctx)) {
                    memset(d, 0, sizeof(*d));
                    arkm_unlock_irqrestore(&arkm_iommu_domains_lock, irq);
                    return NULL;
                }
                arkm_iommu_vtd_context[bus] = ctx;
                arkm_iommu_vtd_root[bus].lo =
                    ((uint64_t)(uintptr_t)ctx & ARKM_IOMMU_PAGE_MASK) |
                    ARKM_IOMMU_CONTEXT_PRESENT;
                arkm_iommu_vtd_root[bus].hi = 0ULL;
            }
            uint32_t devfn = ((uint32_t)slot << 3) | func;
            uint64_t *ctx = arkm_iommu_vtd_context[bus];
            arkm_iommu_128_t *ce = (arkm_iommu_128_t *)(void *)&ctx[devfn * 2U];
            ce->lo = (d->pml4_phys & ARKM_IOMMU_PAGE_MASK) | 1ULL; /* P=1, TT=00b (multi-level) */
            ce->hi = 2ULL | ((uint64_t)d->domain_id << 8); /* AW=4-level */
        } else if (d->backend == ARKM_IOMMU_BACKEND_AMDVI) {
            /* AMD DTE: valid + translation-valid, 4-level host page table,
             * read/write permission, and DomainID at DTE bits 95:80. */
            if (!arkm_iommu_amd_dte_table) {
                memset(d, 0, sizeof(*d));
                arkm_unlock_irqrestore(&arkm_iommu_domains_lock, irq);
                return NULL;
            }
            arkm_iommu_amd_dte_t *dte = &arkm_iommu_amd_dte_table[requester_id];
            dte->qword[0] = (d->pml4_phys & ARKM_IOMMU_PAGE_MASK) |
                            (4ULL << 9) | (1ULL << 62) | (1ULL << 61) |
                            (1ULL << 1) | 1ULL;
            dte->qword[1] = (uint64_t)d->domain_id; /* DomainID occupies DTE bits 79:64. */
        }
        arkm_unlock_irqrestore(&arkm_iommu_domains_lock, irq);
        return d;
    }
    arkm_unlock_irqrestore(&arkm_iommu_domains_lock, irq);
    return NULL;
}

static int arkm_iommu_map_iova(uint8_t bus, uint8_t slot, uint8_t func,
                               uint64_t iova, uint64_t phys, uint64_t length,
                               uint32_t permissions) {
    /* No live IOTLB invalidation path exists yet.  Never mutate page tables
     * once translation is active; the current implementation is pre-map only. */
    if (arkm_iommu_translation_active) return 0;
    if (!length || length > (16ULL * 1024ULL * 1024ULL) ||
        (iova & (PAGE_SIZE - 1ULL)) || (phys & (PAGE_SIZE - 1ULL)) ||
        (length & (PAGE_SIZE - 1ULL)) ||
        iova >= ARKM_IOMMU_ADDR_LIMIT || phys >= ARKM_IOMMU_ADDR_LIMIT ||
        length > ARKM_IOMMU_ADDR_LIMIT - iova ||
        length > ARKM_IOMMU_ADDR_LIMIT - phys) return 0;
    arkm_iommu_domain_t *d = arkm_iommu_domain_get(bus, slot, func, 1);
    if (!d || d->poisoned) return 0;
    uint64_t irq = 0ULL;
    arkm_lock_irqsave(&d->lock, &irq);
    for (uint64_t off = 0ULL; off < length; off += PAGE_SIZE) {
        if (!arkm_iommu_map_one(d, iova + off, phys + off, permissions)) {
            /* Keep the domain non-activatable after a partial install. */
            d->poisoned = 1U;
            arkm_unlock_irqrestore(&d->lock, irq);
            return 0;
        }
    }
    arkm_unlock_irqrestore(&d->lock, irq);
    return 1;
}

int arkm_iommu_map_dma_alloc(uint8_t bus, uint8_t slot, uint8_t func,
                             uint64_t phys, uint64_t length,
                             uint32_t permissions, uint64_t *dma_address) {
    if (!dma_address || !length || phys > UINT64_MAX - length ||
        arkm_iommu_translation_active) return 0;
    if (!arkm_iommu_tables_ready) return 0;
    uint64_t offset = phys & (PAGE_SIZE - 1ULL);
    uint64_t page_phys = phys & ~(PAGE_SIZE - 1ULL);
    uint64_t span = offset + length;
    if (span > UINT64_MAX - (PAGE_SIZE - 1ULL)) return 0;
    uint64_t rounded = (span + PAGE_SIZE - 1ULL) & ~(PAGE_SIZE - 1ULL);
    if (!rounded || rounded > (16ULL * 1024ULL * 1024ULL) ||
        page_phys >= ARKM_IOMMU_ADDR_LIMIT ||
        rounded > ARKM_IOMMU_ADDR_LIMIT - page_phys) return 0;

    arkm_iommu_domain_t *d = arkm_iommu_domain_get(bus, slot, func, 1);
    if (!d || d->poisoned) return 0;
    uint64_t irq = 0ULL;
    arkm_lock_irqsave(&d->lock, &irq);
    uint64_t iova = (d->next_iova + PAGE_SIZE - 1ULL) & ~(PAGE_SIZE - 1ULL);
    if (iova < d->next_iova || iova >= ARKM_IOMMU_ADDR_LIMIT ||
        rounded > ARKM_IOMMU_ADDR_LIMIT - iova) {
        arkm_unlock_irqrestore(&d->lock, irq);
        return 0;
    }
    for (uint64_t off = 0ULL; off < rounded; off += PAGE_SIZE) {
        if (!arkm_iommu_map_one(d, iova + off, page_phys + off, permissions)) {
            d->poisoned = 1U;
            arkm_unlock_irqrestore(&d->lock, irq);
            return 0;
        }
    }
    d->next_iova = iova + rounded;
    *dma_address = iova + offset;
    arkm_unlock_irqrestore(&d->lock, irq);
    return 1;
}

static int arkm_iommu_prepare_dma(uint8_t bus, uint8_t slot, uint8_t func,
                                  uint64_t phys, uint64_t length,
                                  uint32_t permissions, uint64_t *dma_address) {
    if (!length || phys > UINT64_MAX - length) return 0;
    if (dma_address) *dma_address = phys;
    if (!arkm_iommu_tables_ready) return 1; /* Legacy physical-DMA fallback. */
    uint64_t page_phys = phys & ~(PAGE_SIZE - 1ULL);
    uint64_t end_phys = phys + length;
    if (end_phys > UINT64_MAX - (PAGE_SIZE - 1ULL)) return 0;
    uint64_t page_end = (end_phys + PAGE_SIZE - 1ULL) & ~(PAGE_SIZE - 1ULL);
    if (page_end < page_phys || page_end > ARKM_IOMMU_ADDR_LIMIT ||
        page_end - page_phys > (16ULL * 1024ULL * 1024ULL)) return 0;
    if (!arkm_iommu_map_iova(bus, slot, func, page_phys, page_phys,
                             page_end - page_phys, permissions)) return 0;
    if (dma_address) *dma_address = phys; /* Identity IOVA for existing drivers. */
    return 1;
}

static int arkm_iommu_domain_has_dma(uint8_t bus, uint8_t slot, uint8_t func) {
    arkm_iommu_domain_t *d = arkm_iommu_domain_get(bus, slot, func, 0);
    return d && !d->poisoned && d->mapped_pages != 0U;
}

static int arkm_iommu_pci_command_allowed(uint8_t bus, uint8_t slot,
                                           uint8_t func, uint16_t command) {
    if (!(command & 0x0004U) || !arkm_iommu_translation_active) return 1;
    return arkm_iommu_domain_has_dma(bus, slot, func);
}

static int arkm_iommu_dmar_parse(struct ACPISDTHeader *table) {
    if (!table || table->Length < sizeof(arkm_dmar_header_t)) return 0;
    arkm_dmar_header_t *dh = (arkm_dmar_header_t *)table;
    arkm_iommu_discovery.host_address_width = (uint8_t)(dh->host_address_width + 1U);
    uint8_t *p = (uint8_t *)table + sizeof(*dh);
    uint8_t *end = (uint8_t *)table + table->Length;
    uint32_t drhd_total = 0U;
    uint32_t include_all = 0U;
    uint32_t scope_bytes = 0U;
    uint32_t unsupported = 0U;
    while (p < end) {
        if ((uint64_t)(end - p) < sizeof(arkm_dmar_subheader_t)) return 0;
        uint16_t type = arkm_iommu_read_u16(p);
        uint16_t length = arkm_iommu_read_u16(p + 2U);
        if (length < sizeof(arkm_dmar_subheader_t) ||
            (uint64_t)(end - p) < length) return 0;
        if (type == 0U) { /* DRHD */
            if (length < sizeof(arkm_dmar_drhd_t)) return 0;
            arkm_dmar_drhd_t *drhd = (arkm_dmar_drhd_t *)(void *)p;
            drhd_total++;
            arkm_iommu_discovery.drhd_count++;
            if (drhd->segment != 0U || !drhd->register_base ||
                (drhd->register_base & (PAGE_SIZE - 1ULL))) unsupported++;
            if (drhd->flags & 1U) {
                include_all++;
                arkm_iommu_discovery.include_all_count++;
                if (!arkm_iommu_discovery.first_drhd_base)
                    arkm_iommu_discovery.first_drhd_base = drhd->register_base;
                arkm_iommu_discovery.segment = drhd->segment;
            }
            /* Device scopes are currently not resolved through PCI bridge
             * ancestry. A non-empty scope therefore blocks enablement. */
            scope_bytes += (uint32_t)length - (uint32_t)sizeof(*drhd);
            if (length > sizeof(*drhd)) unsupported++;
        } else if (type == 1U) { /* RMRR */
            if (length < sizeof(arkm_dmar_rmrr_t)) return 0;
            arkm_dmar_rmrr_t *rmrr = (arkm_dmar_rmrr_t *)(void *)p;
            if (rmrr->base_address > rmrr->limit_address ||
                (rmrr->base_address & (PAGE_SIZE - 1ULL)) ||
                ((rmrr->limit_address + 1ULL) & (PAGE_SIZE - 1ULL))) unsupported++;
            arkm_iommu_discovery.rmrr_count++;
            unsupported++;
        } else if (type == 2U) { /* ATSR */
            arkm_iommu_discovery.ats_scope_count++;
            unsupported++;
        } else if (type == 3U || type == 4U || type == 5U) {
            /* RHSA, ANDD, SATC: not required by this narrow legacy-mode path. */
            unsupported++;
        } else {
            unsupported++;
        }
        p += length;
    }
    if (p != end || drhd_total != 1U || include_all != 1U ||
        scope_bytes != 0U || unsupported != 0U ||
        arkm_iommu_discovery.host_address_width < 48U ||
        arkm_iommu_discovery.host_address_width > 52U) return 0;
    return 1;
}

static void arkm_iommu_amd_mark_device(uint16_t devid) {
    arkm_iommu_amd_device_coverage[devid >> 3] |= (uint8_t)(1U << (devid & 7U));
}

static int arkm_iommu_amd_device_is_covered(uint16_t devid) {
    if (arkm_iommu_amd_all_devices) return 1;
    return (arkm_iommu_amd_device_coverage[devid >> 3] &
            (uint8_t)(1U << (devid & 7U))) != 0U;
}

static int arkm_iommu_ivhd_entries_parse(uint8_t *p, uint8_t *end) {
    uint16_t range_start = 0U;
    int range_open = 0;
    while (p < end) {
        uint8_t type = p[0];
        uint32_t entry_length;
        if (type < 0x80U) entry_length = 4U << (type >> 6);
        else if (type == 0xF0U) {
            if ((uint64_t)(end - p) < 22ULL) return 0;
            entry_length = 22U + p[21];
        } else return 0; /* Unsupported variable/special entry: fail closed. */
        if (entry_length == 0U || (uint64_t)(end - p) < entry_length) return 0;
        if ((type & 0xC0U) != 0U || entry_length != 4U) return 0;

        uint16_t devid = arkm_iommu_read_u16(p + 1U);
        switch (type) {
            case 0x00U: /* PAD4 */
                if (range_open) return 0;
                break;
            case 0x01U: /* ALL */
                if (range_open) return 0;
                arkm_iommu_amd_all_devices = 1U;
                break;
            case 0x02U: /* SELECT */
                if (range_open) return 0;
                arkm_iommu_amd_mark_device(devid);
                break;
            case 0x03U: /* SELECT_RANGE_START */
                if (range_open) return 0;
                range_start = devid;
                range_open = 1;
                break;
            case 0x04U: /* RANGE_END */
                if (!range_open || devid < range_start) return 0;
                for (uint32_t id = range_start; id <= (uint32_t)devid; ++id)
                    arkm_iommu_amd_mark_device((uint16_t)id);
                range_open = 0;
                break;
            default:
                return 0;
        }
        p += entry_length;
    }
    return p == end && !range_open;
}

static int arkm_iommu_ivrs_parse(struct ACPISDTHeader *table) {
    if (!table || table->Length < sizeof(arkm_ivrs_header_t)) return 0;
    arkm_ivrs_header_t *ivrs_header = (arkm_ivrs_header_t *)(void *)table;
    /* The page-table builder currently implements AMD Mode=4 (48-bit IOVA).
     * Reject firmware that advertises narrower physical or virtual widths. */
    uint32_t physical_width = (ivrs_header->iv_info & 0x00007F00U) >> 8;
    uint32_t virtual_width = (ivrs_header->iv_info & 0x003F8000U) >> 15;
    if (physical_width < 48U || physical_width > 52U || virtual_width < 48U)
        return 0;
    arkm_iommu_discovery.host_address_width = (uint8_t)physical_width;
    uint8_t *p = (uint8_t *)table + sizeof(arkm_ivrs_header_t);
    uint8_t *end = (uint8_t *)table + table->Length;
    uint32_t ivhd_total = 0U;
    uint32_t ivmd_total = 0U;
    uint32_t unsupported = 0U;

    while (p < end) {
        if ((uint64_t)(end - p) < 4ULL) return 0;
        uint8_t type = p[0];
        uint16_t length = arkm_iommu_read_u16(p + 2U);
        if (length < 4U || (uint64_t)(end - p) < length) return 0;

        if (type == 0x10U || type == 0x11U || type == 0x40U) {
            uint32_t header_length = (type == 0x10U) ? 24U : 40U;
            if (length < header_length) return 0;
            arkm_ivrs_ivhd_t *ivhd = (arkm_ivrs_ivhd_t *)(void *)p;
            ivhd_total++;
            if (ivhd_total > ARKM_IOMMU_MAX_IVHD) unsupported++;
            arkm_iommu_discovery.ivhd_count++;
            if (!arkm_iommu_discovery.first_ivhd_base)
                arkm_iommu_discovery.first_ivhd_base = ivhd->register_base;
            if (!ivhd->register_base || (ivhd->register_base & (PAGE_SIZE - 1ULL)) ||
                ivhd->segment != 0U) unsupported++;
            if (!arkm_iommu_ivhd_entries_parse(p + header_length, p + length))
                unsupported++;
        } else if (type == 0x20U || type == 0x21U || type == 0x22U) {
            /* IVMD records carry unity-map/exclusion semantics. Their fixed
             * fields are range-checked, but this backend does not yet install
             * those firmware mappings, so any IVMD blocks activation. */
            if (length < 32U) return 0;
            uint16_t segment = arkm_iommu_read_u16(p + 8U);
            uint64_t range_start = arkm_iommu_read_u64(p + 16U);
            uint64_t range_length = arkm_iommu_read_u64(p + 24U);
            if (segment != 0U || range_length == 0ULL ||
                range_start > UINT64_MAX - range_length) return 0;
            ivmd_total++;
            arkm_iommu_discovery.ivmd_count++;
            unsupported++;
        } else {
            unsupported++;
        }
        p += length;
    }

    if (p != end || ivhd_total != 1U || ivmd_total != 0U || unsupported != 0U)
        return 0;
    if (!arkm_iommu_amd_all_devices) {
        uint32_t any = 0U;
        for (uint32_t i = 0U; i < sizeof(arkm_iommu_amd_device_coverage); ++i)
            any |= arkm_iommu_amd_device_coverage[i];
        if (!any) return 0;
    }
    return 1;
}

static void arkm_iommu_discover(void) {
    memset(&arkm_iommu_discovery, 0, sizeof(arkm_iommu_discovery));
    memset(arkm_iommu_domains, 0, sizeof(arkm_iommu_domains));
    memset(arkm_iommu_vtd_context, 0, sizeof(arkm_iommu_vtd_context));
    arkm_iommu_amd_dte_table = NULL;
    arkm_iommu_amd_deny_root = NULL;
    arkm_iommu_amd_all_devices = 0U;
    memset(arkm_iommu_amd_device_coverage, 0, sizeof(arkm_iommu_amd_device_coverage));
    arkm_iommu_vtd_root = NULL;
    arkm_iommu_tables_ready = 0U;
    arkm_iommu_translation_active = 0U;
    arkm_iommu_next_domain_id = 1U;

    struct ACPISDTHeader *dmar = arkm_x_acpi_table("DMAR");
    if (dmar) {
        arkm_iommu_discovery.dmar_present = 1U;
        arkm_iommu_discovery.dmar_valid =
            (uint8_t)arkm_iommu_dmar_parse(dmar);
        if (arkm_iommu_discovery.dmar_valid) {
            arkm_iommu_discovery.vtd_eligible = 1U;
        } else {
            arkm_iommu_discovery.unsupported_topology = 1U;
        }
    }

    struct ACPISDTHeader *ivrs = arkm_x_acpi_table("IVRS");
    if (ivrs) {
        arkm_iommu_discovery.ivrs_present = 1U;
        arkm_iommu_discovery.ivrs_valid =
            (uint8_t)arkm_iommu_ivrs_parse(ivrs);
        if (arkm_iommu_discovery.ivrs_valid) {
            /* AMD DTE and four-level page-table domains are staged in RAM.
             * Hardware register/command-buffer initialization is not enabled
             * by this Phase 9 boot path. */
            arkm_iommu_discovery.amdvi_eligible = 1U;
        } else {
            arkm_iommu_discovery.unsupported_topology = 1U;
        }
    }

    if (arkm_iommu_discovery.vtd_eligible) {
        uint64_t *root_page = NULL;
        if (arkm_iommu_alloc_page(&root_page)) {
            arkm_iommu_vtd_root = (arkm_iommu_128_t *)(void *)root_page;
            arkm_iommu_tables_ready = 1U;
        } else {
            arkm_iommu_discovery.vtd_eligible = 0U;
        }
    } else if (arkm_iommu_discovery.amdvi_eligible) {
        arkm_iommu_amd_deny_root = NULL;
        void *dte_memory = pmm_alloc_contiguous_pages(ARKM_IOMMU_DTE_PAGES);
        if (dte_memory && arkm_iommu_alloc_page(&arkm_iommu_amd_deny_root)) {
            arkm_iommu_amd_dte_table =
                (arkm_iommu_amd_dte_t *)(void *)dte_memory;
            /* A V=1, TV=1 entry rooted at an empty page table denies any
             * requester not subsequently assigned a mapped per-device root. */
            uint64_t deny_qword0 =
                ((uint64_t)(uintptr_t)arkm_iommu_amd_deny_root & ARKM_IOMMU_PAGE_MASK) |
                (4ULL << 9) | (1ULL << 1) | 1ULL;
            for (uint32_t id = 0U; id < ARKM_IOMMU_DTE_ENTRIES; ++id) {
                arkm_iommu_amd_dte_table[id].qword[0] = deny_qword0;
                arkm_iommu_amd_dte_table[id].qword[1] = 0ULL;
            }
            __asm__ volatile("mfence" ::: "memory");
            arkm_iommu_tables_ready = 1U;
        } else {
            if (dte_memory)
                pmm_free_contiguous_pages(dte_memory, ARKM_IOMMU_DTE_PAGES);
            if (arkm_iommu_amd_deny_root) {
                pmm_free_page(arkm_iommu_amd_deny_root);
                arkm_iommu_amd_deny_root = NULL;
            }
            arkm_iommu_discovery.amdvi_eligible = 0U;
        }
    }

    arkm_iommu_discovery.present =
        (uint8_t)(arkm_iommu_discovery.dmar_present || arkm_iommu_discovery.ivrs_present);
    arkm_iommu_discovery.valid =
        (uint8_t)(arkm_iommu_discovery.vtd_eligible || arkm_iommu_discovery.amdvi_eligible);
    arkm_iommu_discovery.translation_active = 0U;
    qemu_serial_write("[IOMMU] DMAR=");
    qemu_serial_write(arkm_iommu_discovery.dmar_valid ? "VALID" :
                      (arkm_iommu_discovery.dmar_present ? "INVALID" : "ABSENT"));
    qemu_serial_write(" IVRS=");
    qemu_serial_write(arkm_iommu_discovery.ivrs_valid ? "STRUCTURE-VALID/STAGED" :
                      (arkm_iommu_discovery.ivrs_present ? "UNSUPPORTED/INVALID" : "ABSENT"));
    qemu_serial_write(arkm_iommu_tables_ready ?
        " domains=READY hardware-translation=OFF (quiesce gate pending)\n" :
        " domains=UNAVAILABLE hardware-translation=OFF (legacy DMA retained)\n");
}


static int arkm_iommu_verify_busmaster_coverage(void) {
    if (!arkm_iommu_tables_ready || !arkm_pci_ecam_ready ||
        arkm_pci_ecam_region_count == 0U) return 0;
    /* Do not claim segment-wide coverage when the MCFG map exposes only a
     * subset of buses. Every bus in segment 0 must be reachable via ECAM. */
    for (uint32_t bus = 0U; bus < 256U; ++bus) {
        int covered = 0;
        for (uint32_t region = 0U; region < arkm_pci_ecam_region_count; ++region) {
            arkm_pci_ecam_region_t *r = &arkm_pci_ecam_regions[region];
            if (r->valid && r->segment_group == 0U &&
                bus >= r->start_bus && bus <= r->end_bus) {
                covered = 1;
                break;
            }
        }
        if (!covered) return 0;
    }
    uint32_t scanned = 0U;
    for (uint32_t region = 0U; region < arkm_pci_ecam_region_count; ++region) {
        arkm_pci_ecam_region_t *r = &arkm_pci_ecam_regions[region];
        if (!r->valid || r->segment_group != 0U) continue;
        for (uint32_t bus = r->start_bus; bus <= r->end_bus; ++bus) {
            for (uint32_t slot = 0U; slot < 32U; ++slot) {
                uint16_t vendor0 = pci_config_read_word((uint8_t)bus,
                                                         (uint8_t)slot, 0U, 0U);
                if (vendor0 == 0xFFFFU) continue;
                uint16_t header = pci_config_read_word((uint8_t)bus,
                    (uint8_t)slot, 0U, 0x0EU);
                uint32_t functions = (header & 0x80U) ? 8U : 1U;
                for (uint32_t func = 0U; func < functions; ++func) {
                    uint16_t vendor = pci_config_read_word((uint8_t)bus,
                        (uint8_t)slot, (uint8_t)func, 0U);
                    if (vendor == 0xFFFFU) continue;
                    uint16_t cmd = pci_config_read_word((uint8_t)bus,
                        (uint8_t)slot, (uint8_t)func, 0x04U);
                    scanned++;
                    if ((cmd & 0x0004U) &&
                        !arkm_iommu_domain_has_dma((uint8_t)bus, (uint8_t)slot,
                                                   (uint8_t)func)) return 0;
                }
            }
        }
    }
    return scanned != 0U;
}

static void arkm_iommu_report_busmaster_coverage(void) {
    if (!arkm_iommu_tables_ready) return;
    qemu_serial_write(arkm_iommu_verify_busmaster_coverage()
        ? "[IOMMU] staged DMA mappings cover every active PCI bus master\n"
        : "[IOMMU] DMA coverage incomplete; hardware translation remains disabled\n");
}

typedef struct {
    struct ACPISDTHeader h;
    uint32_t firmware_ctrl;
    uint32_t dsdt;
    uint8_t reserved0;
    uint8_t preferred_pm_profile;
    uint16_t sci_int;
    uint32_t smi_cmd;
    uint8_t acpi_enable;
    uint8_t acpi_disable;
    uint8_t s4bios_req;
    uint8_t pstate_cnt;
    uint32_t pm1a_evt_blk;
    uint32_t pm1b_evt_blk;
    uint32_t pm1a_cnt_blk;
    uint32_t pm1b_cnt_blk;
    uint32_t pm2_cnt_blk;
    uint32_t pm_tmr_blk;
    uint32_t gpe0_blk;
    uint32_t gpe1_blk;
    uint8_t pm1_evt_len;
    uint8_t pm1_cnt_len;
    uint8_t pm2_cnt_len;
    uint8_t pm_tmr_len;
} __attribute__((packed)) arkm_x_fadt_head_t;

static void arkm_xpower_probe(void) {
    memset(&arkm_xpower,0,sizeof(arkm_xpower));
    struct ACPISDTHeader* h=arkm_x_acpi_table("FACP");
    if(!h || h->Length < sizeof(arkm_x_fadt_head_t)) return;
    arkm_x_fadt_head_t* f=(arkm_x_fadt_head_t*)h;
    arkm_xpower.present=1;
    arkm_xpower.acpi_version=h->Revision;
    arkm_xpower.pm1a_cnt=f->pm1a_cnt_blk;
    arkm_xpower.pm1b_cnt=f->pm1b_cnt_blk;
    arkm_xpower.pm1_cnt_len=f->pm1_cnt_len;
    arkm_xpower.sci_irq=f->sci_int;
    arkm_xpower.resume_ready=1;
}

static int arkm_xpower_suspend(uint32_t mode) {
    if(mode==ARKM_XPOWER_SOFT_RESUME) {
        arkm_xpower.soft_suspended=0;
        arkm_xpower.suspend_tick=0;
        arkm_xpower.resume_ready=1;
        return 0;
    }
    if(mode==ARKM_XPOWER_SOFT_SUSPEND) {
        if(!arkm_xpower.present) return -1;
        arkm_xpower.soft_suspended=1;
        arkm_xpower.suspend_tick=timer_ticks;
        arkm_xpower.resume_ready=1;
        return 0;
    }
    return -1;
}

static void arkm_xvirt_probe(void) {
    memset(&arkm_xvirt,0,sizeof(arkm_xvirt));
    uint32_t a,b,c,d;
    __asm__ volatile("cpuid":"=a"(a),"=b"(b),"=c"(c),"=d"(d):"a"(1),"c"(0):"memory");
    arkm_xvirt.hypervisor=(uint8_t)((c>>31)&1U);
    arkm_xvirt.vmx=(uint8_t)((c>>5)&1U);
    __asm__ volatile("cpuid":"=a"(a),"=b"(b),"=c"(c),"=d"(d):"a"(0x80000000U),"c"(0):"memory");
    if(a>=0x80000001U){__asm__ volatile("cpuid":"=a"(a),"=b"(b),"=c"(c),"=d"(d):"a"(0x80000001U),"c"(0):"memory"); arkm_xvirt.svm=(uint8_t)((c>>2)&1U);}
    if(arkm_xvirt.vmx) {
        uint32_t lo,hi;
        __asm__ volatile("rdmsr":"=a"(lo),"=d"(hi):"c"(0x3AU));
        arkm_xvirt.feature_control=((uint64_t)hi<<32)|lo;
        void* page=pmm_alloc_page(); if(page){arkm_xvirt.control_page=page; arkm_xvirt.control_phys=(uint64_t)page; memset(page,0,PAGE_SIZE); *(uint32_t*)page=0; arkm_xvirt.staged=1;}
    }
    if(arkm_xvirt.svm) {
        uint32_t lo,hi; __asm__ volatile("rdmsr":"=a"(lo),"=d"(hi):"c"(0xC0000080U)); arkm_xvirt.efer=((uint64_t)hi<<32)|lo;
        uint32_t vmcr_lo, vmcr_hi; __asm__ volatile("rdmsr":"=a"(vmcr_lo),"=d"(vmcr_hi):"c"(0xC0010114U));
        uint64_t vmcr=((uint64_t)vmcr_hi<<32)|vmcr_lo;
        if(!(vmcr & (1ULL<<4))) {
            void* page=pmm_alloc_page();
            if(page){ memset(page,0,PAGE_SIZE); arkm_xvirt.control_page=page; arkm_xvirt.control_phys=(uint64_t)page; arkm_xvirt.staged=1; }
        }
    }
}

static int arkm_xns_create(const char* name, uint64_t cpu_mask, uint64_t mem_pages, uint32_t parent) {
    uint64_t irq; arkm_lock_irqsave(&arkm_x_ns_lock,&irq);
    for(uint32_t i=1;i<ARKM_X_NS_MAX;i++) if(!arkm_x_namespaces[i].active){
        memset(&arkm_x_namespaces[i],0,sizeof(arkm_x_namespaces[i]));
        arkm_x_namespaces[i].active=1; arkm_x_namespaces[i].id=arkm_x_ns_next++; arkm_x_namespaces[i].parent_id=parent;
        arkm_x_namespaces[i].cpu_mask=cpu_mask?cpu_mask:amp_foundation.schedulable_mask;
        arkm_x_namespaces[i].memory_limit_pages=mem_pages; arkm_x_namespaces[i].pid_base=1000U+i*64U;
        arkm_x_namespaces[i].mount_id=arkm_x_namespaces[i].id; arkm_x_namespaces[i].net_id=arkm_x_namespaces[i].id; arkm_x_namespaces[i].ipc_id=arkm_x_namespaces[i].id;
        if(name) {uint32_t n=0;while(name[n]&&n<sizeof(arkm_x_namespaces[i].name)-1U){arkm_x_namespaces[i].name[n]=name[n];n++;}arkm_x_namespaces[i].name[n]=0;}
        arkm_unlock_irqrestore(&arkm_x_ns_lock,irq); return (int)arkm_x_namespaces[i].id;
    }
    arkm_unlock_irqrestore(&arkm_x_ns_lock,irq); return -1;
}

static void arkm_xns_init(void) {
    memset(arkm_x_namespaces,0,sizeof(arkm_x_namespaces));
    arkm_x_namespaces[0].active=1; arkm_x_namespaces[0].id=1; arkm_x_namespaces[0].cpu_mask=amp_foundation.schedulable_mask; arkm_x_namespaces[0].memory_limit_pages=TOTAL_PAGES; strcpy(arkm_x_namespaces[0].name,"root");
    arkm_x_ns_next=2;
}

struct arkm_x_eth_ipv6 { uint8_t dst[6]; uint8_t src[6]; uint16_t type; } __attribute__((packed));
struct arkm_x_ipv6 { uint32_t vtcfl; uint16_t payload_len; uint8_t next; uint8_t hop; uint64_t src_hi,src_lo,dst_hi,dst_lo; } __attribute__((packed));
struct arkm_x_icmp6 { uint8_t type,code; uint16_t checksum; uint32_t rest; } __attribute__((packed));

/* Shared with the X7 IPv6 path below.  Keep checksum arithmetic byte-oriented:
 * IPv6 pseudo-header words must be interpreted in network byte order, not the
 * host's native uint16_t/uint64_t order. */
static uint16_t arkm_x7_ipv6_checksum_bytes(const uint8_t src[16],
                                             const uint8_t dst[16],
                                             uint8_t next,
                                             const uint8_t* payload,
                                             uint32_t len);

static uint32_t arkm_x_ipv6_checksum(const struct arkm_x_ipv6* ip,
                                     const void* payload, uint32_t len) {
    if (!ip || (!payload && len != 0U)) return 0xFFFFFFFFU;
    /* src/dst fields are packed directly into the wire-format IPv6 header. */
    const uint8_t* header_bytes = (const uint8_t*)ip;
    const uint8_t* src = header_bytes + offsetof(struct arkm_x_ipv6, src_hi);
    const uint8_t* dst = header_bytes + offsetof(struct arkm_x_ipv6, dst_hi);
    return (uint32_t)arkm_x7_ipv6_checksum_bytes(
        src, dst, ARKM_XNET6_NEXT_ICMPV6, (const uint8_t*)payload, len);
}

static void arkm_xnet6_init(void) {
    memset(&arkm_xnet,0,sizeof(arkm_xnet));
    arkm_xnet.enabled = e1000_mmio_base ? 1U : 0U;
    if(!arkm_xnet.enabled) return;
    uint64_t eui64 = ((uint64_t)(mac_addr[0] ^ 0x02U) << 56) |
                     ((uint64_t)mac_addr[1] << 48) |
                     ((uint64_t)mac_addr[2] << 40) |
                     (0xFFULL << 32) | (0xFEULL << 24) |
                     ((uint64_t)mac_addr[3] << 16) |
                     ((uint64_t)mac_addr[4] << 8) | (uint64_t)mac_addr[5];
    arkm_xnet.ipv6_hi=0xFE80000000000000ULL;
    arkm_xnet.ipv6_lo=eui64;
    arkm_xnet.gateway=ARKM_X_GATEWAY_V4;
    arkm_xnet.dns_server=ARKM_X_DEFAULT_DNS_V4;
    arkm_xnet.dhcp_xid=ARKM_X_DHCP_XID;
    arkm_xnet.dns_txid=ARKM_X_DNS_TXID;
}

static int arkm_xnet6_echo_reply(const uint8_t* raw, uint16_t packet_len) {
    if(packet_len < sizeof(struct arkm_x_eth_ipv6)+sizeof(struct arkm_x_ipv6)+sizeof(struct arkm_x_icmp6)) return 0;
    const struct arkm_x_eth_ipv6* eth=(const struct arkm_x_eth_ipv6*)raw;
    const struct arkm_x_ipv6* in=(const struct arkm_x_ipv6*)(raw+sizeof(*eth));
    uint16_t plen=ntohs(in->payload_len);
    if ((ntohl(in->vtcfl) >> 28) != 6U ||
        in->next != ARKM_XNET6_NEXT_ICMPV6 ||
        plen < sizeof(struct arkm_x_icmp6) ||
        (uint32_t)plen + 40U + 14U > packet_len) return 0;
    struct arkm_x_icmp6* ic=(struct arkm_x_icmp6*)((uint8_t*)in+40);
    if(ic->type!=ARKM_XNET6_ICMP_ECHO_REQUEST || ic->code!=0U ||
       arkm_x_ipv6_checksum(in,ic,plen)!=0U) return 0;
    uint8_t out[14+40+1536]; if(plen>1536) return 0;
    struct arkm_x_eth_ipv6* eo=(struct arkm_x_eth_ipv6*)out; struct arkm_x_ipv6* io=(struct arkm_x_ipv6*)(out+14); struct arkm_x_icmp6* co=(struct arkm_x_icmp6*)(out+14+40);
    memcpy(eo->dst,eth->src,6); memcpy(eo->src,mac_addr,6); eo->type=htons(ARKM_X_IPV6_TYPE);
    *io=*in; io->src_hi=in->dst_hi; io->src_lo=in->dst_lo; io->dst_hi=in->src_hi; io->dst_lo=in->src_lo; io->hop=64;
    memcpy(co,(const uint8_t*)in+40,plen);
    co->type=ARKM_XNET6_ICMP_ECHO_REPLY;
    co->checksum=0;
    /* The helper returns the checksum as a host numeric value formed from
     * network-order bytes; htons() serializes it into the on-wire field. */
    co->checksum=htons((uint16_t)arkm_x_ipv6_checksum(io,co,plen));
    e1000_send_packet(out,14U+40U+plen); return 1;
}

void arkm_xnet6_ingress(uint8_t* raw, uint16_t len) {
    if(!arkm_xnet.enabled) return;
    if (!arkm_x7_net6_ingress(raw,len)) (void)arkm_xnet6_echo_reply(raw,len);
}

static uint16_t arkm_x7_checksum_host(const void* data, uint32_t len) {
    const uint8_t* p=(const uint8_t*)data; uint32_t sum=0;
    while(len>=2U){ sum += ((uint32_t)p[0]<<8) | p[1]; p+=2; len-=2U; }
    if(len) sum += (uint32_t)p[0]<<8;
    while(sum>>16) sum=(sum&0xFFFFU)+(sum>>16);
    return (uint16_t)~sum;
}

static uint16_t arkm_x7_checksum_be(const void* data, uint32_t len) {
    return htons(arkm_x7_checksum_host(data,len));
}

static void arkm_xdhcp_send_discover(void) {
    uint8_t pkt[1600];
    memset(pkt, 0, sizeof(pkt));
    ethernet_hdr_t* eth=(ethernet_hdr_t*)pkt;
    ipv4_hdr_t* ip=(ipv4_hdr_t*)(pkt+14);
    udp_hdr_t* udp=(udp_hdr_t*)(pkt+14+20);
    uint8_t* dhcp=pkt+14+20+8;

    memset(eth->dest_mac, 0xFF, 6);
    memcpy(eth->src_mac, mac_addr, 6);
    eth->ethertype=htons(0x0800);

    ip->version_ihl=0x45; ip->ttl=64; ip->protocol=17;
    ip->src_ip=0; ip->dest_ip=0xFFFFFFFFU;

    udp->src_port=htons(ARKM_X_DHCP_CLIENT_PORT);
    udp->dest_port=htons(ARKM_X_DHCP_SERVER_PORT);
    udp->checksum=0;

    /* BOOTP/DHCP fixed header is exactly 236 bytes. */
    dhcp[0]=1;  /* BOOTREQUEST */
    dhcp[1]=1;  /* Ethernet */
    dhcp[2]=6;  /* MAC length */
    dhcp[3]=0;  /* hops */
    *(uint32_t*)(dhcp+4)=htonl(arkm_xnet.dhcp_xid);
    *(uint16_t*)(dhcp+10)=htons(0x8000U);
    memcpy(dhcp+28, mac_addr, 6);
    *(uint32_t*)(dhcp+236)=htonl(0x63825363U);

    uint8_t* o=dhcp+240;
    *o++=53; *o++=1; *o++=1;                    /* DHCP Discover */
    *o++=55; *o++=3; *o++=1; *o++=3; *o++=6;    /* mask/router/DNS */
    *o++=255;

    uint16_t used=(uint16_t)(o-dhcp);
    if(used < 300U) { memset(dhcp+used, 0, 300U-used); used=300U; }
    udp->length=htons((uint16_t)(8U+used));
    ip->total_len=htons((uint16_t)(20U+8U+used));
    ip->checksum=0; ip->checksum=arkm_x7_checksum_be(ip,20);
    e1000_send_packet(pkt,(uint16_t)(14U+20U+8U+used));
}

static int arkm_xdhcp_rx(ipv4_hdr_t* ip, udp_hdr_t* udp, uint8_t* payload, uint16_t len) {
    (void)ip;
    if(ntohs(udp->dest_port)!=68 || len<240 || ntohl(*(uint32_t*)(payload+4))!=ARKM_X_DHCP_XID) return 0;
    uint32_t cookie=ntohl(*(uint32_t*)(payload+236)); if(cookie!=0x63825363U) return 1;
    uint8_t* o=payload+240; uint16_t left=(uint16_t)(len-240);
    while(left>0){
        uint8_t code=*o++; left--;
        if(code==0) continue;             /* DHCP PAD is one byte, not a TLV. */
        if(code==255) break;
        if(left<1) break;
        uint8_t olen=*o++; left--;
        if(olen>left) break;
        if(code==1&&olen==4)memcpy(&arkm_xnet.netmask,o,4);
        else if(code==3&&olen>=4)memcpy(&arkm_xnet.gateway,o,4);
        else if(code==6&&olen>=4){memcpy(&arkm_xnet.dns_server,o,4);arkm_xnet.dns_ready=1;}
        else if(code==51&&olen==4)arkm_xnet.lease_seconds=ntohl(*(uint32_t*)o);
        o+=olen;left=(uint16_t)(left-olen);
    }
    return 1;
}

/* DNS observability counters: deliberately passive; they do not alter packet flow. */
static volatile uint32_t arkm_xdns_dbg_tx_attempts;
static volatile uint32_t arkm_xdns_dbg_tx_submitted;
static volatile uint32_t arkm_xdns_dbg_arp_missing;
static volatile uint32_t arkm_xdns_dbg_udp_rx_seen;
static volatile uint32_t arkm_xdns_dbg_udp_rx_53000;
static volatile uint32_t arkm_xdns_dbg_rx_id_match;
static volatile uint32_t arkm_xdns_dbg_dns_responses;
static volatile uint32_t arkm_xdns_dbg_a_answers;
static volatile uint32_t arkm_xdns_dbg_short_packets;
static volatile uint32_t arkm_xdns_dbg_last_send_status; /* 0=queued, 1=no DNS server, 2=ARP missing, 3=invalid name */
static volatile uint32_t arkm_xdns_dbg_last_src_ip;
static volatile uint32_t arkm_xdns_dbg_last_dst_ip;
static volatile uint16_t arkm_xdns_dbg_last_src_port;
static volatile uint16_t arkm_xdns_dbg_last_dst_port;
static volatile uint16_t arkm_xdns_dbg_last_rx_id;
static volatile uint16_t arkm_xdns_dbg_last_flags;
static volatile uint16_t arkm_xdns_dbg_last_answer_count;
static volatile uint8_t arkm_xdns_dbg_last_rcode;

static uint16_t arkm_xdns_encode_name(const char* name, uint8_t* out, uint16_t cap) {
    if(!name || !out || cap < 2) return 0;
    uint16_t pos=0, start=0;
    uint32_t n=0;
    while(1){
        char c=name[n];
        if(c=='.' || c==0){
            uint16_t len=(uint16_t)(n-start);
            if(len>63 || pos+len+1>=cap) return 0;
            out[pos++]=(uint8_t)len;
            for(uint16_t i=0;i<len;i++) out[pos++]=(uint8_t)name[start+i];
            if(c==0){out[pos++]=0;break;}
            start=n+1;
        }
        n++;
    }
    return pos;
}

/* Advance over one encoded DNS name. Compression pointers occupy two bytes
 * in the original message and terminate the name at this location. */
static int arkm_xdns_skip_name(const uint8_t* msg, uint16_t len, uint16_t* off) {
    if(!msg || !off || *off>=len) return 0;
    uint32_t pos=*off;
    for(uint32_t steps=0;steps<(uint32_t)len;steps++) {
        if(pos>=len) return 0;
        uint8_t label=msg[pos];
        if(label==0) { *off=(uint16_t)(pos+1U); return 1; }
        if((label&0xC0U)==0xC0U) {
            if(pos+1U>=len) return 0;
            uint16_t target=(uint16_t)(((uint16_t)(label&0x3FU)<<8)|msg[pos+1U]);
            if(target>=len) return 0;
            *off=(uint16_t)(pos+2U);
            return 1;
        }
        if((label&0xC0U)!=0U || pos+1U+(uint32_t)label>len) return 0;
        pos+=1U+(uint32_t)label;
    }
    return 0;
}

static uint16_t arkm_xudp_checksum_ipv4(uint32_t src, uint32_t dst, uint8_t proto, const void* data, uint16_t len) {
    uint8_t pseudo[12];
    memcpy(pseudo, &src, 4); memcpy(pseudo+4, &dst, 4);
    pseudo[8]=0; pseudo[9]=proto; pseudo[10]=(uint8_t)(len>>8); pseudo[11]=(uint8_t)len;
    uint32_t sum=0;
    const uint8_t* p=pseudo;
    for(uint32_t i=0;i<12;i+=2) sum += ((uint32_t)p[i]<<8)|p[i+1];
    p=(const uint8_t*)data; uint32_t n=len;
    while(n>=2U){sum += ((uint32_t)p[0]<<8)|p[1]; p+=2; n-=2U;}
    if(n) sum += (uint32_t)p[0]<<8;
    while(sum>>16) sum=(sum&0xFFFFU)+(sum>>16);
    return htons((uint16_t)~sum);
}

static uint32_t arkm_xdns_next_hop(void) {
    uint32_t dns = arkm_xnet.dns_server;
    uint32_t gateway = arkm_xnet.gateway ? arkm_xnet.gateway : ARKM_X_GATEWAY_V4;
    uint32_t mask = arkm_xnet.netmask ? arkm_xnet.netmask : IP_V4(255,255,255,0);
    if (!dns) return 0;

    /* QEMU user-mode networking exposes 10.0.2.3 as a virtual DNS service,
       not an ordinary host on the emulated Ethernet segment. Send the frame
       to the SLIRP gateway MAC while preserving 10.0.2.3 as the IP destination.
       This avoids making the very first DNS query depend on a separate ARP
       entry for the synthetic DNS address. */
    if (dns == ARKM_X_DEFAULT_DNS_V4 && gateway == ARKM_X_GATEWAY_V4)
        return gateway;

    /* Other networks use normal on-link neighbor resolution. */
    return ((dns & mask) == (local_kernel_ip & mask)) ? dns : gateway;
}

static int arkm_xdns_send(const char* name) {
    arkm_xdns_dbg_tx_attempts++;
    uint8_t pkt[600]; memset(pkt,0,sizeof(pkt));
    if(!name || !name[0] || !arkm_xnet.dns_server) { arkm_xdns_dbg_last_send_status=1U; return -1; }
    uint32_t next_hop = arkm_xdns_next_hop();
    if (!next_hop) { arkm_xdns_dbg_last_send_status=1U; return -1; }
    int have=0; uint8_t mac[6]={0}; uint64_t irq; arkm_lock_irqsave(&net_stack_lock,&irq);
    for(int i=0;i<MAX_ARP_ENTRIES;i++) if(arp_table[i].valid&&arp_table[i].ip==next_hop){memcpy(mac,arp_table[i].mac,6);have=1;break;}
    arkm_unlock_irqrestore(&net_stack_lock,irq);
    if(!have){arkm_xdns_dbg_arp_missing++;arkm_xdns_dbg_last_send_status=2U;arkm_xnet_arp_probe_for(next_hop);return -2;}
    ethernet_hdr_t* eth=(ethernet_hdr_t*)pkt; ipv4_hdr_t* ip=(ipv4_hdr_t*)(pkt+14); udp_hdr_t* udp=(udp_hdr_t*)(pkt+34); uint8_t* dns=pkt+42;
    memcpy(eth->dest_mac,mac,6);memcpy(eth->src_mac,mac_addr,6);eth->ethertype=htons(0x0800);
    ip->version_ihl=0x45;ip->ttl=64;ip->protocol=17;ip->src_ip=local_kernel_ip;ip->dest_ip=arkm_xnet.dns_server;
    uint8_t* d=dns;*(uint16_t*)d=htons(arkm_xnet.dns_txid);d+=2;*(uint16_t*)d=htons(0x0100);d+=2;*(uint16_t*)d=htons(1);d+=2;d+=6;uint16_t qn=arkm_xdns_encode_name(name,d,500);if(!qn){arkm_xdns_dbg_last_send_status=3U;return -1;}d+=qn;*(uint16_t*)d=htons(1);d+=2;*(uint16_t*)d=htons(1);d+=2;uint16_t dns_len=(uint16_t)(d-dns);
    udp->src_port=htons(53000);udp->dest_port=htons(53);udp->length=htons(8+dns_len);udp->checksum=0;ip->total_len=htons(20+8+dns_len);
    udp->checksum=arkm_xudp_checksum_ipv4(ip->src_ip, ip->dest_ip, 17U, udp, (uint16_t)(8U+dns_len)); if(udp->checksum==0) udp->checksum=0xFFFFU; ip->checksum=0; ip->checksum=arkm_x7_checksum_be(ip,20);
    arkm_xnet.dns_pending=1; arkm_xnet.dns_found=0; { uint32_t nn=0; while(name[nn] && nn+1U<sizeof(arkm_xnet.dns_name)){ arkm_xnet.dns_name[nn]=name[nn]; nn++; } arkm_xnet.dns_name[nn]=0; }
    arkm_xdns_dbg_last_send_status=0U;
    arkm_xdns_dbg_tx_submitted++;
    e1000_send_packet(pkt,(uint16_t)(14+20+8+dns_len)); return 0;
}

static int arkm_xdns_rx(ipv4_hdr_t* ip, udp_hdr_t* udp, uint8_t* payload, uint16_t len) {
    if(ntohs(udp->dest_port)!=53000U) return 0;
    arkm_xdns_dbg_udp_rx_53000++;
    /* Only a datagram from the configured resolver's DNS service is relevant. */
    if(ntohs(udp->src_port)!=53U || ip->src_ip!=arkm_xnet.dns_server) return 0;
    if(len<12U) { arkm_xdns_dbg_short_packets++; return 0; }
    arkm_xdns_dbg_last_rx_id=ntohs(*(uint16_t*)payload);
    if(arkm_xdns_dbg_last_rx_id!=arkm_xnet.dns_txid) return 0;
    arkm_xdns_dbg_rx_id_match++;
    uint16_t flags=ntohs(*(uint16_t*)(payload+2));
    uint16_t qd=ntohs(*(uint16_t*)(payload+4)),an=ntohs(*(uint16_t*)(payload+6));
    arkm_xdns_dbg_last_flags=flags;
    arkm_xdns_dbg_last_rcode=(uint8_t)(flags&0x0FU);
    arkm_xdns_dbg_last_answer_count=an;
    if(!(flags&0x8000U)) return 0; /* It is not a DNS response. */
    arkm_xdns_dbg_dns_responses++;
    if((flags&0x0200U)!=0U) { arkm_xdns_dbg_short_packets++; arkm_xnet.dns_pending=0; return 1; }
    if((flags&0x000FU)!=0U) { arkm_xnet.dns_pending=0; return 1; }
    if(qd==0U || an==0U) { arkm_xnet.dns_pending=0; return 1; }

    uint16_t off=12U;
    for(uint16_t q=0;q<qd;q++) {
        if(!arkm_xdns_skip_name(payload,len,&off) || (uint32_t)off+4U>len) {
            arkm_xdns_dbg_short_packets++; return 1;
        }
        /* skip_name advances past the terminating zero; QTYPE + QCLASS = 4 */
        off=(uint16_t)(off+4U);
    }
    for(uint16_t i=0;i<an;i++) {
        if(!arkm_xdns_skip_name(payload,len,&off) || (uint32_t)off+10U>len) {
            arkm_xdns_dbg_short_packets++; break;
        }
        uint16_t type=ntohs(*(uint16_t*)(payload+off));
        uint16_t cls=ntohs(*(uint16_t*)(payload+off+2U));
        uint16_t rdlen=ntohs(*(uint16_t*)(payload+off+8U));
        off=(uint16_t)(off+10U);
        if((uint32_t)off+rdlen>len) { arkm_xdns_dbg_short_packets++; break; }
        if(type==1U && cls==1U && rdlen==4U) {
            memcpy(arkm_xnet.dns_answer,payload+off,4U);
            arkm_xdns_dbg_a_answers++;
            arkm_xnet.dns_found=1;
            arkm_xnet.dns_pending=0;
            return 1;
        }
        off=(uint16_t)(off+rdlen);
    }
    /* A syntactically valid response was received, even if it had no A RR. */
    arkm_xnet.dns_pending=0;
    return 1;
}

int arkm_xnet_udp_hook(ipv4_hdr_t* ip, udp_hdr_t* udp, uint8_t* payload, uint16_t len) {
    arkm_xdns_dbg_udp_rx_seen++;
    arkm_xdns_dbg_last_src_ip=ip->src_ip;
    arkm_xdns_dbg_last_dst_ip=ip->dest_ip;
    arkm_xdns_dbg_last_src_port=ntohs(udp->src_port);
    arkm_xdns_dbg_last_dst_port=ntohs(udp->dest_port);
    if (arkm_x7_net_udp_hook(ip,udp,payload,len)) return 1;
    if(arkm_xdhcp_rx(ip,udp,payload,len)) return 1;
    if(arkm_xdns_rx(ip,udp,payload,len)) return 1;
    return 0;
}

static int arkm_xnet_ensure_dhcp(void);

static int arkm_xdns_query(const char* name) {
    if (!name || !name[0]) return 0;

    /* Do not issue DNS against boot-time fallback configuration while the
       asynchronous DHCP exchange is still in progress. */
    if (e1000_mmio_base && !arkm_xnet.dhcp_bound && !arkm_xnet_ensure_dhcp()) {
        arkm_xnet.dns_pending = 0;
        arkm_xnet.dns_found = 0;
        return 0;
    }

    /* One ID per logical lookup; retransmissions below deliberately retain
       this ID so a delayed reply can still satisfy the current transaction. */
    arkm_xnet.dns_txid = (uint16_t)(arkm_xnet.dns_txid + 1U);
    if (arkm_xnet.dns_txid == 0U) arkm_xnet.dns_txid = 1U;

    uint32_t response_count_before = arkm_xdns_dbg_dns_responses;
    uint32_t next_hop = arkm_xdns_next_hop();
    for (uint32_t attempt = 0; attempt < 3U; attempt++) {
        int rc = arkm_xdns_send(name);
        if (rc == -2) {
            /* ARP is asynchronous. Poll the NIC and explicitly wait for the
               selected next-hop mapping before attempting to submit DNS. */
            int have_mac = 0;
            for (uint32_t wait = 0; wait < 500000U; wait++) {
                e1000_poll_rx();
                uint64_t irq;
                arkm_lock_irqsave(&net_stack_lock, &irq);
                for (int i = 0; i < MAX_ARP_ENTRIES; i++) {
                    if (arp_table[i].valid && arp_table[i].ip == next_hop) {
                        have_mac = 1;
                        break;
                    }
                }
                arkm_unlock_irqrestore(&net_stack_lock, irq);
                if (have_mac) break;
                __asm__ volatile("pause");
            }
            if (!have_mac) continue;
            rc = arkm_xdns_send(name);
        }
        if (rc != 0) continue;

        /* Give slow user-mode DNS forwarding a bounded interval to respond;
           a quarter-million PAUSEs was too short on some host configurations. */
        for (uint32_t wait = 0; wait < 1000000U &&
             !arkm_xnet.dns_found && arkm_xnet.dns_pending; wait++) {
            e1000_poll_rx();
            __asm__ volatile("pause");
        }
        if (arkm_xnet.dns_found) return 1;

        /* A valid negative/truncated/no-A response is a real answer state,
           not a timeout. Do not hammer the resolver after receiving one. */
        if (arkm_xdns_dbg_dns_responses != response_count_before) break;
        arkm_xnet.dns_pending = 0;
    }

    arkm_xnet.dns_pending = 0;
    arkm_xnet.dns_found = 0;
    return 0;
}

static int arkm_xusb_free(void) {
    spin_lock(&arkm_x_usb_lock);
    /* Never return DMA-owned pages to the allocator until the controller is
     * confirmed halted.  This also handles a partially initialized host. */
    if(arkm_xusb.bar && arkm_xusb.cap_length) {
        volatile uint32_t* cmd=(volatile uint32_t*)((uint64_t)arkm_xusb.bar+arkm_xusb.op_base+ARKM_XHCI_USBCMD);
        volatile uint32_t* sts=(volatile uint32_t*)((uint64_t)arkm_xusb.bar+arkm_xusb.op_base+ARKM_XHCI_USBSTS);
        *cmd &= ~ARKM_XHCI_USBCMD_RS;
        uint32_t halted=0;
        for(uint32_t i=0;i<100000U;i++) {
            if(*sts & ARKM_XHCI_USBSTS_HCH) { halted=1U; break; }
            __asm__ volatile("pause");
        }
        if(!halted) { spin_unlock(&arkm_x_usb_lock); return 0; }
    }
    if(arkm_xusb.dcbaa) pmm_free_page(arkm_xusb.dcbaa);
    if(arkm_xusb.cmd_ring) pmm_free_page(arkm_xusb.cmd_ring);
    if(arkm_xusb.evt_ring) pmm_free_page(arkm_xusb.evt_ring);
    if(arkm_xusb.erst) pmm_free_page(arkm_xusb.erst);
    memset(&arkm_xusb,0,sizeof(arkm_xusb));
    spin_unlock(&arkm_x_usb_lock);
    return 1;
}

static int arkm_xusb_wait_reset(volatile uint32_t* usbsts) {
    for(uint32_t i=0;i<100000;i++){uint32_t s=*usbsts;if(!(s&ARKM_XHCI_USBSTS_CNR))return 1;__asm__ volatile("pause");}
    return 0;
}

static int arkm_xusb_init(uint8_t bus, uint8_t slot, uint8_t func, uint64_t bar0) {
    hw_xhci_ready = 0U;
    arkm_xusb_init_fail_stage = 0U;
    arkm_xusb_init_diag_bar = 0U; /* Filled after the physical BAR is mapped. */
    arkm_xusb_init_diag_cap = 0U;
    arkm_xusb_init_diag_hcs = 0U;
    arkm_xusb_init_diag_cmd = 0U;
    arkm_xusb_init_diag_sts = 0U;
    arkm_xusb_init_diag_cfg = 0U;
    if (!bar0) { arkm_xusb_init_fail_stage = 1U; return -1; }
    arkm_x_pci_enable_memory_only(bus, slot, func);
    uint64_t base = bar0 & ~0xFULL;
    uint64_t mmio_base = base;
    arkm_pci_ecam_diag_hex("[ARKM xHCI] physical BAR=", base);
    if (base >= 0x100000000ULL || !arkm_x_map_mmio_identity(base, ARKM_XHCI_MMIO_WINDOW_BYTES)) {
        mmio_base = arkm_x_map_mmio_alias(
            base, ARKM_XHCI_MMIO_WINDOW_BYTES, ARKM_XHCI_MMIO_VIRTUAL_BASE);
    }
    if (!mmio_base) {
        arkm_xusb_init_fail_stage = 2U;
        return -1;
    }
    arkm_xusb_init_diag_bar = (uint32_t)(mmio_base & 0xFFFFFFFFU);
    arkm_pci_ecam_diag_hex("[ARKM xHCI] virtual MMIO base=", mmio_base);
    volatile uint8_t *mmio = (volatile uint8_t *)(uintptr_t)mmio_base;
    uint8_t cap = *(volatile uint8_t *)(mmio + ARKM_XHCI_CAPLENGTH);
    uint32_t hcs = *(volatile uint32_t *)(mmio + ARKM_XHCI_HCSPARAMS1);
    uint32_t dbo = *(volatile uint32_t *)(mmio + ARKM_XHCI_DBOFF);
    uint32_t rto = *(volatile uint32_t *)(mmio + ARKM_XHCI_RTSOFF);
    arkm_xusb_init_diag_cap = cap;
    arkm_xusb_init_diag_hcs = hcs;
    if (cap < 0x20U || cap > 0x80U) {
        arkm_xusb_init_fail_stage = 3U;
        return -1;
    }
    memset(&arkm_xusb, 0, sizeof(arkm_xusb));
    arkm_xusb.bus = bus; arkm_xusb.slot = slot; arkm_xusb.func = func;
    arkm_xusb.bar = mmio_base; arkm_xusb.bar_phys = base;
    arkm_xusb.cap_length = cap; arkm_xusb.op_base = cap;
    arkm_xusb.db_base = dbo & ~0x3U; arkm_xusb.rt_base = rto & ~0x1FU;
    arkm_xusb.max_ports = (hcs >> 24) & 0xFFU;
    arkm_xusb.max_slots = hcs & 0xFFU;
    if (arkm_xusb.max_slots == 0U) arkm_xusb.max_slots = 1U;
    if (arkm_xusb.max_slots > 64U) arkm_xusb.max_slots = 64U;

    volatile uint32_t *cmd = (volatile uint32_t *)(mmio + arkm_xusb.op_base + ARKM_XHCI_USBCMD);
    volatile uint32_t *sts = (volatile uint32_t *)(mmio + arkm_xusb.op_base + ARKM_XHCI_USBSTS);
    *cmd &= ~ARKM_XHCI_USBCMD_RS;
    uint32_t halted = 0U;
    for (uint32_t i = 0U; i < 1000000U; ++i) {
        uint32_t sv = *sts;
        arkm_xusb_init_diag_cmd = *cmd;
        arkm_xusb_init_diag_sts = sv;
        if (sv & ARKM_XHCI_USBSTS_HCH) { halted = 1U; break; }
        __asm__ volatile("pause");
    }
    if (!halted) { arkm_xusb_init_fail_stage = 4U; return -1; }

    *cmd |= ARKM_XHCI_USBCMD_HCRST;
    uint32_t reset_cleared = 0U;
    for (uint32_t i = 0U; i < 1000000U; ++i) {
        if (!(*cmd & ARKM_XHCI_USBCMD_HCRST)) { reset_cleared = 1U; break; }
        __asm__ volatile("pause");
    }
    if (!reset_cleared) {
        arkm_xusb_init_fail_stage = 5U;
        arkm_xusb_init_diag_cmd = *cmd;
        arkm_xusb_init_diag_sts = *sts;
        return -1;
    }
    if (!arkm_xusb_wait_reset(sts)) {
        arkm_xusb_init_fail_stage = 6U;
        arkm_xusb_init_diag_cmd = *cmd;
        arkm_xusb_init_diag_sts = *sts;
        return -1;
    }

    arkm_xusb.dcbaa = pmm_alloc_page();
    arkm_xusb.cmd_ring = pmm_alloc_page();
    arkm_xusb.evt_ring = pmm_alloc_page();
    arkm_xusb.erst = pmm_alloc_page();
    if (!arkm_xusb.dcbaa || !arkm_xusb.cmd_ring || !arkm_xusb.evt_ring || !arkm_xusb.erst) {
        arkm_xusb_init_fail_stage = 7U;
        (void)arkm_xusb_free();
        return -1;
    }
    memset(arkm_xusb.dcbaa, 0, PAGE_SIZE);
    memset(arkm_xusb.cmd_ring, 0, PAGE_SIZE);
    memset(arkm_xusb.evt_ring, 0, PAGE_SIZE);
    memset(arkm_xusb.erst, 0, PAGE_SIZE);
    if (!arkm_iommu_prepare_dma(bus, slot, func, (uint64_t)arkm_xusb.dcbaa,
                                PAGE_SIZE, 3U, NULL) ||
        !arkm_iommu_prepare_dma(bus, slot, func, (uint64_t)arkm_xusb.cmd_ring,
                                PAGE_SIZE, 3U, NULL) ||
        !arkm_iommu_prepare_dma(bus, slot, func, (uint64_t)arkm_xusb.evt_ring,
                                PAGE_SIZE, 3U, NULL) ||
        !arkm_iommu_prepare_dma(bus, slot, func, (uint64_t)arkm_xusb.erst,
                                PAGE_SIZE, 3U, NULL)) {
        arkm_xusb_init_fail_stage = 71U;
        (void)arkm_xusb_free();
        return -1;
    }
    /* Do not grant bus mastering until every controller-owned ring is mapped. */
    arkm_x_pci_enable_mem_busmaster(bus, slot, func);
    {
        uint32_t *cr = (uint32_t *)arkm_xusb.cmd_ring;
        uint32_t ti = 255U * 4U;
        cr[ti + 0U] = (uint32_t)(uintptr_t)arkm_xusb.cmd_ring;
        cr[ti + 1U] = (uint32_t)((uint64_t)(uintptr_t)arkm_xusb.cmd_ring >> 32);
        cr[ti + 2U] = 0U;
        cr[ti + 3U] = (ARKM_XHCI_TRB_LINK << 10) | 1U | (1U << 1);
    }
    volatile uint32_t *dclo = (volatile uint32_t *)(mmio + arkm_xusb.op_base + 0x30U);
    volatile uint32_t *dchi = (volatile uint32_t *)(mmio + arkm_xusb.op_base + 0x34U);
    *dclo = (uint32_t)(arkm_xusb.dcbaa_phys = (uint64_t)(uintptr_t)arkm_xusb.dcbaa);
    *dchi = (uint32_t)(arkm_xusb.dcbaa_phys >> 32);
    volatile uint32_t *crlo = (volatile uint32_t *)(mmio + arkm_xusb.op_base + 0x18U);
    volatile uint32_t *crhi = (volatile uint32_t *)(mmio + arkm_xusb.op_base + 0x1CU);
    *crlo = (uint32_t)((uint64_t)(uintptr_t)arkm_xusb.cmd_ring | 1ULL);
    *crhi = (uint32_t)(((uint64_t)(uintptr_t)arkm_xusb.cmd_ring) >> 32);
    volatile uint32_t *cfg = (volatile uint32_t *)(mmio + arkm_xusb.op_base + ARKM_XHCI_CONFIG);
    uint32_t slots_enabled = (arkm_xusb.max_slots > 32U) ? 32U : arkm_xusb.max_slots;
    *cfg = slots_enabled;
    __asm__ volatile("mfence" ::: "memory");
    uint32_t cfg_readback = *cfg;
    arkm_xusb_init_diag_cfg = cfg_readback;
    if ((cfg_readback & 0xFFU) != slots_enabled) {
        arkm_xusb_init_fail_stage = 8U;
        arkm_xusb_init_diag_cmd = *cmd;
        arkm_xusb_init_diag_sts = *sts;
        (void)arkm_xusb_free();
        return -1;
    }

    arkm_xusb.running = 0U;
    arkm_xusb.ready = 0U;
    for (uint32_t p = 0U; p < arkm_xusb.max_ports; ++p) {
        volatile uint32_t *ps = (volatile uint32_t *)(mmio + arkm_xusb.op_base +
            ARKM_XHCI_PORT_BASE + p * ARKM_XHCI_PORT_STRIDE);
        if (*ps & ARKM_XHCI_PORT_CCS) arkm_xusb.connected_ports++;
    }
    arkm_xusb.hid_ready = 0U;
    arkm_xusb_init_diag_cmd = *cmd;
    arkm_xusb_init_diag_sts = *sts;
    return 0;
}

static void arkm_xusb_poll(void) {
    spin_lock(&arkm_x_usb_lock);
    if(!arkm_xusb.ready) { spin_unlock(&arkm_x_usb_lock); return; }
    volatile uint8_t* mmio=(volatile uint8_t*)(uint64_t)arkm_xusb.bar; arkm_xusb.connected_ports=0;
    for(uint32_t p=0;p<arkm_xusb.max_ports;p++){volatile uint32_t* ps=(volatile uint32_t*)(mmio+arkm_xusb.op_base+ARKM_XHCI_PORT_BASE+p*ARKM_XHCI_PORT_STRIDE);uint32_t v=*ps;if(v&ARKM_XHCI_PORT_CCS)arkm_xusb.connected_ports++;}
    spin_unlock(&arkm_x_usb_lock);
}

static void arkm_xusb_hid_keyboard(const uint8_t* report,uint32_t len) {
    if(!report || len<8) return;
    uint8_t mods=report[0]; (void)mods;
    for(uint32_t i=2;i<8&&i<len;i++) if(report[i]) { arkm_x_hid_key_events++; }
}

static void arkm_xusb_hid_mouse(const uint8_t* report,uint32_t len) {
    if(!report || len<3) return;
    int8_t dx=(int8_t)report[1], dy=(int8_t)report[2];
    sys_mouse.x += dx; sys_mouse.y += dy; if(sys_mouse.x<0)sys_mouse.x=0;if(sys_mouse.y<0)sys_mouse.y=0;if(sys_mouse.x>=(int)screen_width)sys_mouse.x=(int)screen_width-1;if(sys_mouse.y>=(int)screen_height)sys_mouse.y=(int)screen_height-1; arkm_x_hid_mouse_events++;
}

static int arkm_rm_smp_admission_selftest(void) {
    if (get_core_id() != bsp_apic_id) return -1;
    uint32_t pid = arkm6_current_pid_fast();
    uint32_t generation = pid ? arkm_rm_generation_for_pid(pid) : 0U;
    if (!pid || !generation) return -1;
    uint64_t online = __atomic_load_n(&smp_online_mask, __ATOMIC_ACQUIRE);
    int bsp_slot_i = smp_tss_slot_for_apic_id(bsp_apic_id);
    if (bsp_slot_i < 0 || bsp_slot_i >= 32) return -1;
    uint32_t expected = 0U;
    for (uint32_t slot = 0U; slot < 32U; ++slot)
        if (slot != (uint32_t)bsp_slot_i && (online & (1ULL << slot)))
            expected |= (1U << slot);
    if (!expected) return 1;
    __atomic_store_n(&arkm_rm_stress_pid, pid, __ATOMIC_RELAXED);
    __atomic_store_n(&arkm_rm_stress_generation, generation, __ATOMIC_RELAXED);
    __atomic_store_n(&arkm_rm_stress_ack_mask, 0U, __ATOMIC_RELEASE);
    for (uint32_t slot = 0U; slot < 32U; ++slot) {
        __atomic_store_n(&arkm_rm_stress_ops[slot], 0U, __ATOMIC_RELAXED);
        __atomic_store_n(&arkm_rm_stress_failures[slot], 0U, __ATOMIC_RELAXED);
    }
    uint32_t request = __atomic_add_fetch(&arkm_rm_stress_request, 1U, __ATOMIC_ACQ_REL);
    if (request == 0U)
        request = __atomic_add_fetch(&arkm_rm_stress_request, 1U, __ATOMIC_ACQ_REL);
    for (uint32_t slot = 0U; slot < 32U; ++slot)
        if (expected & (1U << slot)) apic_send_wakeup(local_apic_ids[slot]);

    uint32_t bsp_ops = 0U, failures = 0U;
    for (uint32_t n = 0U; n < 16U; ++n) {
        if (arkm_rm_reserve_identity(pid, generation, ARKM_RM_MEMORY, 1U)) {
            arkm_rm_commit_identity(pid, generation, ARKM_RM_MEMORY, 1U);
            arkm_rm_release_identity(pid, generation, ARKM_RM_MEMORY, 1U);
            bsp_ops++;
        } else failures++;
    }
    uint32_t spins = 0U;
    while ((__atomic_load_n(&arkm_rm_stress_ack_mask, __ATOMIC_ACQUIRE) & expected) != expected &&
           ++spins < 2000000U) __asm__ volatile("pause" ::: "memory");
    __atomic_store_n(&arkm_rm_stress_request, 0U, __ATOMIC_RELEASE);
    uint32_t ack = __atomic_load_n(&arkm_rm_stress_ack_mask, __ATOMIC_ACQUIRE);
    uint32_t operations = bsp_ops;
    for (uint32_t slot = 0U; slot < 32U; ++slot) {
        if ((expected & (1U << slot)) == 0U) continue;
        operations += __atomic_load_n(&arkm_rm_stress_ops[slot], __ATOMIC_RELAXED);
        failures += __atomic_load_n(&arkm_rm_stress_failures[slot], __ATOMIC_RELAXED);
    }
    arkm6_audit_record(ARKM6_EVT_PROCESS, 0x10F5U,
                       ((uint64_t)ack << 32) | expected,
                       ((uint64_t)operations << 32) | failures);
    return (ack & expected) == expected && failures == 0U &&
           operations == 16U + 8U * (uint32_t)__builtin_popcount(expected);
}

static int arkm_xselftest_mem(void) {
    void* p=pmm_alloc_page(); if(!p)return 0; uint8_t* b=(uint8_t*)p; for(uint32_t i=0;i<PAGE_SIZE;i++)b[i]=(uint8_t)(i^0x5A); int slot=arkm_xdma_map((uint64_t)p,PAGE_SIZE,0x3,0x100); if(slot<0){pmm_free_page(p);return 0;} uint32_t test_pid=arkm6_current_pid_fast(); uint32_t test_generation=arkm_rm_generation_for_pid(test_pid); if(!arkm_xdma_begin_transfer(slot,test_pid,test_generation)){(void)arkm_xdma_unmap(slot);pmm_free_page(p);return 0;} if(arkm_xdma_unmap_identity(slot,test_pid,test_generation)!=-2){(void)arkm_xdma_end_transfer(slot,test_pid,test_generation);pmm_free_page(p);return 0;} if(!arkm_xdma_end_transfer(slot,test_pid,test_generation)){pmm_free_page(p);return 0;} int stress_result=arkm_rm_smp_admission_selftest(); if(stress_result==0){pmm_free_page(p);return 0;} return b[0]==0x5A && b[255]==(uint8_t)(255^0x5A) ? (pmm_free_page(p),1): (pmm_free_page(p),0);
}

static int arkm_xselftest_huge(void) {
    uint64_t va=0x68000000ULL;
    uint64_t r=arkm_xhuge_map(va,0x3,0);
    if(r==(uint64_t)-1)return 0;
    uint64_t pi=(va>>39)&0x1FFULL,di=(va>>30)&0x1FFULL,ti=(va>>21)&0x1FFULL;
    uint64_t* pml4=(uint64_t*)app_context.cr3;
    int ok=(pml4 && (pml4[pi]&1ULL));
    if(ok){uint64_t* pdp=(uint64_t*)(pml4[pi]&~0xFFFULL);
        ok=(pdp[di]&1ULL);
        if(ok){uint64_t* pd=(uint64_t*)(pdp[di]&~0xFFFULL);
            ok=((pd[ti]&ARKM_XVM_PRESENT)!=0) && ((pd[ti]&ARKM_XVM_PS)!=0) && ((pd[ti]&0x001FE000ULL)==0ULL);
        }
    }
    ok &= arkm_xhuge_unmap(va)==0;
    return ok;
}

static int arkm_xselftest_vm(void) {
    void* a=(void*)arkm_xvm_map(0,8192,0x3,0);
    if(!a || a==(void*)-1) return 0;
    uint64_t base=(uint64_t)a, cr3=app_context.cr3;
    uint64_t* p0=NULL;
    int ok=arkm_xvm_walk((uint64_t*)cr3,base,&p0);
    if(ok && p0 && (*p0&ARKM_XVM_PRESENT)){
        uint8_t* phys=(uint8_t*)(*p0&0x000FFFFFFFFFF000ULL);
        phys[0]=0x12; phys[PAGE_SIZE-1]=0x34;
        ok=(phys[0]==0x12 && phys[PAGE_SIZE-1]==0x34);
    }
    ok &= arkm_xvm_protect(base,8192,1)==0;
    if(ok && arkm_xvm_walk((uint64_t*)cr3,base,&p0)) ok &= ((*p0&ARKM_XVM_WRITE)==0);
    ok &= arkm_xvm_unmap(base,8192)==0;
    return ok;
}

static void arkm_x8_swap_diag_clear_io(void) {
    arkm_x8_swap_diag_io_stage=0U;
    arkm_x8_swap_diag_lba=0U;
    arkm_x8_swap_diag_polls=0U;
    arkm_x8_swap_diag_op=0U;
    arkm_x8_swap_diag_cmd=0U;
    arkm_x8_swap_diag_status=0U;
    arkm_x8_swap_diag_wait_error=0U;
}

/* Swap/reclaim shell self-tests need a disposable address space. The public
 * arkm_xvm_map() API is intentionally capability-gated and records allocations
 * against a running process; calling it from the kernel shell can fail before
 * any storage I/O. Mapping the test page into user_pml4 directly would be worse:
 * that root shares the kernel identity map. This private root copies the low
 * identity map into its own PD so the self-test can safely split one 2-MiB leaf. */
typedef struct {
    uint64_t* root;
    uint64_t* pdp0;
    uint64_t* pd0;
    uint64_t va;
    uint64_t original_pde;
    uint32_t pd_index;
    uint8_t mapped;
} arkm_x8_swap_test_page_t;

static int arkm_x8_swap_test_page_create(arkm_x8_swap_test_page_t* t) {
    arkm_x8_swap_diag_page_create_stage=0U;
    if (!t) { arkm_x8_swap_diag_page_create_stage=1U; return 0; }
    memset(t,0,sizeof(*t));

    /* Separate each allocation failure so stage 2 is no longer ambiguous. */
    t->root=(uint64_t*)pmm_alloc_page();
    if (!t->root) { arkm_x8_swap_diag_page_create_stage=2U; goto fail; }
    t->pdp0=(uint64_t*)pmm_alloc_page();
    if (!t->pdp0) { arkm_x8_swap_diag_page_create_stage=3U; goto fail; }
    t->pd0=(uint64_t*)pmm_alloc_page();
    if (!t->pd0) { arkm_x8_swap_diag_page_create_stage=4U; goto fail; }

    memcpy(t->root,user_pml4,PAGE_SIZE);
    memcpy(t->pdp0,p3_table,PAGE_SIZE);
    for(uint32_t i=0;i<512U;i++) t->pd0[i]=p2_table[i]&~(1ULL<<2);
    t->pdp0[0]=(uint64_t)t->pd0|0x07ULL;
    t->root[0]=(uint64_t)t->pdp0|0x07ULL;
    arkm_x8_swap_diag_page_create_stage=6U;

    /* Select a supervisor-only 2-MiB identity leaf in the private low map. */
    for(uint64_t va=0x20000000ULL;va<0x40000000ULL;va+=0x200000ULL) {
        uint32_t pi=(uint32_t)((va>>21)&0x1FFULL);
        uint64_t pde=t->pd0[pi];
        if((pde&(ARKM_XVM_PRESENT|ARKM_XVM_PS))!=(ARKM_XVM_PRESENT|ARKM_XVM_PS)) continue;
        t->va=va;
        t->pd_index=pi;
        t->original_pde=pde;
        arkm_x8_swap_diag_page_create_stage=7U;
        void* page=pmm_alloc_page();
        if(!page) { arkm_x8_swap_diag_page_create_stage=8U; goto fail; }
        memset(page,0,PAGE_SIZE);
        uint64_t flags=ARKM_XVM_PRESENT|ARKM_XVM_USER|ARKM_XVM_WRITE;
        if(aegis_nxe_enabled) flags|=ARKM_XVM_NX;
        if(!app_vmm_map_user_page(t->root,va,(uint64_t)page,flags)) {
            pmm_free_page(page);
            arkm_x8_swap_diag_page_create_stage=9U;
            goto fail;
        }
        t->mapped=1U;
        uint64_t* pte=NULL;
        if(!arkm_xvm_walk(t->root,va,&pte)||!pte||!(*pte&ARKM_XVM_PRESENT)) {
            arkm_x8_swap_diag_page_create_stage=10U;
            goto fail;
        }
        arkm_x8_swap_diag_page_create_stage=11U;
        return 1;
    }
    /* No suitable inherited 2-MiB identity leaf exists in the selected range. */
    arkm_x8_swap_diag_page_create_stage=12U;
fail:
    /* Release the mapped test page too if validation failed after mapping. */
    if(t->mapped && t->root) {
        uint64_t* pte=NULL;
        if(arkm_xvm_walk(t->root,t->va,&pte) && pte) {
            uint64_t entry=*pte;
            *pte=0U;
            if((entry&ARKM_X_SWAP_MARK) && !(entry&ARKM_XVM_PRESENT)) {
                uint64_t enc=(entry>>ARKM_X_SWAP_SLOT_SHIFT)&0xFFFFFU;
                if(enc>0U && enc-1U<ARKM_X_SWAP_SLOTS)
                    arkm_x_swap_entries[(uint32_t)(enc-1U)].active=0U;
            } else if(entry&ARKM_XVM_PRESENT) {
                pmm_free_page((void*)(entry&0x000FFFFFFFFFF000ULL));
            }
        }
    }
    /* Release a partially built private page-directory split. */
    if(t->pd0 && t->va) {
        uint64_t cur=t->pd0[t->pd_index];
        if(cur!=t->original_pde && (cur&ARKM_XVM_PRESENT) && !(cur&ARKM_XVM_PS)) {
            t->pd0[t->pd_index]=t->original_pde;
            pmm_free_page((void*)(cur&~0xFFFULL));
        }
    }
    if(t->pd0) pmm_free_page(t->pd0);
    if(t->pdp0) pmm_free_page(t->pdp0);
    if(t->root) pmm_free_page(t->root);
    memset(t,0,sizeof(*t));
    return 0;
}

static void arkm_x8_swap_test_page_destroy(arkm_x8_swap_test_page_t* t) {
    if(!t) return;
    if(t->root && t->mapped) {
        uint64_t* pte=NULL;
        if(arkm_xvm_walk(t->root,t->va,&pte) && pte) {
            uint64_t entry=*pte;
            *pte=0U;
            if((entry&ARKM_X_SWAP_MARK) && !(entry&ARKM_XVM_PRESENT)) {
                uint64_t enc=(entry>>ARKM_X_SWAP_SLOT_SHIFT)&0xFFFFFU;
                if(enc>0U && enc-1U<ARKM_X_SWAP_SLOTS) {
                    uint32_t slot=(uint32_t)(enc-1U);
                    if(arkm_x_swap_entries[slot].cr3==(uint64_t)t->root &&
                       arkm_x_swap_entries[slot].virt==t->va)
                        arkm_x_swap_entries[slot].active=0U;
                }
            } else if(entry&ARKM_XVM_PRESENT) {
                pmm_free_page((void*)(entry&0x000FFFFFFFFFF000ULL));
            }
        }
    }
    if(t->pd0 && t->va) {
        uint64_t cur=t->pd0[t->pd_index];
        t->pd0[t->pd_index]=t->original_pde;
        if(cur!=t->original_pde && (cur&ARKM_XVM_PRESENT) && !(cur&ARKM_XVM_PS))
            pmm_free_page((void*)(cur&~0xFFFULL));
    }
    if(t->pd0) pmm_free_page(t->pd0);
    if(t->pdp0) pmm_free_page(t->pdp0);
    if(t->root) pmm_free_page(t->root);
    memset(t,0,sizeof(*t));
}

static int arkm_xselftest_swap(void) {
    arkm_x8_swap_diag_test_stage=0U;
    arkm_x8_swap_diag_clear_io();
    if(arkm_x8_swap_backend==ARKM_X8_SWAP_BACKEND_NONE) { arkm_x8_swap_diag_test_stage=1U; return -1; }
    arkm_x8_swap_test_page_t test_page;
    if(!arkm_x8_swap_test_page_create(&test_page)) { arkm_x8_swap_diag_test_stage=2U; return 0; }
    uint64_t v=test_page.va, cr3=(uint64_t)test_page.root;
    uint64_t* pte=NULL;
    int ok=arkm_xvm_walk((uint64_t*)cr3,v,&pte) && pte && (*pte&ARKM_XVM_PRESENT);
    if(!ok) { arkm_x8_swap_diag_test_stage=3U; arkm_x8_swap_test_page_destroy(&test_page); return 0; }
    uint8_t* phys=(uint8_t*)(*pte&0x000FFFFFFFFFF000ULL);
    phys[0]=0xA7; phys[PAGE_SIZE-1]=0x5C;
    arkm_x8_swap_diag_test_stage=4U;
    int slot=arkm_xswap_out(cr3,v,0x3);
    int swapped=(slot>=0);
    ok=swapped;
    arkm_x8_swap_diag_test_stage=swapped?5U:6U;
    if(ok) {
        ok=((*pte&ARKM_X_SWAP_MARK)!=0 && (*pte&ARKM_XVM_PRESENT)==0);
        arkm_x8_swap_diag_test_stage=ok?7U:8U;
    }
    int restored_ok=0;
    if(ok) {
        int in_rc=arkm_xswap_in(cr3,v);
        restored_ok=(in_rc>0);
        ok=restored_ok;
        arkm_x8_swap_diag_test_stage=ok?9U:10U;
    }
    if(ok) {
        ok=arkm_xvm_walk((uint64_t*)cr3,v,&pte) && pte && (*pte&ARKM_XVM_PRESENT);
        if(ok) {
            uint8_t* restored=(uint8_t*)(*pte&0x000FFFFFFFFFF000ULL);
            ok=(restored[0]==0xA7 && restored[PAGE_SIZE-1]==0x5C);
        }
        arkm_x8_swap_diag_test_stage=ok?11U:12U;
    }
    arkm_x8_swap_test_page_destroy(&test_page);
    return ok;
}

static int arkm_xselftest_cow(void) {
    if(!app_context.cr3) return 0;
    void* a=pmm_alloc_page();
    if(!a) return 0;
    memset(a,0x3C,PAGE_SIZE);
    uint64_t va=0x62000000ULL, old_phys=(uint64_t)a;
    int ok=app_vmm_map_user_page((uint64_t*)app_context.cr3,va,old_phys,ARKM_XVM_PRESENT|ARKM_XVM_USER);
    uint64_t* pte=NULL;
    if(ok) ok=arkm_xvm_walk((uint64_t*)app_context.cr3,va,&pte);
    if(ok){
        *pte &= ~ARKM_XVM_WRITE;
        ok=arkm_x_cow_register(app_context.cr3,va,old_phys);
    }
    if(ok) ok=arkm_x_cow_fault(app_context.cr3,va);
    if(ok && arkm_xvm_walk((uint64_t*)app_context.cr3,va,&pte)){
        uint64_t new_phys=*pte&0x000FFFFFFFFFF000ULL;
        ok=(new_phys!=old_phys) && ((uint8_t*)new_phys)[0]==0x3C;
    } else ok=0;
    arkm_xvm_unmap(va,PAGE_SIZE);
    pmm_free_page((void*)old_phys);
    return ok;
}

static int arkm_xselftest_driver(void) {
    int id=advanced_register_driver("arkm-x-selftest",0,31,7,0xFFFF,0x0001,0,1);if(id<0)return 0;advanced_hotplug_push(1,0,31,7,0);advanced_driver_heartbeat((uint32_t)id);int n=arkm_xdriver_hotplug_poll();return n>0;
}

static int arkm_xselftest_ns(void) {int id=arkm_xns_create("test-box",amp_foundation.schedulable_mask,1024,1);return id>1;}

static int arkm_xselftest_net(void) {
    if(!e1000_mmio_base) return -1;
    arkm_xdhcp_send_discover();
    return 1;
}

static int arkm_xselftest_power(void) { return arkm_xpower.present ? (arkm_xpower_suspend(ARKM_XPOWER_SOFT_SUSPEND)==0 && arkm_xpower_suspend(ARKM_XPOWER_SOFT_RESUME)==0) : -1; }
static int arkm_xselftest_virt(void) { return (arkm_xvirt.vmx || arkm_xvirt.svm) ? 1 : -1; }
static int arkm_xselftest_usb(void) {
    if (!arkm_xusb.ready) return -1;
    uint8_t keyboard_report[8]={0};
    uint8_t mouse_report[3]={0};
    arkm_xusb_hid_keyboard(keyboard_report,sizeof(keyboard_report));
    arkm_xusb_hid_mouse(mouse_report,sizeof(mouse_report));
    return 1;
}
static int arkm_xselftest_audio(void) { return arkm_xaudio.ready ? 1 : -1; }

static arkm_x_test_result_t arkm_xselftest_all(void) {
    arkm_x_test_result_t r={0}; int v;
    int (*tests[])(void)={arkm_xselftest_mem,arkm_xselftest_vm,arkm_xselftest_cow,arkm_xselftest_huge,arkm_xselftest_swap,arkm_xselftest_driver,arkm_xselftest_ns,arkm_xselftest_net,arkm_xselftest_usb,arkm_xselftest_audio,arkm_xselftest_power,arkm_xselftest_virt};
    r.total=(uint32_t)(sizeof(tests)/sizeof(tests[0]));
    for(uint32_t i=0;i<r.total;i++){v=tests[i]();if(v<0)r.skipped++;else if(v)r.passed++;else r.failed++;}
    return r;
}

static void arkm_x_report(void) {
    arkm6_luna_shell_line("ARKM MEMORY TOPOLOGY: ",arkm_x_memnode_count?"ONLINE":"OFFLINE");
    arkm_x_write_dec_line("ARKM TOPOLOGY NODES: ",arkm_x_memnode_count);
    arkm_x_write_dec_line("ARKM HUGE AREAS: ",ARKM_X_HUGE_AREAS);
    arkm_x_write_dec_line("ARKM SWAP SLOTS: ",ARKM_X_SWAP_SLOTS);
    arkm6_luna_shell_line("ARKM USB HOST: ",arkm_xusb.ready?"READY":"OFFLINE");
    arkm6_luna_shell_line("ARKM AUDIO: ",arkm_x7_audio_status_name());
    arkm6_luna_shell_line("ARKM IPv6: ",arkm_xnet.enabled?"READY":"OFFLINE");
    arkm6_luna_shell_line("ARKM DHCP: ",arkm_xnet.dhcp_bound?"BOUND":"DISCOVERABLE");
    arkm6_luna_shell_line("ARKM DNS: ",arkm_xnet.dns_ready?"READY":"STAGED");
    arkm6_luna_shell_line("ARKM VIRT: ",arkm_xvirt_status_name());
    arkm6_luna_shell_line("ARKM POWER: ",arkm_xpower.present?"ACPI READY":"NO FADT");
    arkm_x_write_dec_line("ARKM HID KEY EVENTS: ",arkm_x_hid_key_events);
    arkm_x_write_dec_line("ARKM HID MOUSE EVENTS: ",arkm_x_hid_mouse_events);
}

static void arkm_x_init(void) {
    if(arkm_x_initialized)return;
    arkm_x_mem_init();
    arkm_xns_init();
    arkm_xnet6_init();
    arkm_xvirt_probe();
    arkm_xpower_probe();
    /* Identify the first usable USB host and audio controller without
     * touching unrelated PCI devices. */
    for(uint16_t bus=0;bus<256U&&!arkm_xusb.ready;bus++)for(uint16_t slot=0;slot<32U&&!arkm_xusb.ready;slot++){
        uint16_t vendor=pci_config_read_word((uint8_t)bus,(uint8_t)slot,0,0x00);if(vendor==0xFFFFU)continue;
        for(uint16_t func=0;func<8U&&!arkm_xusb.ready;func++){
            uint16_t v=pci_config_read_word((uint8_t)bus,(uint8_t)slot,(uint8_t)func,0x00);if(v==0xFFFFU)continue;
            uint32_t cr=pci_config_read_dword((uint8_t)bus,(uint8_t)slot,(uint8_t)func,0x08);uint8_t cc=(uint8_t)(cr>>24),sc=(uint8_t)(cr>>16),pi=(uint8_t)(cr>>8);uint64_t bar=arkm_x_pci_bar64((uint8_t)bus,(uint8_t)slot,(uint8_t)func);
            /* Part-1 USB/HDA are owned by ARKM-X7 below. Keep the generic
             * discovery pass read-only so two independent controller
             * initializers cannot reset the same QEMU device. */
            (void)cc; (void)sc; (void)pi; (void)bar;
        }
    }
    arkm6_swap_ready = (arkm_x8_swap_backend != ARKM_X8_SWAP_BACKEND_NONE) ? 1U:0U;
    arkm6_power_acpi_ready = arkm_xpower.present ? 1U:0U;
    arkm_x_initialized=1;
    arkm6_event_push(ARKM6_EVT_GENERIC,0x58524D49U,((uint64_t)arkm_xusb.ready<<32)|arkm_xaudio.ready);
}

static void arkm_x_tick(void) {
    if(!arkm_x_initialized || timer_ticks==arkm_x_tick_stamp) return;
    arkm_x_tick_stamp=timer_ticks;
    if((timer_ticks&0x3FU)==0)arkm_xdriver_hotplug_poll();
    if((timer_ticks&0x7FU)==0){arkm_x_mem_refresh();arkm_xusb_poll();}
}

static int arkm_x_shell_command(const char* command) {
    if(!command)return 0;
    if(!strcmp(command,"ARKM-X STATUS")||!strcmp(command,"ARKM X STATUS")){arkm_x_report();return 1;}
    if(!strcmp(command,"ARKM-X SELFTEST")||!strcmp(command,"ARKM X SELFTEST")){
        arkm_x_test_result_t r=arkm_xselftest_all();arkm_x_write_dec_line("TESTS: ",r.total);arkm_x_write_dec_line("PASSED: ",r.passed);arkm_x_write_dec_line("FAILED: ",r.failed);arkm_x_write_dec_line("SKIPPED: ",r.skipped);arkm6_luna_shell_line("RESULT: ",r.failed?"FAIL":"PASS");return 1;
    }
    if(!strcmp(command,"ARKM-X SWAP")||!strcmp(command,"ARKM X SWAP")){
        int rc=arkm_xswap_reclaim_one();
        if(rc>0) arkm6_luna_shell_line("SWAP: ","ONE PAGE RECLAIMED");
        else if(rc==0) arkm6_luna_shell_line("SWAP: ","NO PAGE RECLAIMED");
        else arkm6_luna_shell_line("SWAP: ","STORAGE UNAVAILABLE");
        return 1;
    }
    if(!strcmp(command,"ARKM-X USB")||!strcmp(command,"ARKM X USB")){arkm_x_write_dec_line("HOST CONTROLLERS: ",arkm_xusb.ready?1U:0U);arkm_x_write_dec_line("ROOT PORTS: ",arkm_xusb.max_ports);arkm_x_write_dec_line("CONNECTED PORTS: ",arkm_xusb.connected_ports);arkm6_luna_shell_line("HID REPORT PATH: ",arkm_xusb.hid_ready?"ACTIVE":"READY FOR ENUMERATION");return 1;}
    if(!strcmp(command,"ARKM-X AUDIO")||!strcmp(command,"ARKM X AUDIO")){arkm6_luna_shell_line("CONTROLLER: ",arkm_xaudio.ready?"READY":"OFFLINE");arkm_x_write_hex_line("CODEC MASK: ",arkm_xaudio.codec_mask);arkm6_luna_shell_line("PCM BUFFER: ",arkm_xaudio.stream_ready?"ALLOCATED":"UNAVAILABLE");return 1;}
    if(!strcmp(command,"ARKM-X NET")||!strcmp(command,"ARKM X NET")){arkm6_luna_shell_line("IPv6: ",arkm_xnet.enabled?"READY":"OFFLINE");arkm6_luna_shell_line("DHCP: ",arkm_xnet.dhcp_bound?"BOUND":"NOT BOUND");arkm6_luna_shell_line("DNS: ",arkm_xnet.dns_ready?"READY":"STAGED");return 1;}
    if(!strcmp(command,"ARKM-X DHCP")||!strcmp(command,"ARKM X DHCP")){arkm_xdhcp_send_discover();arkm6_luna_shell_line("DHCP: ","DISCOVER SENT");return 1;}
    if(arkm6_prefix(command,"ARKM-X DNS ")||arkm6_prefix(command,"ARKM X DNS ")){const char* n=command+11;int rc=arkm_xdns_send(n);if(rc==0)arkm6_luna_shell_line("DNS: ","QUERY SENT");else if(rc==-2)arkm6_luna_shell_line("DNS: ","ARP NEEDED; RETRY");else arkm6_luna_shell_line("DNS: ","QUERY FAILED");return 1;}
    if(!strcmp(command,"ARKM-X POWER")||!strcmp(command,"ARKM X POWER")){arkm6_luna_shell_line("ACPI FADT: ",arkm_xpower.present?"PRESENT":"MISSING");arkm6_luna_shell_line("SOFT SUSPEND: ",arkm_xpower.soft_suspended?"ACTIVE":"READY");return 1;}
    if(!strcmp(command,"ARKM-X SUSPEND")||!strcmp(command,"ARKM X SUSPEND")){int rc=arkm_xpower_suspend(ARKM_XPOWER_SOFT_SUSPEND);arkm6_luna_shell_line("SUSPEND: ",rc==0?"READY":"UNAVAILABLE");return 1;}
    if(!strcmp(command,"ARKM-X RESUME")||!strcmp(command,"ARKM X RESUME")){int rc=arkm_xpower_suspend(ARKM_XPOWER_SOFT_RESUME);arkm6_luna_shell_line("RESUME: ",rc==0?"READY":"UNAVAILABLE");return 1;}
    if(!strcmp(command,"ARKM-X VIRT")||!strcmp(command,"ARKM X VIRT")){arkm6_luna_shell_line("VMX: ",arkm_xvirt.vmx?"SUPPORTED":"NO");arkm6_luna_shell_line("SVM: ",arkm_xvirt.svm?"SUPPORTED":"NO");arkm6_luna_shell_line("HYPERVISOR: ",arkm_xvirt.hypervisor?"PRESENT":"NOT DETECTED");arkm6_luna_shell_line("VIRT STATUS: ",arkm_xvirt_status_name());arkm6_luna_shell_line("CONTROL PAGE: ",arkm_xvirt.staged?(arkm_xvirt.vmx?"VMXON STAGED":"SVM VMCB STAGED"):"NONE");return 1;}
    if(!strcmp(command,"ARKM-X NAMESPACE")||!strcmp(command,"ARKM X NAMESPACE")){int id=arkm_xns_create("shell-box",amp_foundation.schedulable_mask,1024,1);if(id>0){arkm_x_write_dec_line("NAMESPACE: ",(uint32_t)id);arkm6_luna_shell_line("CONTAINER PRIMITIVE: ","READY");}else arkm6_luna_shell_line("NAMESPACE: ","FAILED");return 1;}
    if(!strcmp(command,"ARKM-X MEMORY")||!strcmp(command,"ARKM X MEMORY")){arkm_x_mem_refresh();arkm_x_write_dec_line("NODES: ",arkm_x_memnode_count);for(uint32_t i=0;i<arkm_x_memnode_count;i++){arkm_x_write_dec_line("FREE PAGES: ",(uint32_t)(arkm_x_memnodes[i].free_pages>0xFFFFFFFFULL?0xFFFFFFFFU:arkm_x_memnodes[i].free_pages));}return 1;}
    return 0;
}



/* Public bridge names keep the rest of the kernel insulated from ARKM-X internals. */
void arkm_x_completion_init(void) {
    /* Dependency: the allocator, VMM, security policy, SMP/AMP topology, and
     * scheduler must exist before X7 can attach VM/device state to them. */
    if (!arkm_init_has(ARKM_INIT_PMM | ARKM_INIT_VMM | ARKM_INIT_SECURITY | ARKM_INIT_SCHED)) {
        arkm_init_fail(ARKM_INIT_X7);
        return;
    }
    /* Bring up the legacy services first; X7 consumes their storage/network state. */
    if (!arkm_x_initialized) arkm_x_init();
    arkm_x7_init();
    if (arkm_x7_ready) arkm_init_mark(ARKM_INIT_X7);
    else arkm_init_fail(ARKM_INIT_X7);
    if (e1000_mmio_base) arkm_x7_dhcp_start();
}
void arkm_x_completion_tick(void) {
    arkm_x_completion_init();
    if (!arkm_init_has(ARKM_INIT_X7)) return;
    arkm_x_tick();
    arkm_x7_tick();
}
int arkm_x_completion_shell(const char* command) {
    arkm_x_completion_init();
    if(arkm_x7_shell(command)) return 1;
    return arkm_x_shell_command(command);
}
int arkm_x_completion_cow_fault(uint64_t cr3, uint64_t fault_addr) {
    return arkm_x_cow_fault(cr3, fault_addr);
}
int arkm_x_completion_swap_fault(uint64_t cr3, uint64_t fault_addr) {
    return arkm_xswap_fault(cr3, fault_addr);
}
uint64_t arkm_x_completion_vm_map(uint64_t addr, uint64_t length, uint32_t prot, uint32_t flags) { return arkm_xvm_map(addr, length, prot, flags); }
int arkm_x_completion_vm_unmap(uint64_t addr, uint64_t length) { return arkm_xvm_unmap(addr, length); }
int arkm_x_completion_vm_protect(uint64_t addr, uint64_t length, uint32_t prot) { return arkm_xvm_protect(addr, length, prot); }
static void arkm_x7_write_dec_line(const char* label,uint32_t value);
/* ========================================================================
 * ARKM-X7 HARDWARE / MEMORY COMPLETION
 * ------------------------------------------------------------------------
 * This layer completes the seven deliberately deferred areas without
 * replacing ARKM's established LAPIC, SMP, scheduler, VMM, compositor, or
 * E1000 paths.  Hardware-heavy paths are explicitly testable from the shell
 * and are not executed from the timer interrupt.
 * ======================================================================== */

#define ARKM_X7_COW_MAX              512U
#define ARKM_X7_NS_BIND_MAX          64U
#define ARKM_X7_USB_TRBS             256U
#define ARKM_X7_USB_BUFSIZE          PAGE_SIZE
#define ARKM_X7_HDA_PAGES            4U
#define ARKM_X7_HDA_CBL              (ARKM_X7_HDA_PAGES * PAGE_SIZE)
#define ARKM_X7_HDA_TAG              1U
#define ARKM_X7_VM_GUEST_CODE_SIZE   PAGE_SIZE
#define ARKM_X7_VM_GUEST_STACK_SIZE  PAGE_SIZE
#define ARKM_X7_DNS_RETRY_TICKS      512U
#define ARKM_X7_DHCP_RETRY_TICKS     256U
#define ARKM_X7_RECLAIM_AGE          2048U
#define ARKM_X7_PTE_ACCESSED         (1ULL << 5)
#define ARKM_X7_PTE_DIRTY            (1ULL << 6)
#define ARKM_X7_VMCS_REVISION        0x00000000U
#define ARKM_X7_MSR_FEATURE_CONTROL  0x0000003AU
#define ARKM_X7_MSR_VMX_BASIC        0x00000480U
#define ARKM_X7_MSR_EPT_VPID_CAP     0x0000048CU
#define ARKM_X7_MSR_EFER             0xC0000080U
#define ARKM_X7_MSR_VM_HSAVE_PA      0xC0010117U
#define ARKM_X7_MSR_VM_CR            0xC0010114U
#define ARKM_X7_EFER_SVME            (1ULL << 12)
#define ARKM_X7_VMCR_SVMDIS          (1ULL << 4)
#define ARKM_X7_VMX_CR0_FIXED0       0x486U
#define ARKM_X7_VMX_CR0_FIXED1       0x487U
#define ARKM_X7_VMX_CR4_FIXED0       0x488U
#define ARKM_X7_VMX_CR4_FIXED1       0x489U
#define ARKM_X7_VMX_PIN_BASED        0x4000U
#define ARKM_X7_VMX_PROC_BASED       0x4002U
#define ARKM_X7_VMX_EXIT_CTLS        0x400CU
#define ARKM_X7_VMX_ENTRY_CTLS       0x4012U
#define ARKM_X7_VMX_PROC2_CTLS       0x401EU
#define ARKM_X7_VMX_LDTR_AR           0x4820U
