    if(!arkm_x7_vcpu.vmcb){ arkm_x7_vcpu.vmcb=pmm_alloc_page(); }
    if(!arkm_x7_vcpu.vmxon||!arkm_x7_vcpu.vmcb) return 0;
    arkm_x7_vcpu.vmxon_phys=(uint64_t)arkm_x7_vcpu.vmxon;
    arkm_x7_vcpu.vmcb_phys=(uint64_t)arkm_x7_vcpu.vmcb;
    memset(arkm_x7_vcpu.vmxon,0,PAGE_SIZE);
    memset(arkm_x7_vcpu.vmcb,0,PAGE_SIZE);
    *(uint32_t*)arkm_x7_vcpu.vmxon=(uint32_t)basic & ARKM_X7_VMX_VMXON_REV_MASK;
    *(uint32_t*)arkm_x7_vcpu.vmcb=(uint32_t)basic & ARKM_X7_VMX_VMXON_REV_MASK;
