    if(!arkm_x7_vcpu.vmx_active){
        uint8_t fail=0;
        __asm__ volatile("vmxon %1; setna %0" : "=r"(fail) : "m"(arkm_x7_vcpu.vmxon_phys) : "cc","memory");
        if(fail) { arkm_x7_vcpu.vmx_failed=1; return 0; }
        arkm_x7_vcpu.vmx_active=1;
    }
    return 1;
