    arkm_x7_vcpu.guest_code=code; arkm_x7_vcpu.guest_stack=stack;
    arkm_x7_vcpu.vmcb_phys=(uint64_t)vmcb; arkm_x7_vcpu.hsave_phys=(uint64_t)hsave;

    typedef struct { uint16_t sel,attr; uint32_t limit; uint64_t base; } vmseg_t;
    vmseg_t* es=(vmseg_t*)((uint8_t*)vmcb+0x400U);
    vmseg_t* cs=(vmseg_t*)((uint8_t*)vmcb+0x410U);
    vmseg_t* ss=(vmseg_t*)((uint8_t*)vmcb+0x420U);
    vmseg_t* ds=(vmseg_t*)((uint8_t*)vmcb+0x430U);
    vmseg_t* fs=(vmseg_t*)((uint8_t*)vmcb+0x440U);
    vmseg_t* gs=(vmseg_t*)((uint8_t*)vmcb+0x450U);
    vmseg_t* gd=(vmseg_t*)((uint8_t*)vmcb+0x460U);
    vmseg_t* id=(vmseg_t*)((uint8_t*)vmcb+0x480U);
    vmseg_t* tr=(vmseg_t*)((uint8_t*)vmcb+0x490U);
    memset(es,0,sizeof(*es));
