static void arkm_x7_write_dec_line(const char* label,uint32_t value){char n[24];itoa_dec(value,n);arkm6_luna_shell_line(label,n);}

/* Keep the old boot behavior untouched; ARKM-X7 runtime is explicit/lazy. */


// ==========================================
// 6. ARKM USER-SPACE C LIBRARY (LIBC) STUBS
// ==========================================
static inline uint64_t arkm_syscall(uint64_t sys_num, uint64_t param) {
    uint64_t ret;
    __asm__ volatile ("int $0x80" : "=a" (ret) : "D" (sys_num), "S" (param) : "memory");
    return ret;
}

int socket(int domain, int type, int protocol) {
    (void)domain; (void)type; (void)protocol;
    return (int)arkm_syscall(11, 0);
}

int bind(int sockfd, uint16_t port) {
    (void)sockfd;
    return (int)arkm_syscall(12, (uint64_t)port);
}

int listen(int sockfd, int backlog) {
    (void)sockfd;
    return (int)arkm_syscall(13, (uint64_t)backlog);
}

int accept(int sockfd) {
    (void)sockfd;
    return (int)arkm_syscall(16, (uint64_t)sockfd);
}

ssize_t recv(int sockfd, void *buf, size_t len, int flags) {
    (void)sockfd; (void)len; (void)flags;
    return (ssize_t)arkm_syscall(17, (uint64_t)buf);
}

ssize_t send(int sockfd, const void *buf, size_t len, int flags) {
    sys_send_args_t args = {sockfd, buf, len, flags};
    return (ssize_t)arkm_syscall(19, (uint64_t)&args);
}

int open(const char *pathname, int flags) {
    (void)flags;
    return (int)arkm_syscall(21, (uint64_t)pathname);
}

ssize_t read(int fd, void *buf, size_t count) {
    sys_read_args_t args = {fd, buf, count};
    return (ssize_t)arkm_syscall(22, (uint64_t)&args);
}

int close(int fd) {
    return (int)arkm_syscall(23, (uint64_t)fd);
}

void* malloc(size_t size) {
    static uint64_t current_brk = 0;
    if (current_brk == 0) {
        current_brk = arkm_syscall(18, 0);
    }
    uint64_t allocated_mem = current_brk;
    current_brk += size;
    arkm_syscall(18, current_brk);
    return (void*)allocated_mem;
}

void printf(const char* format) {
    ui_text_t txt;
    txt.x = 20;
    txt.y = 40;
    txt.color = 0xFFFFFF;
    int i = 0;
    while(format[i] && i < 63) { txt.text[i] = format[i]; i++; }
    txt.text[i] = '\0';
    arkm_syscall(10, (uint64_t)&txt);
}


