int getpid(void) { return (int)arkm_syscall(46, 0); }
int getuid(void) { return (int)arkm_syscall(47, 0); }
int getgid(void) { return (int)arkm_syscall(48, 0); }
int getppid(void) { return (int)arkm_syscall(53, 0); }

int kill(int pid, int sig) {
    arkm6_proc_args_t a;
    memset(&a, 0, sizeof(a));
    a.pid = (uint32_t)pid;
    a.sig_or_status = (uint32_t)sig;
    return (int)arkm_syscall(54, (uint64_t)&a);
}

int waitpid(int pid, int* status, int options) {
    arkm6_proc_args_t a;
    memset(&a, 0, sizeof(a));
    a.pid = (uint32_t)pid;
    a.options = (uint32_t)options;
    int rc = (int)arkm_syscall(55, (uint64_t)&a);
    if (rc >= 0 && status) *status = (int)a.sig_or_status;
    return rc;
}

int pipe(int fds[2]) {
    if (!fds) return -1;
    return (int)arkm_syscall(56, (uint64_t)fds);
}

ssize_t write(int fd, const void* buffer, size_t length) {
    arkm6_io_args_t a;
    a.fd = fd; a.buffer = (void*)buffer; a.length = (uint32_t)length;
    return (ssize_t)arkm_syscall(58, (uint64_t)&a);
}

void* mmap(void* addr, size_t length, int prot, int flags, int fd, long offset) {
    (void)fd; (void)offset;
    arkm6_vm_args_t a;
    a.op = ARKM6_VM_MAP; a.addr = (uint64_t)addr; a.length = length;
    a.prot = (uint32_t)prot; a.flags = (uint32_t)flags;
    uint64_t ret = arkm_syscall(59, (uint64_t)&a);
    return (ret == (uint64_t)-1) ? (void*)0 : (void*)ret;
}

int munmap(void* addr, size_t length) {
    arkm6_vm_args_t a;
    a.op = ARKM6_VM_UNMAP; a.addr = (uint64_t)addr; a.length = length;
    a.prot = 0; a.flags = 0;
    return (int)arkm_syscall(59, (uint64_t)&a);
}

int mprotect(void* addr, size_t length, int prot) {
    arkm6_vm_args_t a;
    a.op = ARKM6_VM_PROTECT; a.addr = (uint64_t)addr; a.length = length;
    a.prot = (uint32_t)prot; a.flags = 0;
    return (int)arkm_syscall(59, (uint64_t)&a);
}

uint64_t luna_capabilities(void) {
    arkm6_cap_args_t a;
    a.op = ARKM6_CAP_QUERY; a.value = 0;
    return arkm_syscall(60, (uint64_t)&a);
}

int luna_sched_setaffinity(int pid, uint64_t cpu_mask) {
    arkm6_sched_policy_args_t a;
    memset(&a, 0, sizeof(a));
    a.op = 1U; a.pid = (uint32_t)pid; a.cpu_mask = cpu_mask;
    return (int)arkm_syscall(64, (uint64_t)&a);
}

int luna_sched_set_amp_role(int pid, uint32_t role) {
    arkm6_sched_policy_args_t a;
    memset(&a, 0, sizeof(a));
    a.op = 2U; a.pid = (uint32_t)pid; a.amp_role = role;
    return (int)arkm_syscall(64, (uint64_t)&a);
}

int luna_sched_get_policy(int pid, arkm6_sched_policy_args_t* out) {
    if (!out) return -1;
    memset(out, 0, sizeof(*out));
    out->op = 0U; out->pid = (uint32_t)pid;
    return (int)arkm_syscall(64, (uint64_t)out);
}

int luna_event_next(arkm6_event_t* out) {
    if (!out) return -1;
    arkm6_event_read_args_t a;
    memset(&a, 0, sizeof(a));
    int rc = (int)arkm_syscall(65, (uint64_t)&a);
    if (rc == 0) *out = a.event;
    return rc;
}

int luna_audit_latest(arkm6_audit_event_t* out) {
    if (!out) return -1;
    arkm6_audit_read_args_t a;
    memset(&a, 0, sizeof(a));
    int rc = (int)arkm_syscall(66, (uint64_t)&a);
    if (rc == 0) *out = a.event;
    return rc;
}

int chdir(const char* path) {
    arkm6_path_args_t a;
    memset(&a, 0, sizeof(a));
    if (!path) return -1;
    size_t i = 0; while (path[i] && i + 1U < sizeof(a.path)) { a.path[i] = path[i]; i++; }
    a.path[i] = '\0';
    return (int)arkm_syscall(67, (uint64_t)&a);
}

char* getcwd(char* buf, size_t size) {
    if (!buf || size == 0 || size < ARKM6_MAX_CWD) return (char*)0;
    arkm6_path_args_t a;
    memset(&a, 0, sizeof(a));
    if (arkm_syscall(68, (uint64_t)&a) != 0) return (char*)0;
    memcpy(buf, a.path, size < sizeof(a.path) ? size : sizeof(a.path));
    buf[size - 1U] = '\0';
    return buf;
}

uint64_t luna_fs_free_bytes(void) {
    return arkm_syscall(69, 0);
}

